const DM_E2EE_VERSION = 1;
const DM_E2EE_ALGORITHM = 'ECDH-P256-HKDF-SHA256-AES-GCM';
const DM_E2EE_MISSING_KEY_TOAST = 'User has not updated their app - They do not have a Encrypted End-to-End Key';
const DM_E2EE_OWN_KEY_TOAST = 'You DO NOT HAVE A End-to-End Encryption KEY.\nThe user you are trying to message has a End-to-End Encryption.\nPlease sign out, and sign back in to generate a E2EE Key';
const DM_E2EE_PRIVATE_KEY_MISSING_TOAST = 'Your End-to-End Encryption private key is missing on this device.\nYour encrypted chat history is still saved, but this browser cannot decrypt it.\nUse the original browser/device that created the key, or restore from a future key backup.';
const DM_E2EE_INFO_PREFIX = 'ScreenList DM E2EE v1';
const DM_E2EE_PUBLIC_FIELD = 'dmEncryptionPublicKey';
const DM_E2EE_KEY_VERSION_FIELD = 'dmEncryptionKeyVersion';
const DM_E2EE_LOCAL_PUBLIC_PREFIX = 'screenlist_dm_e2ee_public_';
const DM_E2EE_LOCAL_PRIVATE_PREFIX = 'screenlist_dm_e2ee_private_jwk_';
const DM_E2EE_BACKUP_FIELD = 'dmEncryptionKeyBackup';
const DM_E2EE_BACKUP_VERSION = 1;
const DM_E2EE_BACKUP_ITERATIONS = 240000;
const DM_E2EE_RECOVERY_NOTICE_PREFIX = 'screenlist_dm_e2ee_recovery_notice_';
let dmEncryptionReadyPromise = null;
let dmE2eeRecoveryModalPromise = null;
const dmE2eeDecryptCache = new Map();

function hasDirectMessageCryptoSupport() {
  return !!(window.crypto && window.crypto.subtle && window.TextEncoder && window.TextDecoder);
}

function dmE2eeEncodeText(value = '') {
  return new TextEncoder().encode(String(value || ''));
}

function dmE2eeDecodeText(value) {
  return new TextDecoder().decode(value);
}

function dmE2eeBytesToBase64(bytes) {
  const chunkSize = 0x8000;
  let binary = '';
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
  for (let i = 0; i < arr.length; i += chunkSize) {
    binary += String.fromCharCode.apply(null, arr.slice(i, i + chunkSize));
  }
  return btoa(binary);
}

function dmE2eeBase64ToBytes(value = '') {
  const binary = atob(String(value || ''));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function dmE2eeCanonicalJson(value) {
  if (!value || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(dmE2eeCanonicalJson).join(',')}]`;
  return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${dmE2eeCanonicalJson(value[key])}`).join(',')}}`;
}

async function dmE2eeSha256Base64Url(value = '') {
  const digest = await crypto.subtle.digest('SHA-256', dmE2eeEncodeText(value));
  return dmE2eeBytesToBase64(new Uint8Array(digest)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function getDmE2eeRecoveryNoticeKey(uid = '') {
  return DM_E2EE_RECOVERY_NOTICE_PREFIX + String(uid || 'anon');
}

function hasSeenDmE2eeRecoveryNotice(uid = '') {
  try { return localStorage.getItem(getDmE2eeRecoveryNoticeKey(uid)) === '1'; }
  catch (error) { return false; }
}

function markDmE2eeRecoveryNoticeSeen(uid = '') {
  try { localStorage.setItem(getDmE2eeRecoveryNoticeKey(uid), '1'); } catch (error) {}
}

function getDmE2eeRecoveryBackupFromUserData(userData = {}) {
  const backup = userData?.[DM_E2EE_BACKUP_FIELD] || userData?.dmE2eeKeyBackup || null;
  if (!backup || typeof backup !== 'object') return null;
  if (!backup.salt || !backup.iv || !backup.ciphertext) return null;
  return backup;
}

async function deriveDmE2eeRecoveryAesKey(passphrase = '', saltBase64 = '', iterations = DM_E2EE_BACKUP_ITERATIONS) {
  const password = String(passphrase || '');
  if (!password || !saltBase64) throw new Error('Missing Shelfd Secure Key password');
  const keyMaterial = await crypto.subtle.importKey('raw', dmE2eeEncodeText(password), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', hash: 'SHA-256', salt: dmE2eeBase64ToBytes(saltBase64), iterations: Math.max(120000, Number(iterations || DM_E2EE_BACKUP_ITERATIONS)) },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

async function buildDmE2eePrivateKeyBackup(privateJwk = null, passphrase = '') {
  if (!privateJwk || !privateJwk.d) throw new Error('Missing private key to back up');
  const cleanPassphrase = String(passphrase || '');
  if (cleanPassphrase.length < 6) throw new Error('Shelfd Secure Key password must be at least 6 characters');
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const saltBase64 = dmE2eeBytesToBase64(salt);
  const key = await deriveDmE2eeRecoveryAesKey(cleanPassphrase, saltBase64, DM_E2EE_BACKUP_ITERATIONS);
  const ciphertext = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, additionalData: dmE2eeEncodeText(`${DM_E2EE_INFO_PREFIX}|account-key-backup|v${DM_E2EE_BACKUP_VERSION}`) },
    key,
    dmE2eeEncodeText(JSON.stringify(privateJwk))
  );
  return {
    v: DM_E2EE_BACKUP_VERSION,
    alg: 'AES-GCM-256',
    kdf: 'PBKDF2-SHA256',
    iterations: DM_E2EE_BACKUP_ITERATIONS,
    salt: saltBase64,
    iv: dmE2eeBytesToBase64(iv),
    ciphertext: dmE2eeBytesToBase64(new Uint8Array(ciphertext)),
    createdAtMs: Date.now()
  };
}

async function decryptDmE2eePrivateKeyBackup(backup = null, passphrase = '') {
  if (!backup || !backup.salt || !backup.iv || !backup.ciphertext) throw new Error('Missing Shelfd Secure Key backup');
  const key = await deriveDmE2eeRecoveryAesKey(passphrase, backup.salt, backup.iterations || DM_E2EE_BACKUP_ITERATIONS);
  const decrypted = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: dmE2eeBase64ToBytes(backup.iv), additionalData: dmE2eeEncodeText(`${DM_E2EE_INFO_PREFIX}|account-key-backup|v${backup.v || DM_E2EE_BACKUP_VERSION}`) },
    key,
    dmE2eeBase64ToBytes(backup.ciphertext)
  );
  const privateJwk = JSON.parse(dmE2eeDecodeText(decrypted));
  if (!privateJwk || privateJwk.kty !== 'EC' || privateJwk.crv !== 'P-256' || !privateJwk.d) throw new Error('Invalid restored private key');
  return privateJwk;
}

async function saveDmE2eeRecoveryBackup(uid = '', privateJwk = null, passphrase = '') {
  if (!uid || !privateJwk) return null;
  const backup = await buildDmE2eePrivateKeyBackup(privateJwk, passphrase);
  await db.collection('users').doc(uid).set({
    [DM_E2EE_BACKUP_FIELD]: backup,
    dmEncryptionBackupEnabled: true,
    dmEncryptionBackupUpdatedAtMs: Date.now()
  }, { merge: true });
  usersMap[uid] = {
    ...(usersMap[uid] || {}),
    uid,
    [DM_E2EE_BACKUP_FIELD]: backup,
    dmEncryptionBackupEnabled: true,
    dmEncryptionBackupUpdatedAtMs: Date.now()
  };
  markDmE2eeRecoveryNoticeSeen(uid);
  return backup;
}

function closeDmE2eeRecoveryModal() {
  const modal = document.getElementById('dm-e2ee-recovery-modal');
  if (!modal) return;
  modal.classList.remove('open');
  setTimeout(() => modal.remove(), 180);
}

function showDmE2eeRecoveryPasswordModal(mode = 'unlock', options = {}) {
  if (dmE2eeRecoveryModalPromise) return dmE2eeRecoveryModalPromise;
  const isSetup = mode === 'setup';
  const isReset = mode === 'reset';
  dmE2eeRecoveryModalPromise = new Promise(resolve => {
    const existing = document.getElementById('dm-e2ee-recovery-modal');
    if (existing) existing.remove();
    const overlay = document.createElement('div');
    overlay.id = 'dm-e2ee-recovery-modal';
    overlay.className = 'dm-e2ee-recovery-modal';
    const title = isSetup ? 'Create your Shelfd Secure Key' : (isReset ? 'Reset encrypted messages key?' : 'Unlock encrypted messages');
    const copy = isSetup
      ? 'Create one password to restore your encrypted messages on any phone, desktop, browser, or Home Screen app. Shelfd never saves this password.'
      : isReset
        ? 'This device cannot find your old private key and no encrypted backup exists yet. New messages can work after a reset, but older encrypted messages may stay locked on this device.'
        : 'Enter your Shelfd Secure Key password to restore your private key on this device and unlock your chat history.';
    overlay.innerHTML = `
      <div class="dm-e2ee-recovery-card" role="dialog" aria-modal="true" aria-label="${escAttr(title)}">
        <button class="dm-e2ee-recovery-x" type="button" aria-label="Close">×</button>
        <div class="dm-e2ee-recovery-kicker">E2EE</div>
        <h3>${escHtml(title)}</h3>
        <p>${escHtml(copy)}</p>
        ${isReset ? '' : `
          <label class="dm-e2ee-recovery-label">Shelfd Secure Key password</label>
          <input class="dm-e2ee-recovery-input" id="dm-e2ee-recovery-pass" type="password" autocomplete="current-password" placeholder="Enter password">
          ${isSetup ? `<input class="dm-e2ee-recovery-input" id="dm-e2ee-recovery-confirm" type="password" autocomplete="new-password" placeholder="Confirm password">` : ''}
          <div class="dm-e2ee-recovery-error" id="dm-e2ee-recovery-error"></div>
        `}
        <div class="dm-e2ee-recovery-actions">
          <button class="dm-e2ee-recovery-secondary" type="button" id="dm-e2ee-recovery-cancel">${isReset ? 'Cancel' : 'Not now'}</button>
          <button class="dm-e2ee-recovery-primary" type="button" id="dm-e2ee-recovery-submit">${isSetup ? 'Save Secure Key' : isReset ? 'Create New Key' : 'Unlock'}</button>
        </div>
      </div>`;
    const finish = value => {
      closeDmE2eeRecoveryModal();
      dmE2eeRecoveryModalPromise = null;
      resolve(value);
    };
    overlay.querySelector('.dm-e2ee-recovery-x')?.addEventListener('click', () => finish(null));
    overlay.querySelector('#dm-e2ee-recovery-cancel')?.addEventListener('click', () => finish(null));
    overlay.addEventListener('click', event => { if (event.target === overlay) finish(null); });
    overlay.querySelector('#dm-e2ee-recovery-submit')?.addEventListener('click', () => {
      if (isReset) { finish('__RESET__'); return; }
      const pass = String(overlay.querySelector('#dm-e2ee-recovery-pass')?.value || '');
      const confirm = String(overlay.querySelector('#dm-e2ee-recovery-confirm')?.value || '');
      const error = overlay.querySelector('#dm-e2ee-recovery-error');
      if (pass.length < 6) {
        if (error) error.textContent = 'Use at least 6 characters.';
        return;
      }
      if (isSetup && pass !== confirm) {
        if (error) error.textContent = 'Passwords do not match.';
        return;
      }
      finish(pass);
    });
    overlay.querySelectorAll('input').forEach(input => {
      input.addEventListener('keydown', event => {
        if (event.key === 'Enter') overlay.querySelector('#dm-e2ee-recovery-submit')?.click();
      });
    });
    document.body.appendChild(overlay);
    requestAnimationFrame(() => {
      overlay.classList.add('open');
      overlay.querySelector('#dm-e2ee-recovery-pass')?.focus?.();
    });
  });
  return dmE2eeRecoveryModalPromise;
}

async function restoreDmE2eePrivateKeyFromBackup(uid = '', backup = null) {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const passphrase = await showDmE2eeRecoveryPasswordModal('unlock');
    if (!passphrase) return null;
    try {
      const privateJwk = await decryptDmE2eePrivateKeyBackup(backup, passphrase);
      const privateKey = await importDmE2eePrivateKey(privateJwk);
      await storeDmE2eePrivateKey(uid, privateKey, privateJwk);
      markDmE2eeRecoveryNoticeSeen(uid);
      showToast('Encrypted messages unlocked', { durationMs: 1800 });
      return { privateKey, privateJwk };
    } catch (error) {
      console.warn('Shelfd Secure Key unlock failed:', error);
      showToast(attempt >= 2 ? 'Could not unlock encrypted messages' : 'Wrong Shelfd Secure Key password', { durationMs: 2200 });
    }
  }
  return null;
}

async function maybeSetupDmE2eeRecoveryBackup(uid = '', privateJwk = null, userData = {}, options = {}) {
  if (!uid || !privateJwk || options.silent || getDmE2eeRecoveryBackupFromUserData(userData) || hasSeenDmE2eeRecoveryNotice(uid)) return null;
  const passphrase = await showDmE2eeRecoveryPasswordModal('setup');
  if (!passphrase) {
    markDmE2eeRecoveryNoticeSeen(uid);
    return null;
  }
  try {
    const backup = await saveDmE2eeRecoveryBackup(uid, privateJwk, passphrase);
    showToast('Shelfd Secure Key saved', { durationMs: 1800 });
    return backup;
  } catch (error) {
    console.error('Could not save Shelfd Secure Key backup:', error);
    showToast('Could not save Secure Key backup', { durationMs: 2200 });
    return null;
  }
}

function isValidDmEncryptionPublicKey(key = null) {
  return !!(key && key.kty === 'EC' && key.crv === 'P-256' && key.x && key.y);
}

function getDmE2eeLocalPublicKey(uid = '') {
  try {
    const raw = localStorage.getItem(DM_E2EE_LOCAL_PUBLIC_PREFIX + uid);
    const parsed = raw ? JSON.parse(raw) : null;
    return isValidDmEncryptionPublicKey(parsed) ? parsed : null;
  } catch (error) {
    return null;
  }
}

function setDmE2eeLocalPublicKey(uid = '', publicKey = null) {
  if (!uid || !isValidDmEncryptionPublicKey(publicKey)) return;
  try { localStorage.setItem(DM_E2EE_LOCAL_PUBLIC_PREFIX + uid, JSON.stringify(publicKey)); } catch (error) {}
}

function getDmE2eeLocalPrivateJwk(uid = '') {
  try {
    const raw = localStorage.getItem(DM_E2EE_LOCAL_PRIVATE_PREFIX + uid);
    const parsed = raw ? JSON.parse(raw) : null;
    return parsed && parsed.kty === 'EC' && parsed.crv === 'P-256' && parsed.d ? parsed : null;
  } catch (error) {
    return null;
  }
}

function setDmE2eeLocalPrivateJwk(uid = '', privateKey = null) {
  if (!uid || !privateKey) return;
  try { localStorage.setItem(DM_E2EE_LOCAL_PRIVATE_PREFIX + uid, JSON.stringify(privateKey)); } catch (error) {}
}

function openDmE2eeKeyDb() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error('IndexedDB unavailable'));
      return;
    }
    const req = indexedDB.open('screenlist-dm-e2ee-v1', 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains('keys')) db.createObjectStore('keys');
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error('IndexedDB open failed'));
  });
}

async function dmE2eeIdbGet(key = '') {
  const db = await openDmE2eeKeyDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('keys', 'readonly');
    const req = tx.objectStore('keys').get(key);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error || new Error('IndexedDB read failed'));
    tx.oncomplete = () => db.close();
    tx.onerror = () => { try { db.close(); } catch (error) {} };
  });
}

async function dmE2eeIdbSet(key = '', value = null) {
  const db = await openDmE2eeKeyDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('keys', 'readwrite');
    tx.objectStore('keys').put(value, key);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { try { db.close(); } catch (error) {}; reject(tx.error || new Error('IndexedDB write failed')); };
  });
}

async function importDmE2eePrivateKey(privateJwk) {
  return crypto.subtle.importKey(
    'jwk',
    privateJwk,
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    ['deriveBits']
  );
}

async function importDmE2eePublicKey(publicJwk) {
  return crypto.subtle.importKey(
    'jwk',
    publicJwk,
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    []
  );
}

async function loadDmE2eePrivateKey(uid = '') {
  if (!uid || !hasDirectMessageCryptoSupport()) return null;
  try {
    const key = await dmE2eeIdbGet('ecdh-private-' + uid);
    if (key) return key;
  } catch (error) {}
  const fallbackJwk = getDmE2eeLocalPrivateJwk(uid);
  if (!fallbackJwk) return null;
  const restoredKey = await importDmE2eePrivateKey(fallbackJwk);
  try { await dmE2eeIdbSet('ecdh-private-' + uid, restoredKey); } catch (error) {}
  return restoredKey;
}

async function storeDmE2eePrivateKey(uid = '', privateKey = null, privateJwk = null) {
  if (!uid || !privateKey) return;
  if (privateJwk) setDmE2eeLocalPrivateJwk(uid, privateJwk);
  try {
    await dmE2eeIdbSet('ecdh-private-' + uid, privateKey);
    return;
  } catch (error) {
    console.warn('Secure Direct Message IndexedDB key storage failed; using local private-key backup only:', error);
  }
}

async function createDmE2eeKeyPair(uid = '') {
  const generated = await crypto.subtle.generateKey(
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    ['deriveBits']
  );
  const publicJwk = await crypto.subtle.exportKey('jwk', generated.publicKey);
  const privateJwk = await crypto.subtle.exportKey('jwk', generated.privateKey);
  const privateKey = await importDmE2eePrivateKey(privateJwk);
  setDmE2eeLocalPublicKey(uid, publicJwk);
  await storeDmE2eePrivateKey(uid, privateKey, privateJwk);
  return { privateKey, publicJwk };
}

async function ensureDirectMessageEncryptionReady(uid = currentUser?.uid || '', options = {}) {
  if (!uid || !currentUser || uid !== currentUser.uid) return null;
  if (!hasDirectMessageCryptoSupport()) throw new Error('This browser does not support Web Crypto E2EE');
  if (dmEncryptionReadyPromise) return dmEncryptionReadyPromise;
  const opts = { silent: false, ...options };
  dmEncryptionReadyPromise = (async () => {
    let privateKey = await loadDmE2eePrivateKey(uid);
    let privateJwk = getDmE2eeLocalPrivateJwk(uid);
    let publicJwk = getDmE2eeLocalPublicKey(uid);
    let userData = {};
    let remotePublicJwk = null;
    let recoveryBackup = null;
    try {
      const snap = await db.collection('users').doc(uid).get();
      userData = snap.exists ? (snap.data() || {}) : {};
      remotePublicJwk = userData?.[DM_E2EE_PUBLIC_FIELD] || null;
      if (!isValidDmEncryptionPublicKey(remotePublicJwk)) remotePublicJwk = null;
      recoveryBackup = getDmE2eeRecoveryBackupFromUserData(userData);
    } catch (error) {
      console.warn('Could not read existing DM encryption profile:', error);
    }

    if (!isValidDmEncryptionPublicKey(publicJwk) && remotePublicJwk) {
      publicJwk = remotePublicJwk;
      setDmE2eeLocalPublicKey(uid, publicJwk);
    }

    if (!privateKey && recoveryBackup) {
      if (opts.silent) return null;
      const restored = await restoreDmE2eePrivateKeyFromBackup(uid, recoveryBackup);
      if (restored?.privateKey) {
        privateKey = restored.privateKey;
        privateJwk = restored.privateJwk;
      } else {
        const error = new Error('Shelfd Secure Key password required to unlock encrypted messages.');
        error.dmE2eeOwnKeyMissing = true;
        error.dmE2eePrivateKeyMissing = true;
        error.dmE2eeNeedsUnlock = true;
        throw error;
      }
    }

    if (!privateKey && remotePublicJwk && !recoveryBackup) {
      if (opts.silent) return null;
      const resetChoice = await showDmE2eeRecoveryPasswordModal('reset');
      if (resetChoice !== '__RESET__') {
        const error = new Error('Encrypted message key reset was cancelled.');
        error.dmE2eeOwnKeyMissing = true;
        error.dmE2eePrivateKeyMissing = true;
        throw error;
      }
      publicJwk = null;
    }

    if (!privateKey || !isValidDmEncryptionPublicKey(publicJwk)) {
      const pair = await createDmE2eeKeyPair(uid);
      privateKey = pair.privateKey;
      privateJwk = getDmE2eeLocalPrivateJwk(uid);
      publicJwk = pair.publicJwk;
    }

    const fingerprint = await dmE2eeSha256Base64Url(dmE2eeCanonicalJson(publicJwk));
    const patch = {
      [DM_E2EE_PUBLIC_FIELD]: publicJwk,
      [DM_E2EE_KEY_VERSION_FIELD]: DM_E2EE_VERSION,
      dmEncryptionFingerprint: fingerprint,
      dmEncryptionAlgorithm: DM_E2EE_ALGORITHM,
      dmEncryptionUpdatedAtMs: Date.now()
    };
    await db.collection('users').doc(uid).set(patch, { merge: true });
    usersMap[uid] = {
      ...(usersMap[uid] || {}),
      uid,
      ...patch,
      ...(recoveryBackup ? { [DM_E2EE_BACKUP_FIELD]: recoveryBackup, dmEncryptionBackupEnabled: true } : {})
    };

    if (privateJwk) await maybeSetupDmE2eeRecoveryBackup(uid, privateJwk, { ...userData, ...(recoveryBackup ? { [DM_E2EE_BACKUP_FIELD]: recoveryBackup } : {}) }, opts);
    return { privateKey, publicJwk, fingerprint };
  })().finally(() => {
    dmEncryptionReadyPromise = null;
  });
  return dmEncryptionReadyPromise;
}

async function getDirectMessagePublicKeyForUid(uid = '') {
  if (!uid) return null;
  if (uid === currentUser?.uid) {
    const ready = await ensureDirectMessageEncryptionReady(uid);
    return ready?.publicJwk || null;
  }
  const cached = usersMap[uid]?.[DM_E2EE_PUBLIC_FIELD];
  if (isValidDmEncryptionPublicKey(cached)) return cached;
  const snap = await db.collection('users').doc(uid).get();
  const data = snap.exists ? { uid: snap.id, ...(snap.data() || {}) } : null;
  if (data?.uid) usersMap[uid] = { ...(usersMap[uid] || {}), ...data };
  const key = data?.[DM_E2EE_PUBLIC_FIELD];
  return isValidDmEncryptionPublicKey(key) ? key : null;
}

function getDmE2eePairInfo(threadId = '', senderUid = '', recipientUid = '') {
  const pair = [senderUid, recipientUid].map(uid => String(uid || '').trim()).sort().join('|');
  return `${DM_E2EE_INFO_PREFIX}|thread:${threadId}|pair:${pair}`;
}

async function deriveDmE2eeWrapKey(privateKey, publicJwk, threadId = '', senderUid = '', recipientUid = '') {
  const publicKey = await importDmE2eePublicKey(publicJwk);
  const sharedBits = await crypto.subtle.deriveBits({ name: 'ECDH', public: publicKey }, privateKey, 256);
  const hkdfKey = await crypto.subtle.importKey('raw', sharedBits, 'HKDF', false, ['deriveKey']);
  const salt = await crypto.subtle.digest('SHA-256', dmE2eeEncodeText(`${DM_E2EE_INFO_PREFIX}|salt|${threadId}`));
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt,
      info: dmE2eeEncodeText(getDmE2eePairInfo(threadId, senderUid, recipientUid))
    },
    hkdfKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

function getDmE2eeAdditionalData(threadId = '', messageId = '', part = '') {
  return dmE2eeEncodeText(`${DM_E2EE_INFO_PREFIX}|${threadId}|${messageId}|${part}`);
}

function getDirectMessagePlainPayload(message = {}) {
  return {
    text: String(message.text || ''),
    shareMedia: message.shareMedia ? normalizeSharedMediaPayload(message.shareMedia) : null,
    imageData: message.imageData || '',
    imageName: message.imageName || ''
  };
}

async function encryptDirectMessagePayloadForThread(thread = {}, messageId = '', payload = {}) {
  const senderUid = currentUser?.uid || '';
  const participantUids = getDirectMessageParticipantUids(thread);
  if (!senderUid || !participantUids.includes(senderUid)) throw new Error('Missing secure message sender');
  let ready = null;
  try {
    ready = await ensureDirectMessageEncryptionReady(senderUid);
  } catch (error) {
    error.dmE2eeOwnKeyMissing = true;
    throw error;
  }
  if (!ready?.privateKey || !isValidDmEncryptionPublicKey(ready.publicJwk)) {
    const error = new Error('Your E2EE key is not ready on this device.');
    error.dmE2eeOwnKeyMissing = true;
    throw error;
  }
  const recipientPublicKeys = {};
  await Promise.all(participantUids.map(async uid => {
    const publicKey = await getDirectMessagePublicKeyForUid(uid);
    if (!isValidDmEncryptionPublicKey(publicKey)) {
      const profile = getDirectMessageProfile(uid, usersMap[uid] || thread.participants?.[uid] || {});
      const name = getDisplayName(profile, 'A participant');
      const error = new Error(`${name} needs to open the updated app once before secure messages can be sent.`);
      error.dmE2eeMissingPublicKey = true;
      throw error;
    }
    recipientPublicKeys[uid] = publicKey;
  }));

  const contentKey = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
  const contentKeyRaw = new Uint8Array(await crypto.subtle.exportKey('raw', contentKey));
  const payloadIv = crypto.getRandomValues(new Uint8Array(12));
  const payloadBytes = dmE2eeEncodeText(JSON.stringify({
    text: String(payload.text || '').slice(0, 1000),
    shareMedia: payload.shareMedia ? normalizeSharedMediaPayload(payload.shareMedia) : null,
    imageData: payload.imageData || '',
    imageName: payload.imageName || ''
  }));
  const ciphertext = new Uint8Array(await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: payloadIv, additionalData: getDmE2eeAdditionalData(thread.id, messageId, 'payload') },
    contentKey,
    payloadBytes
  ));
  const boxes = {};
  await Promise.all(participantUids.map(async uid => {
    const wrapKey = await deriveDmE2eeWrapKey(ready.privateKey, recipientPublicKeys[uid], thread.id, senderUid, uid);
    const boxIv = crypto.getRandomValues(new Uint8Array(12));
    const wrappedKey = new Uint8Array(await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: boxIv, additionalData: getDmE2eeAdditionalData(thread.id, messageId, 'box:' + uid) },
      wrapKey,
      contentKeyRaw
    ));
    boxes[uid] = {
      iv: dmE2eeBytesToBase64(boxIv),
      key: dmE2eeBytesToBase64(wrappedKey)
    };
  }));

  return {
    isEncrypted: true,
    dmE2ee: {
      v: DM_E2EE_VERSION,
      alg: DM_E2EE_ALGORITHM,
      senderUid,
      senderPublicKey: ready.publicJwk,
      iv: dmE2eeBytesToBase64(payloadIv),
      ciphertext: dmE2eeBytesToBase64(ciphertext),
      boxes
    }
  };
}

async function decryptDirectMessagePayload(threadId = '', message = {}) {
  if (!message?.isEncrypted || !message?.dmE2ee) return getDirectMessagePlainPayload(message);
  const cacheKey = `${threadId}|${message.id || ''}|${message.dmE2ee.ciphertext || ''}`;
  if (dmE2eeDecryptCache.has(cacheKey)) return dmE2eeDecryptCache.get(cacheKey);
  try {
    const uid = currentUser?.uid || '';
    const envelope = message.dmE2ee || {};
    const box = envelope.boxes?.[uid];
    if (!uid || !box) throw new Error('No encrypted key box for this device');
    let privateKey = await loadDmE2eePrivateKey(uid);
    if (!privateKey) {
      const ready = await ensureDirectMessageEncryptionReady(uid);
      privateKey = ready?.privateKey || await loadDmE2eePrivateKey(uid);
    }
    if (!privateKey) throw new Error('Private key not found on this device');
    const wrapKey = await deriveDmE2eeWrapKey(privateKey, envelope.senderPublicKey, threadId, envelope.senderUid || message.fromUid || '', uid);
    const rawContentKey = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: dmE2eeBase64ToBytes(box.iv), additionalData: getDmE2eeAdditionalData(threadId, message.id || '', 'box:' + uid) },
      wrapKey,
      dmE2eeBase64ToBytes(box.key)
    );
    const contentKey = await crypto.subtle.importKey('raw', rawContentKey, { name: 'AES-GCM' }, false, ['decrypt']);
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: dmE2eeBase64ToBytes(envelope.iv), additionalData: getDmE2eeAdditionalData(threadId, message.id || '', 'payload') },
      contentKey,
      dmE2eeBase64ToBytes(envelope.ciphertext)
    );
    const parsed = JSON.parse(dmE2eeDecodeText(decrypted));
    const payload = {
      text: String(parsed.text || ''),
      shareMedia: parsed.shareMedia ? normalizeSharedMediaPayload(parsed.shareMedia) : null,
      imageData: parsed.imageData || '',
      imageName: parsed.imageName || ''
    };
    dmE2eeDecryptCache.set(cacheKey, payload);
    return payload;
  } catch (error) {
    console.warn('Direct Message decrypt failed:', error);
    return { text: '[Encrypted message locked. Open Messages and enter your Shelfd Secure Key to restore it.]', shareMedia: null, imageData: '', imageName: '', e2eeError: true };
  }
}

function renderDirectMessagePayloadContent(payload = {}, encrypted = false) {
  const normalizedShare = payload.shareMedia ? normalizeSharedMediaPayload(payload.shareMedia) : null;
  const shareHtml = normalizedShare ? renderDirectMessageShareCard({ shareMedia: normalizedShare }) : '';
  const imageHtml = payload.imageData ? `<img class="dm-photo-message" src="${escAttr(payload.imageData)}" alt="${escAttr(payload.imageName || 'Photo message')}" loading="lazy">` : '';
  const textHtml = payload.text ? `<span class="dm-message-text">${escHtml(payload.text || '')}</span>` : '';
  const badgeHtml = encrypted ? '<b class="dm-e2ee-badge" title="End-to-end encrypted">E2EE</b>' : '';
  const fallbackHtml = encrypted && !shareHtml && !imageHtml && !textHtml
    ? '<span class="dm-message-text dm-e2ee-loading">Secure message</span>'
    : '';
  return `${shareHtml}${imageHtml}${textHtml}${fallbackHtml}${badgeHtml}`;
}

function renderDirectMessageEncryptedContent(message = {}, threadId = '') {
  return `<div class="dm-e2ee-content" data-dm-e2ee-thread-id="${escAttr(threadId)}" data-dm-e2ee-message-id="${escAttr(message.id || '')}"><span class="dm-message-text dm-e2ee-loading">Decrypting secure message...</span><b class="dm-e2ee-badge" title="End-to-end encrypted">E2EE</b></div>`;
}

async function hydrateDirectMessageEncryptionInView(threadId = '') {
  const thread = dmThreadMap[threadId];
  if (!thread) return;
  const messages = Array.isArray(thread.messages) ? thread.messages : [];
  const nodes = Array.from(document.querySelectorAll('[data-dm-e2ee-message-id]'))
    .filter(node => node.dataset.dmE2eeThreadId === threadId);
  await Promise.all(nodes.map(async node => {
    const message = messages.find(item => String(item.id || '') === String(node.dataset.dmE2eeMessageId || ''));
    if (!message) return;
    const payload = await decryptDirectMessagePayload(threadId, message);
    if (activeDmThreadId !== threadId) return;
    node.innerHTML = renderDirectMessagePayloadContent(payload, true);
    node.classList.toggle('dm-e2ee-error', !!payload.e2eeError);
  }));
}

function normalizeWatchTogetherRequestIds(value) {
  return Array.isArray(value) ? value.map(id => String(id || '').trim()).filter(Boolean) : [];
}

function normalizeWatchTogetherRequestPayloadMap(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.entries(value).reduce((acc, [id, raw]) => {
    const groupId = String(id || raw?.id || '').trim();
    if (!groupId || !raw || typeof raw !== 'object') return acc;
    acc[groupId] = {
      id: groupId,
      ...raw,
      pendingUids: Array.isArray(raw.pendingUids) ? raw.pendingUids.filter(Boolean) : [],
      approvedUids: Array.isArray(raw.approvedUids) ? raw.approvedUids.filter(Boolean) : [],
      participantUids: Array.isArray(raw.participantUids) ? raw.participantUids.filter(Boolean) : [],
      rejectedUids: Array.isArray(raw.rejectedUids) ? raw.rejectedUids.filter(Boolean) : []
    };
    return acc;
  }, {});
}

function getWatchTogetherMirroredPayloadGroups() {
  return [
    ...Object.values(watchTogetherIncomingRequestPayloadMap || {}),
    ...Object.values(watchTogetherOutgoingRequestPayloadMap || {}),
    ...Object.values(watchTogetherApprovedRequestPayloadMap || {})
  ].filter(group => group && group.id);
}

function getWatchTogetherMirrorPayload(group = {}, groupId = '') {
  return {
    id: groupId || group.id || '',
    section: group.section || '',
    title: group.title || '',
    titleKey: group.titleKey || '',
    mediaKey: group.mediaKey || '',
    cover: group.cover || '',
    genre: group.genre || '',
    tmdbId: group.tmdbId || '',
    imdbId: group.imdbId || '',
    librarySection: group.librarySection || group.section || '',
    mediaCategory: group.mediaCategory || group.section || '',
    mode: group.mode === 'planned' ? 'planned' : 'watched',
    ownerUid: group.ownerUid || '',
    participantUids: Array.isArray(group.participantUids) ? group.participantUids.filter(Boolean) : [],
    approvedUids: Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [],
    pendingUids: Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [],
    rejectedUids: Array.isArray(group.rejectedUids) ? group.rejectedUids.filter(Boolean) : [],
    profiles: group.profiles || {},
    status: group.status || 'pending',
    createdAtMs: group.createdAtMs || Date.now(),
    updatedAtMs: Date.now()
  };
}

async function setWatchTogetherRequestMirror(uid = '', direction = 'incoming', groupId = '', payload = {}, options = {}) {
  if (!uid || !groupId) return;
  const isIncoming = direction === 'incoming';
  const idsField = isIncoming ? 'watchTogetherIncomingRequests' : 'watchTogetherOutgoingRequests';
  const mapField = isIncoming ? 'watchTogetherIncomingRequestMap' : 'watchTogetherOutgoingRequestMap';
  const includeInRequestList = options.includeInRequestList !== false;
  await db.collection('users').doc(uid).set({
    [idsField]: includeInRequestList
      ? firebase.firestore.FieldValue.arrayUnion(groupId)
      : firebase.firestore.FieldValue.arrayRemove(groupId),
    [mapField]: { [groupId]: getWatchTogetherMirrorPayload(payload, groupId) }
  }, { merge: true });
}

async function setWatchTogetherApprovedMirror(uid = '', groupId = '', payload = {}) {
  if (!uid || !groupId) return;
  await db.collection('users').doc(uid).set({
    watchTogetherApprovedGroups: firebase.firestore.FieldValue.arrayUnion(groupId),
    watchTogetherApprovedGroupMap: { [groupId]: getWatchTogetherMirrorPayload(payload, groupId) }
  }, { merge: true });
}

async function clearWatchTogetherApprovedMirror(uid = '', groupId = '') {
  if (!uid || !groupId) return;
  const userRef = db.collection('users').doc(uid);
  await userRef.set({ watchTogetherApprovedGroups: firebase.firestore.FieldValue.arrayRemove(groupId) }, { merge: true });
  try {
    await userRef.update({ [`watchTogetherApprovedGroupMap.${groupId}`]: firebase.firestore.FieldValue.delete() });
  } catch (error) {
    console.warn('Watch Together approved mirror cleanup skipped:', error);
  }
}

async function clearWatchTogetherRequestMirror(uid = '', direction = 'incoming', groupId = '') {
  if (!uid || !groupId) return;
  const isIncoming = direction === 'incoming';
  const idsField = isIncoming ? 'watchTogetherIncomingRequests' : 'watchTogetherOutgoingRequests';
  const mapField = isIncoming ? 'watchTogetherIncomingRequestMap' : 'watchTogetherOutgoingRequestMap';
  const userRef = db.collection('users').doc(uid);
  await userRef.set({ [idsField]: firebase.firestore.FieldValue.arrayRemove(groupId) }, { merge: true });
  try {
    await userRef.update({ [`${mapField}.${groupId}`]: firebase.firestore.FieldValue.delete() });
  } catch (error) {
    console.warn('Watch Together request mirror cleanup skipped:', error);
  }
}

function mergeWatchTogetherGroupsById(...groupsLists) {
  const byId = new Map();
  groupsLists.flat().forEach(group => {
    if (!group || !group.id) return;
    byId.set(group.id, { ...(byId.get(group.id) || {}), ...group });
  });
  return [...byId.values()];
}

async function fetchWatchTogetherGroupsByIds(ids = []) {
  // Shared Watch now mirrors all needed request data inside users docs.
  // This avoids depending on a separate top-level collection during send/approve.
  return [];
}

async function hydrateWatchTogetherMirroredRequests() {
  if (!currentUser) return;
  if (watchTogetherMirrorHydratePromise) return watchTogetherMirrorHydratePromise;
  watchTogetherMirrorHydratePromise = (async () => {
    const incomingIds = watchTogetherIncomingRequestIds.slice();
    const outgoingIds = watchTogetherOutgoingRequestIds.slice();
    const mirroredGroups = mergeWatchTogetherGroupsById(
      await fetchWatchTogetherGroupsByIds([...incomingIds, ...outgoingIds]),
      getWatchTogetherMirroredPayloadGroups()
    );
    const incomingFromMirror = mirroredGroups.filter(group => incomingIds.includes(group.id) && (group.pendingUids || []).includes(currentUser.uid));
    const outgoingFromMirror = mirroredGroups.filter(group => outgoingIds.includes(group.id) && group.ownerUid === currentUser.uid && (group.pendingUids || []).length);
    const mirroredIds = new Set(mirroredGroups.map(group => group.id));

    watchTogetherGroups = mergeWatchTogetherGroupsById(
      watchTogetherGroups.filter(group => !mirroredIds.has(group.id)),
      mirroredGroups
    );
    watchTogetherIncomingRequests = incomingFromMirror;
    watchTogetherOutgoingRequests = outgoingFromMirror;
    updateRequestsBadges();
    const communityActive = document.getElementById('nav-community')?.classList.contains('active');
    if (communityActive && activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
  })().catch(error => {
    console.error('Watch Together mirrored request hydrate failed:', error);
  }).finally(() => {
    watchTogetherMirrorHydratePromise = null;
  });
  return watchTogetherMirrorHydratePromise;
}

function canUseWatchTogetherSection(section = activeSection) {
  return WATCH_TOGETHER_SECTIONS.includes(String(section || '').trim());
}

function getWatchTogetherOwnerUid() {
  return viewingUser?.uid || currentUser?.uid || '';
}

function getWatchTogetherTitleKey(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getMediaKeyForSection(item = {}, section = activeSection) {
  const copy = {
    ...(item || {}),
    librarySection: item?.librarySection || item?.mediaCategory || section,
    mediaCategory: item?.mediaCategory || item?.librarySection || section
  };
  return getMediaKey(copy);
}

function getWatchTogetherItemTitle(item = {}, section = activeSection) {
  return getDisplayTitleForItem(item, section) || item?.title || item?.name || '';
}

function buildWatchTogetherItemSeed(item = {}, section = activeSection) {
  const title = getWatchTogetherItemTitle(item, section);
  return {
    section,
    title,
    titleKey: getWatchTogetherTitleKey(title),
    mediaKey: getMediaKeyForSection(item, section),
    cover: item.cover || '',
    genre: item.genre || '',
    tmdbId: item.tmdbId || '',
    imdbId: item.imdbId || '',
    librarySection: section,
    mediaCategory: section
  };
}

function watchTogetherGroupMatchesItem(group = {}, item = {}, section = activeSection) {
  if (!group || !item || group.section !== section) return false;
  const itemMediaKey = getMediaKeyForSection(item, section);
  if (group.mediaKey && itemMediaKey && group.mediaKey === itemMediaKey) return true;
  const itemTitleKey = getWatchTogetherTitleKey(getWatchTogetherItemTitle(item, section));
  return !!group.titleKey && group.titleKey === itemTitleKey;
}

function getWatchTogetherGroupsForItem(item = {}, section = activeSection, ownerUid = getWatchTogetherOwnerUid()) {
  if (!ownerUid || !canUseWatchTogetherSection(section)) return [];
  return watchTogetherGroups.filter(group => {
    const approved = Array.isArray(group.approvedUids) ? group.approvedUids : [];
    return approved.includes(ownerUid) && watchTogetherGroupMatchesItem(group, item, section);
  });
}

function getPendingWatchTogetherGroupsForItem(item = {}, section = activeSection) {
  if (!currentUser || viewingUser || !canUseWatchTogetherSection(section)) return [];
  return watchTogetherGroups.filter(group => {
    const pending = Array.isArray(group.pendingUids) ? group.pendingUids : [];
    return group.ownerUid === currentUser.uid && pending.length && watchTogetherGroupMatchesItem(group, item, section);
  });
}

function getWatchTogetherProfile(uid = '', group = {}) {
  const profile = (group.profiles && group.profiles[uid]) || usersMap[uid] || {};
  return {
    uid,
    name: profile.name || profile.customName || (uid === currentUser?.uid ? userProfile?.name : '') || 'User',
    photo: profile.photo || profile.customPhoto || (uid === currentUser?.uid ? userProfile?.photo : '') || ''
  };
}

function getWatchTogetherAvatar(profile = {}) {
  return profile.photo || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(profile.name || '?') + '&background=1c1535&color=a78bfa');
}

function getWatchTogetherGroupById(groupId = '') {
  const id = String(groupId || '').trim();
  if (!id) return null;
  return { id, ...(
    watchTogetherOutgoingRequestPayloadMap[id] ||
    watchTogetherIncomingRequestPayloadMap[id] ||
    watchTogetherApprovedRequestPayloadMap[id] ||
    watchTogetherGroups.find(group => group && group.id === id) ||
    {}
  ) };
}

function getWatchTogetherBlockedTagUids() {
  if (!watchTogetherTagContext) return new Set();
  const { itemId, section } = watchTogetherTagContext;
  const item = findListItemById(section, itemId);
  if (!item) return new Set();
  const blocked = new Set([currentUser?.uid].filter(Boolean));
  getWatchTogetherGroupsForItem(item, section, currentUser?.uid).forEach(group => {
    [...(group.approvedUids || []), ...(group.pendingUids || [])].forEach(uid => {
      if (uid && uid !== currentUser?.uid) blocked.add(uid);
    });
  });
  watchTogetherSelectedUsers.forEach(user => {
    if (user.uid) blocked.add(user.uid);
  });
  return blocked;
}

function getVisibleWatchTogetherMembersForItem(item = {}, section = activeSection, ownerUid = getWatchTogetherOwnerUid()) {
  const groups = getWatchTogetherGroupsForItem(item, section, ownerUid);
  const byUid = new Map();
  const isOwnPrivateCard = !viewingUser && currentUser?.uid && ownerUid === currentUser.uid;
  groups.forEach(group => {
    const approved = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
    const pending = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
    approved.forEach(uid => {
      if (!uid || uid === ownerUid) return;
      if (!byUid.has(uid)) byUid.set(uid, { ...getWatchTogetherProfile(uid, group), watchTogetherPending: false });
    });
    if (isOwnPrivateCard && group.ownerUid === currentUser.uid) {
      pending.forEach(uid => {
        if (!uid || uid === ownerUid || byUid.has(uid)) return;
        byUid.set(uid, { ...getWatchTogetherProfile(uid, group), watchTogetherPending: true });
      });
    }
  });
  return [...byUid.values()];
}

function renderWatchTogetherCardControl(item = {}, section = activeSection) {
  if (!canUseWatchTogetherSection(section)) return '';
  const ownerUid = getWatchTogetherOwnerUid();
  if (!ownerUid) return '';
  const itemId = escAttr(item.id || '');
  const sectionAttr = escAttr(section);
  const members = getVisibleWatchTogetherMembersForItem(item, section, ownerUid);
  const pendingGroups = getPendingWatchTogetherGroupsForItem(item, section);
  const pendingCount = pendingGroups.reduce((sum, group) => sum + (Array.isArray(group.pendingUids) ? group.pendingUids.length : 0), 0);
  const visible = members.slice(0, 3);
  const stack = members.length ? `<button class="watch-together-stack" type="button" data-mylist-watch-info-id="${itemId}" data-mylist-watch-section="${sectionAttr}" onclick="openWatchTogetherInfoModal(event, '${itemId}', '${sectionAttr}')" aria-label="View people tagged on this title">
    ${visible.map(profile => `<img class="${profile.watchTogetherPending ? 'watch-together-avatar-pending' : ''}" src="${escAttr(getWatchTogetherAvatar(profile))}" alt="${escAttr(profile.name)}" loading="lazy" title="${profile.watchTogetherPending ? 'Waiting for approval' : 'Approved'}">`).join('')}
    ${members.length > 3 ? `<span class="watch-together-more">+${members.length - 3}</span>` : ''}
  </button>` : '';
  const add = (!members.length && !viewingUser && currentUser) ? `<button class="watch-together-add" type="button" data-mylist-watch-add-id="${itemId}" data-mylist-watch-section="${sectionAttr}" onclick="openWatchTogetherTagModal(event, '${itemId}', '${sectionAttr}')" aria-label="Tag people to watch together">＋</button>` : '';
  const pending = pendingCount ? `<span class="watch-together-pending" title="Waiting for approval">${pendingCount} pending</span>` : '';
  if (!stack && !add && !pending) return '';
  return `<div class="watch-together-slot">${stack}${pending}${add}</div>`;
}

function findListItemById(section = activeSection, itemId = '') {
  const source = viewingUser && friendViewData ? friendViewData : data;
  return (source?.[section] || []).find(item => String(item.id) === String(itemId)) || null;
}

function closeWatchTogetherModal() {
  const overlay = document.getElementById('watch-together-modal-overlay');
  if (overlay) overlay.remove();
  watchTogetherTagContext = null;
  watchTogetherSelectedUsers = [];
}

function closeWatchTogetherInfoModal() {
  const overlay = document.getElementById('watch-together-info-overlay');
  if (overlay) overlay.remove();
  if (!document.getElementById('watch-together-modal-overlay')) {
    watchTogetherTagContext = null;
    watchTogetherSelectedUsers = [];
  }
}

function setWatchTogetherMode(mode = 'watched') {
  if (!watchTogetherTagContext) return;
  watchTogetherTagContext.mode = mode === 'planned' ? 'planned' : 'watched';
  const modal = document.getElementById('watch-together-modal-overlay') || document.getElementById('watch-together-info-overlay');
  if (!modal) return;
  modal.querySelectorAll('.watch-together-mode-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.mode === watchTogetherTagContext.mode);
  });
}

function renderWatchTogetherSelected() {
  const wrap = document.getElementById('watch-together-selected');
  if (!wrap) return;
  wrap.innerHTML = watchTogetherSelectedUsers.length
    ? watchTogetherSelectedUsers.map(user => `<span class="watch-together-chip"><img src="${escAttr(getWatchTogetherAvatar(user))}" alt="">${renderDisplayNameHTML(user, 'User')}<button type="button" onclick="removeWatchTogetherSelected('${escAttr(user.uid)}')">×</button></span>`).join('')
    : '<span class="watch-together-selected-empty">Search and add people. They approve before it appears.</span>';
  const saveBtn = document.getElementById('watch-together-save-btn');
  if (saveBtn) saveBtn.disabled = watchTogetherSelectedUsers.length === 0;
}

function removeWatchTogetherSelected(uid = '') {
  watchTogetherSelectedUsers = watchTogetherSelectedUsers.filter(user => user.uid !== uid);
  renderWatchTogetherSelected();
  const input = document.getElementById('watch-together-search-input');
  if (input) searchWatchTogetherUsers(input.value || '');
}

function addWatchTogetherSelected(uid = '', name = '', photo = '') {
  if (!uid || uid === currentUser?.uid || watchTogetherSelectedUsers.some(user => user.uid === uid)) return;
  watchTogetherSelectedUsers.push({ uid, name: name || 'User', photo: photo || '' });
  renderWatchTogetherSelected();
  const input = document.getElementById('watch-together-search-input');
  if (input) searchWatchTogetherUsers(input.value || '');
}

async function searchWatchTogetherUsers(query = '') {
  const results = document.getElementById('watch-together-search-results');
  if (!results) return;
  const q = String(query || '').trim().toLowerCase();
  if (q.length < 2) {
    results.innerHTML = '<div class="watch-together-empty">Type at least 2 letters to tag anyone by username.</div>';
    return;
  }
  results.innerHTML = '<div class="watch-together-empty">Searching...</div>';
  try {
    const snap = await db.collection('users')
      .where('nameLower', '>=', q)
      .where('nameLower', '<=', q + '\uf8ff')
      .limit(12)
      .get();
    const users = [];
    snap.forEach(doc => {
      const raw = { ...(doc.data() || {}), uid: doc.id };
      if (!raw.uid || raw.uid === currentUser?.uid) return;
      usersMap[raw.uid] = raw;
      users.push(raw);
    });
    if (!users.length) {
      results.innerHTML = '<div class="watch-together-empty">No users found.</div>';
      return;
    }
    const blockedUids = getWatchTogetherBlockedTagUids();
    results.innerHTML = users.map(user => {
      const selected = watchTogetherSelectedUsers.some(u => u.uid === user.uid);
      const alreadyTagged = blockedUids.has(user.uid) && !selected;
      const disabled = selected || alreadyTagged;
      const avatar = getWatchTogetherAvatar(user);
      return `<div class="watch-together-result">
        <img src="${escAttr(avatar)}" alt="">
        <div class="watch-together-result-copy"><strong>${renderDisplayNameHTML(user, 'User')}</strong><span>${selected ? 'Selected' : alreadyTagged ? 'Already on this title' : 'Tap Add to request approval'}</span></div>
        <button type="button" class="watch-together-result-add" ${disabled ? 'disabled' : ''} onclick="addWatchTogetherSelected('${escAttr(user.uid)}','${escAttr(user.name || user.customName || 'User')}','${escAttr(user.photo || user.customPhoto || '')}')">${selected ? 'Added' : alreadyTagged ? 'Added' : 'Add'}</button>
      </div>`;
    }).join('');
  } catch (e) {
    console.error('Watch together search failed:', e);
    results.innerHTML = '<div class="watch-together-empty">Search failed. Try again.</div>';
  }
}

function queueWatchTogetherSearch(value = '') {
  clearTimeout(watchTogetherSearchTimer);
  watchTogetherSearchTimer = setTimeout(() => searchWatchTogetherUsers(value), 180);
}

function createWatchTogetherGroupId() {
  const safeUid = String(currentUser?.uid || 'user').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32) || 'user';
  return `wt_${safeUid}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function openWatchTogetherTagModal(event, itemId = '', section = activeSection) {
  event?.stopPropagation?.();
  if (!currentUser || viewingUser || !canUseWatchTogetherSection(section)) return;
  const item = findListItemById(section, itemId);
  if (!item) return;
  const seed = buildWatchTogetherItemSeed(item, section);
  const defaultMode = item.status === 'planned' ? 'planned' : 'watched';
  watchTogetherTagContext = { itemId, section, seed, mode: defaultMode };
  watchTogetherSelectedUsers = [];
  const existing = document.getElementById('watch-together-modal-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'watch-together-modal-overlay';
  overlay.className = 'watch-together-modal-overlay';
  overlay.innerHTML = `<div class="watch-together-modal" role="dialog" aria-modal="true" aria-label="Tag people on ${escAttr(seed.title)}">
    <div class="watch-together-modal-head">
      <div><div class="watch-together-kicker">My Lists Social</div><h3>Tag people on this title</h3><p>${escHtml(seed.title)}</p></div>
      <button type="button" class="watch-together-close" onclick="closeWatchTogetherModal()" aria-label="Close">×</button>
    </div>
    <div class="watch-together-mode-toggle">
      <button type="button" class="watch-together-mode-btn${defaultMode === 'watched' ? ' active' : ''}" data-mode="watched" onclick="setWatchTogetherMode('watched')">Watched together</button>
      <button type="button" class="watch-together-mode-btn${defaultMode === 'planned' ? ' active' : ''}" data-mode="planned" onclick="setWatchTogetherMode('planned')">Plan together</button>
    </div>
    <div class="watch-together-selected" id="watch-together-selected"></div>
    <input id="watch-together-search-input" class="watch-together-search" type="text" placeholder="Search anyone by username..." oninput="queueWatchTogetherSearch(this.value)">
    <div class="watch-together-search-results" id="watch-together-search-results"><div class="watch-together-empty">Type at least 2 letters to tag anyone by username.</div></div>
    <button id="watch-together-save-btn" class="watch-together-save" type="button" disabled onclick="createWatchTogetherRequest()">Send approval request</button>
  </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) closeWatchTogetherModal(); });
  document.body.appendChild(overlay);
  renderWatchTogetherSelected();
  setTimeout(() => document.getElementById('watch-together-search-input')?.focus(), 80);
}

async function createWatchTogetherRequest() {
  if (!currentUser || !watchTogetherTagContext || !watchTogetherSelectedUsers.length) return;
  const btn = document.getElementById('watch-together-save-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending...'; }
  const selected = watchTogetherSelectedUsers.slice();
  const seed = watchTogetherTagContext.seed;
  const mode = watchTogetherTagContext.mode === 'planned' ? 'planned' : 'watched';
  const ownerProfile = {
    uid: currentUser.uid,
    name: userProfile?.name || currentUser.displayName || 'User',
    photo: userProfile?.photo || currentUser.photoURL || ''
  };
  const profiles = { [currentUser.uid]: { name: ownerProfile.name, photo: ownerProfile.photo } };
  selected.forEach(user => { profiles[user.uid] = { name: user.name || 'User', photo: user.photo || '' }; });
  const pendingUids = selected.map(user => user.uid);
  const participantUids = [currentUser.uid, ...pendingUids.filter(uid => uid !== currentUser.uid)];
  try {
    const groupId = createWatchTogetherGroupId();
    const baseGroupData = {
      id: groupId,
      ...seed,
      mode,
      ownerUid: currentUser.uid,
      participantUids,
      approvedUids: [currentUser.uid],
      pendingUids,
      rejectedUids: [],
      profiles,
      status: 'pending',
      createdAtMs: Date.now(),
      updatedAtMs: Date.now()
    };
    const mirrorPayload = getWatchTogetherMirrorPayload(baseGroupData, groupId);
    await Promise.all([
      setWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId, mirrorPayload),
      ...pendingUids.map(uid => setWatchTogetherRequestMirror(uid, 'incoming', groupId, mirrorPayload))
    ]);
    watchTogetherOutgoingRequestIds = [...new Set([...watchTogetherOutgoingRequestIds, groupId])];
    watchTogetherOutgoingRequestPayloadMap[groupId] = mirrorPayload;
    watchTogetherGroups = mergeWatchTogetherGroupsById(watchTogetherGroups, [mirrorPayload]);
    watchTogetherOutgoingRequests = mergeWatchTogetherGroupsById(watchTogetherOutgoingRequests, [mirrorPayload]);
    updateRequestsBadges();
    render();
    const refreshInfoContext = document.getElementById('watch-together-info-overlay')
      ? { itemId: watchTogetherTagContext.itemId, section: watchTogetherTagContext.section }
      : null;
    if (refreshInfoContext) {
      closeWatchTogetherInfoModal();
      setTimeout(() => openWatchTogetherInfoModal(null, refreshInfoContext.itemId, refreshInfoContext.section), 40);
    } else {
      closeWatchTogetherModal();
    }
    showToast('Approval request sent');
  } catch (e) {
    console.error('Create watch together request failed:', e);
    if (btn) { btn.disabled = false; btn.textContent = 'Send approval request'; }
    showToast('Could not send request. Try again.');
  }
}

function getWatchTogetherRequestTitle(group = {}) {
  const mode = group.mode === 'planned' ? 'plans to watch' : 'watched';
  return `${mode} ${group.title || 'this title'} together`;
}

function renderWatchTogetherRequestCards(groups = [], type = 'incoming') {
  if (!groups.length) return '';
  const isIncoming = type === 'incoming';
  return `<div class="friend-watch-request-list ${isIncoming ? 'incoming' : 'outgoing'}">${groups.map(group => {
    const owner = getWatchTogetherProfile(group.ownerUid, group);
    const section = group.section || group.librarySection || group.mediaCategory || '';
    const sectionLabel = getSectionLabel(section, true) || 'Title';
    const modeLabel = group.mode === 'planned' ? 'Plan Together' : 'Watched Together';
    const modeVerb = group.mode === 'planned' ? 'plan to watch' : 'watched';
    const title = group.title || 'Untitled';
    const ownerAvatar = getWatchTogetherAvatar(owner);
    const pendingUids = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
    const pendingUsers = pendingUids.map(uid => getWatchTogetherProfile(uid, group));
    const approvedUids = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
    const approvedUsers = approvedUids.filter(uid => uid !== currentUser?.uid).map(uid => getWatchTogetherProfile(uid, group));
    const targetUsers = isIncoming ? [owner] : pendingUsers;
    const visibleUsers = targetUsers.slice(0, 4);
    const targetStack = visibleUsers.length ? `<div class="friend-watch-request-people-stack">${visibleUsers.map(user => `<img src="${escAttr(getWatchTogetherAvatar(user))}" alt="${escAttr(user.name || 'User')}" loading="lazy">`).join('')}${targetUsers.length > 4 ? `<span>+${targetUsers.length - 4}</span>` : ''}</div>` : '';
    const approvedStack = approvedUsers.length ? `<div class="friend-watch-request-approved"><span>Already joined</span><div class="friend-watch-request-people-stack mini">${approvedUsers.slice(0, 4).map(user => `<img src="${escAttr(getWatchTogetherAvatar(user))}" alt="${escAttr(user.name || 'User')}" loading="lazy">`).join('')}${approvedUsers.length > 4 ? `<span>+${approvedUsers.length - 4}</span>` : ''}</div></div>` : '';
    const summary = isIncoming
      ? `${owner.name || 'Someone'} wants to mark this as ${modeLabel.toLowerCase()} with you.`
      : (pendingUsers.length === 1
        ? `Waiting for ${pendingUsers[0].name || 'this user'} to approve.`
        : `Waiting for ${pendingUsers.length || 0} people to approve.`);
    const sentTo = !isIncoming && pendingUsers.length ? `<div class="friend-watch-request-sent-to"><span>Sent to</span>${pendingUsers.map(user => `
      <button class="friend-watch-request-person-pill" type="button" onclick="cancelWatchTogetherPendingUser('${escAttr(group.id)}','${escAttr(user.uid)}')" aria-label="Remove ${escAttr(user.name || 'user')} from this request">
        <img src="${escAttr(getWatchTogetherAvatar(user))}" alt="" loading="lazy"><strong>${renderDisplayNameHTML(user, 'User')}</strong><em>Remove</em>
      </button>`).join('')}</div>` : '';
    return `<article class="friend-watch-request-card ${isIncoming ? 'needs-approval' : 'sent-request'}">
      <div class="friend-watch-request-poster">${group.cover ? `<img src="${escAttr(group.cover)}" alt="${escAttr(title)}" loading="lazy">` : `<span>${escHtml(getSectionIcon(section))}</span>`}</div>
      <div class="friend-watch-request-body">
        <div class="friend-watch-request-kicker"><span>${escHtml(modeLabel)}</span><em>${escHtml(sectionLabel)}</em></div>
        <h4>${escHtml(title)}</h4>
        <p>${escHtml(summary)}</p>
        <div class="friend-watch-request-meta-row">
          ${targetStack}
          <strong>${isIncoming ? `From ${renderDisplayNameHTML(owner, 'User')}` : `${pendingUsers.length || 0} pending`}</strong>
        </div>
        ${approvedStack}
        ${sentTo}
      </div>
      <div class="friend-watch-request-actions">
        ${isIncoming
          ? `<button class="friend-watch-action accept" type="button" onclick="approveWatchTogetherRequest('${escAttr(group.id)}')">Accept</button><button class="friend-watch-action decline" type="button" onclick="declineWatchTogetherRequest('${escAttr(group.id)}')">Decline</button>`
          : `<button class="friend-watch-action decline" type="button" onclick="cancelWatchTogetherPendingUser('${escAttr(group.id)}')">Remove</button>`}
      </div>
    </article>`;
  }).join('')}</div>`;
}

async function ensureWatchTogetherItemInOwnList(group = {}) {
  if (!group || !canUseWatchTogetherSection(group.section)) return;
  const section = group.section;
  const list = Array.isArray(data[section]) ? data[section] : [];
  const already = list.some(item => watchTogetherGroupMatchesItem(group, item, section));
  if (already) return;
  const nextItem = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    title: group.title || 'Untitled',
    cover: group.cover || '',
    genre: group.genre || '',
    rating: 0,
    status: group.mode === 'planned' ? 'planned' : 'watched',
    tmdbId: group.tmdbId || '',
    imdbId: group.imdbId || '',
    librarySection: section,
    mediaCategory: section,
    episodes: isShowSection(section) ? [] : undefined,
    addedAt: Date.now()
  };
  data[section] = [nextItem, ...list];
  await writeOwnDataDirect(data);
}

async function approveWatchTogetherRequest(groupId = '') {
  if (!currentUser || !groupId) return;
  try {
    const group = { id: groupId, ...(watchTogetherIncomingRequestPayloadMap[groupId] || {}) };
    if (!(group.pendingUids || []).includes(currentUser.uid)) return;
    await ensureWatchTogetherItemInOwnList(group);
    const pendingBefore = Array.isArray(group.pendingUids) ? group.pendingUids : [];
    const remainingPending = pendingBefore.filter(uid => uid !== currentUser.uid);
    const isLastPendingApproval = remainingPending.length === 0;
    const updatedGroup = {
      ...group,
      pendingUids: remainingPending,
      approvedUids: [...new Set([...(Array.isArray(group.approvedUids) ? group.approvedUids : []), currentUser.uid])],
      participantUids: [...new Set([...(Array.isArray(group.participantUids) ? group.participantUids : []), currentUser.uid])],
      status: isLastPendingApproval ? 'approved' : 'pending',
      updatedAtMs: Date.now()
    };
    const approvedMirrorUids = updatedGroup.approvedUids.filter(Boolean);
    await Promise.all([
      clearWatchTogetherRequestMirror(currentUser.uid, 'incoming', groupId),
      setWatchTogetherRequestMirror(group.ownerUid, 'outgoing', groupId, updatedGroup, { includeInRequestList: !isLastPendingApproval }),
      ...approvedMirrorUids.map(uid => setWatchTogetherApprovedMirror(uid, groupId, updatedGroup))
    ]);
    watchTogetherIncomingRequestIds = watchTogetherIncomingRequestIds.filter(id => id !== groupId);
    delete watchTogetherIncomingRequestPayloadMap[groupId];
    watchTogetherIncomingRequests = watchTogetherIncomingRequests.filter(group => group.id !== groupId);
    watchTogetherApprovedRequestIds = [...new Set([...watchTogetherApprovedRequestIds, groupId])];
    watchTogetherApprovedRequestPayloadMap[groupId] = getWatchTogetherMirrorPayload(updatedGroup, groupId);
    if (isLastPendingApproval) {
      watchTogetherOutgoingRequestIds = watchTogetherOutgoingRequestIds.filter(id => id !== groupId);
      watchTogetherOutgoingRequests = watchTogetherOutgoingRequests.filter(group => group.id !== groupId);
    }
    watchTogetherGroups = mergeWatchTogetherGroupsById(watchTogetherGroups, [updatedGroup]);
    showToast('Shared Watch approved');
    if (activeFriendsTab === 'requests') renderRequestsList(true);
    if (activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
    render();
  } catch (e) {
    console.error('Approve watch together failed:', e);
    showToast('Could not approve. Try again.');
  }
}

async function declineWatchTogetherRequest(groupId = '') {
  if (!currentUser || !groupId) return;
  try {
    const group = { id: groupId, ...(watchTogetherIncomingRequestPayloadMap[groupId] || {}) };
    const pendingBefore = Array.isArray(group.pendingUids) ? group.pendingUids : [];
    const remainingPending = pendingBefore.filter(uid => uid !== currentUser.uid);
    const isLastPendingResponse = remainingPending.length === 0;
    const updatedGroup = {
      ...group,
      pendingUids: remainingPending,
      participantUids: (Array.isArray(group.participantUids) ? group.participantUids : []).filter(uid => uid !== currentUser.uid),
      rejectedUids: [...new Set([...(Array.isArray(group.rejectedUids) ? group.rejectedUids : []), currentUser.uid])],
      status: isLastPendingResponse ? ((Array.isArray(group.approvedUids) && group.approvedUids.length > 1) ? 'approved' : 'declined') : 'pending',
      updatedAtMs: Date.now()
    };
    await Promise.all([
      clearWatchTogetherRequestMirror(currentUser.uid, 'incoming', groupId),
      setWatchTogetherRequestMirror(group.ownerUid, 'outgoing', groupId, updatedGroup, { includeInRequestList: !isLastPendingResponse }),
      ...(Array.isArray(updatedGroup.approvedUids) ? updatedGroup.approvedUids : []).filter(Boolean).map(uid => setWatchTogetherApprovedMirror(uid, groupId, updatedGroup))
    ]);
    watchTogetherIncomingRequestIds = watchTogetherIncomingRequestIds.filter(id => id !== groupId);
    delete watchTogetherIncomingRequestPayloadMap[groupId];
    watchTogetherIncomingRequests = watchTogetherIncomingRequests.filter(group => group.id !== groupId);
    watchTogetherGroups = mergeWatchTogetherGroupsById(watchTogetherGroups, [updatedGroup]);
    showToast('Shared Watch declined');
    if (activeFriendsTab === 'requests') renderRequestsList(true);
    if (activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
  } catch (e) {
    console.error('Decline watch together failed:', e);
    showToast('Could not decline. Try again.');
  }
}

async function cancelWatchTogetherPendingUser(groupId = '', targetUid = '') {
  if (!currentUser || !groupId) return;
  try {
    const group = { id: groupId, ...(watchTogetherOutgoingRequestPayloadMap[groupId] || watchTogetherApprovedRequestPayloadMap[groupId] || {}) };
    if (group.ownerUid !== currentUser.uid) return;
    const pendingUids = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
    const targets = (targetUid ? [targetUid] : pendingUids).filter(uid => pendingUids.includes(uid));
    if (!targets.length) return;
    const remainingPending = pendingUids.filter(uid => !targets.includes(uid));
    const approvedUids = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
    const nextStatus = remainingPending.length ? 'pending' : (approvedUids.length > 1 ? 'approved' : 'cancelled');
    const updatedGroup = {
      ...group,
      pendingUids: remainingPending,
      participantUids: (Array.isArray(group.participantUids) ? group.participantUids : []).filter(uid => !targets.includes(uid)),
      status: nextStatus,
      updatedAtMs: Date.now()
    };
    const writes = [
      ...targets.map(uid => clearWatchTogetherRequestMirror(uid, 'incoming', groupId))
    ];
    if (!remainingPending.length && approvedUids.length <= 1) {
      writes.push(clearWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId));
      writes.push(clearWatchTogetherApprovedMirror(currentUser.uid, groupId));
    } else {
      writes.push(setWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId, updatedGroup, { includeInRequestList: remainingPending.length > 0 }));
      if (approvedUids.length > 1) {
        writes.push(...approvedUids.map(uid => setWatchTogetherApprovedMirror(uid, groupId, updatedGroup)));
      }
    }
    await Promise.all(writes);
    const updateGroup = original => original && original.id === groupId
      ? { ...original, pendingUids: remainingPending, participantUids: (original.participantUids || []).filter(uid => !targets.includes(uid)), status: nextStatus }
      : original;
    watchTogetherGroups = watchTogetherGroups.map(updateGroup).filter(g => g && (g.id !== groupId || nextStatus !== 'cancelled'));
    watchTogetherOutgoingRequests = watchTogetherOutgoingRequests.map(updateGroup).filter(g => g && (g.pendingUids || []).length);
    if (!remainingPending.length) {
      watchTogetherOutgoingRequestIds = watchTogetherOutgoingRequestIds.filter(id => id !== groupId);
      if (approvedUids.length <= 1) delete watchTogetherOutgoingRequestPayloadMap[groupId];
      else watchTogetherOutgoingRequestPayloadMap[groupId] = getWatchTogetherMirrorPayload(updatedGroup, groupId);
    } else {
      watchTogetherOutgoingRequestPayloadMap[groupId] = getWatchTogetherMirrorPayload(updatedGroup, groupId);
    }
    showToast(targets.length === 1 ? 'Removed Shared Watch request' : 'Removed pending Shared Watch requests');
    if (activeFriendsTab === 'requests') renderRequestsList(true);
    if (activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
    render();
    const overlay = document.getElementById('watch-together-info-overlay');
    const refreshItemId = overlay?.dataset.itemId || '';
    const refreshSection = overlay?.dataset.section || activeSection;
    if (overlay && refreshItemId) {
      closeWatchTogetherInfoModal();
      setTimeout(() => openWatchTogetherInfoModal(null, refreshItemId, refreshSection), 40);
    }
  } catch (e) {
    console.error('Cancel watch together request failed:', e);
    showToast('Could not remove request. Try again.');
  }
}



async function removeWatchTogetherMember(groupId = '', targetUid = '') {
  if (!currentUser || !groupId || !targetUid || targetUid === currentUser.uid) return;
  try {
    const group = getWatchTogetherGroupById(groupId);
    if (!group || group.ownerUid !== currentUser.uid) return;
    const pendingUids = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
    if (pendingUids.includes(targetUid)) {
      await cancelWatchTogetherPendingUser(groupId, targetUid);
      return;
    }
    const approvedUids = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
    if (!approvedUids.includes(targetUid)) return;

    const remainingApproved = approvedUids.filter(uid => uid !== targetUid);
    const remainingPending = pendingUids.filter(uid => uid !== targetUid);
    const hasApprovedPartner = remainingApproved.some(uid => uid && uid !== currentUser.uid);
    const nextStatus = remainingPending.length ? 'pending' : (hasApprovedPartner ? 'approved' : 'cancelled');
    const updatedGroup = {
      ...group,
      approvedUids: remainingApproved,
      pendingUids: remainingPending,
      participantUids: (Array.isArray(group.participantUids) ? group.participantUids : []).filter(uid => uid !== targetUid),
      status: nextStatus,
      updatedAtMs: Date.now()
    };

    const writes = [
      clearWatchTogetherRequestMirror(targetUid, 'incoming', groupId),
      clearWatchTogetherRequestMirror(targetUid, 'outgoing', groupId),
      clearWatchTogetherApprovedMirror(targetUid, groupId)
    ];

    if (nextStatus === 'cancelled') {
      writes.push(clearWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId));
      writes.push(clearWatchTogetherApprovedMirror(currentUser.uid, groupId));
    } else {
      if (remainingPending.length) {
        writes.push(setWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId, updatedGroup, { includeInRequestList: true }));
        writes.push(...remainingPending.map(uid => setWatchTogetherRequestMirror(uid, 'incoming', groupId, updatedGroup)));
      } else {
        writes.push(clearWatchTogetherRequestMirror(currentUser.uid, 'outgoing', groupId));
      }
      writes.push(...remainingApproved.map(uid => setWatchTogetherApprovedMirror(uid, groupId, updatedGroup)));
    }

    await Promise.all(writes);

    const updateLocalGroup = original => original && original.id === groupId ? updatedGroup : original;
    watchTogetherGroups = watchTogetherGroups.map(updateLocalGroup).filter(g => g && (g.id !== groupId || nextStatus !== 'cancelled'));
    watchTogetherOutgoingRequests = watchTogetherOutgoingRequests.map(updateLocalGroup).filter(g => g && (g.pendingUids || []).length);
    watchTogetherIncomingRequests = watchTogetherIncomingRequests.filter(g => g.id !== groupId || (g.pendingUids || []).includes(currentUser.uid));
    if (nextStatus === 'cancelled') {
      watchTogetherOutgoingRequestIds = watchTogetherOutgoingRequestIds.filter(id => id !== groupId);
      watchTogetherApprovedRequestIds = watchTogetherApprovedRequestIds.filter(id => id !== groupId);
      delete watchTogetherOutgoingRequestPayloadMap[groupId];
      delete watchTogetherApprovedRequestPayloadMap[groupId];
    } else {
      if (remainingPending.length) {
        watchTogetherOutgoingRequestIds = [...new Set([...watchTogetherOutgoingRequestIds, groupId])];
        watchTogetherOutgoingRequestPayloadMap[groupId] = getWatchTogetherMirrorPayload(updatedGroup, groupId);
      } else {
        watchTogetherOutgoingRequestIds = watchTogetherOutgoingRequestIds.filter(id => id !== groupId);
        delete watchTogetherOutgoingRequestPayloadMap[groupId];
      }
      watchTogetherApprovedRequestIds = [...new Set([...watchTogetherApprovedRequestIds, groupId])];
      watchTogetherApprovedRequestPayloadMap[groupId] = getWatchTogetherMirrorPayload(updatedGroup, groupId);
    }

    watchTogetherAverageCache = {};
    updateRequestsBadges();
    render();
    const overlay = document.getElementById('watch-together-info-overlay');
    const refreshItemId = overlay?.dataset.itemId || '';
    const refreshSection = overlay?.dataset.section || activeSection;
    if (overlay && refreshItemId) {
      closeWatchTogetherInfoModal();
      setTimeout(() => openWatchTogetherInfoModal(null, refreshItemId, refreshSection), 40);
    }
    if (activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
    showToast('Removed from Shared Watch');
  } catch (e) {
    console.error('Remove watch together member failed:', e);
    showToast('Could not remove. Try again.');
  }
}

async function openWatchTogetherInfoModal(event, itemId = '', section = activeSection) {
  event?.stopPropagation?.();
  const item = findListItemById(section, itemId);
  if (!item) return;
  const ownerUid = getWatchTogetherOwnerUid();
  const groups = getWatchTogetherGroupsForItem(item, section, ownerUid);
  const membersByUid = new Map();
  const isOwnPrivateCard = !viewingUser && currentUser?.uid && ownerUid === currentUser.uid;
  groups.forEach(group => {
    const approved = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
    const pending = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
    approved.forEach(uid => {
      if (!membersByUid.has(uid)) membersByUid.set(uid, { ...getWatchTogetherProfile(uid, group), groupId: group.id, watchTogetherPending: false });
    });
    if (isOwnPrivateCard && group.ownerUid === currentUser.uid) {
      pending.forEach(uid => {
        if (!membersByUid.has(uid)) membersByUid.set(uid, { ...getWatchTogetherProfile(uid, group), groupId: group.id, watchTogetherPending: true });
      });
    }
  });
  const members = [...membersByUid.values()];
  if (!members.length && !isOwnPrivateCard) return;
  if (isOwnPrivateCard) {
    const seed = buildWatchTogetherItemSeed(item, section);
    const defaultMode = item.status === 'planned' ? 'planned' : 'watched';
    watchTogetherTagContext = { itemId, section, seed, mode: defaultMode };
    watchTogetherSelectedUsers = [];
  }
  const old = document.getElementById('watch-together-info-overlay');
  if (old) old.remove();
  const title = getWatchTogetherItemTitle(item, section);
  const manageHtml = isOwnPrivateCard ? `<div class="watch-together-manage-block">
    <div class="watch-together-manage-title">Add more people</div>
    <div class="watch-together-mode-toggle">
      <button type="button" class="watch-together-mode-btn${item.status === 'planned' ? '' : ' active'}" data-mode="watched" onclick="setWatchTogetherMode('watched')">Watched together</button>
      <button type="button" class="watch-together-mode-btn${item.status === 'planned' ? ' active' : ''}" data-mode="planned" onclick="setWatchTogetherMode('planned')">Plan together</button>
    </div>
    <div class="watch-together-selected" id="watch-together-selected"></div>
    <input id="watch-together-search-input" class="watch-together-search" type="text" placeholder="Search anyone by username..." oninput="queueWatchTogetherSearch(this.value)">
    <div class="watch-together-search-results" id="watch-together-search-results"><div class="watch-together-empty">Type at least 2 letters to tag anyone by username.</div></div>
    <button id="watch-together-save-btn" class="watch-together-save" type="button" disabled onclick="createWatchTogetherRequest()">Send approval request</button>
  </div>` : '';
  const memberHtml = members.length
    ? members.map(profile => `<div class="watch-together-member-row${profile.watchTogetherPending ? ' pending' : ''}">
        <button class="watch-together-member-profile" type="button" onclick="openUserProfile('${escAttr(profile.uid)}')"><img src="${escAttr(getWatchTogetherAvatar(profile))}" alt=""><span>${renderDisplayNameHTML(profile, 'User')}</span>${profile.watchTogetherPending ? '<em>Pending</em>' : ''}</button>
        ${isOwnPrivateCard && profile.uid !== currentUser?.uid ? `<button class="watch-together-member-remove" type="button" onclick="removeWatchTogetherMember('${escAttr(profile.groupId)}','${escAttr(profile.uid)}')" aria-label="Remove ${escAttr(profile.name || 'user')}">Remove</button>` : ''}
      </div>`).join('')
    : '<div class="watch-together-empty">No one added yet.</div>';
  const overlay = document.createElement('div');
  overlay.id = 'watch-together-info-overlay';
  overlay.className = 'watch-together-modal-overlay watch-together-info-overlay';
  overlay.dataset.itemId = itemId;
  overlay.dataset.section = section;
  overlay.innerHTML = `<div class="watch-together-info-modal" role="dialog" aria-modal="true" aria-label="People tagged on ${escAttr(title)}">
    <div class="watch-together-modal-head">
      <div><div class="watch-together-kicker">Watched Together</div><h3>${escHtml(title)}</h3><p id="watch-together-average">Average rating: loading...</p></div>
      <button type="button" class="watch-together-close" onclick="closeWatchTogetherInfoModal()" aria-label="Close">×</button>
    </div>
    <div class="watch-together-member-list">${memberHtml}</div>
    ${manageHtml}
  </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) closeWatchTogetherInfoModal(); });
  document.body.appendChild(overlay);
  if (isOwnPrivateCard) renderWatchTogetherSelected();
  const avgEl = document.getElementById('watch-together-average');
  const average = await calculateWatchTogetherAverageRating(members.map(m => m.uid), item, section);
  if (avgEl) avgEl.textContent = average;
}

async function calculateWatchTogetherAverageRating(uids = [], item = {}, section = activeSection) {
  const seed = buildWatchTogetherItemSeed(item, section);
  const cacheKey = `${section}|${seed.mediaKey}|${seed.titleKey}|${uids.slice().sort().join(',')}`;
  if (watchTogetherAverageCache[cacheKey]) return watchTogetherAverageCache[cacheKey];
  try {
    const docs = await Promise.all(uids.map(uid => db.collection('watchlist').doc(uid).get().catch(() => null)));
    const ratings = [];
    docs.forEach(doc => {
      if (!doc || !doc.exists) return;
      const d = doc.data() || {};
      let list = [];
      try { list = d[section] ? JSON.parse(d[section]) : []; } catch (e) { list = []; }
      const match = (Array.isArray(list) ? list : []).find(row => {
        const rowSeed = buildWatchTogetherItemSeed(row, section);
        return (seed.mediaKey && rowSeed.mediaKey && seed.mediaKey === rowSeed.mediaKey) || (seed.titleKey && seed.titleKey === rowSeed.titleKey);
      });
      const rating = Number(match?.rating || 0);
      if (rating > 0) ratings.push(rating);
    });
    const label = ratings.length
      ? `Average rating: ⭐ ${formatRatingValueForSection(ratings.reduce((sum, rating) => sum + rating, 0) / ratings.length, section, false)} · ${ratings.length}/${uids.length} rated`
      : `Average rating: no ratings yet`;
    watchTogetherAverageCache[cacheKey] = label;
    return label;
  } catch (e) {
    console.error('Average Watch Together rating failed:', e);
    return 'Average rating unavailable';
  }
}

function applyWatchTogetherSnapshot(groups = []) {
  watchTogetherGroups = mergeWatchTogetherGroupsById(groups, watchTogetherGroups);
  const incomingFromSnapshot = currentUser ? groups.filter(group => (group.pendingUids || []).includes(currentUser.uid)) : [];
  const outgoingFromSnapshot = currentUser ? groups.filter(group => group.ownerUid === currentUser.uid && (group.pendingUids || []).length) : [];
  watchTogetherIncomingRequests = mergeWatchTogetherGroupsById(incomingFromSnapshot, watchTogetherIncomingRequests)
    .filter(group => (group.pendingUids || []).includes(currentUser.uid));
  watchTogetherOutgoingRequests = mergeWatchTogetherGroupsById(outgoingFromSnapshot, watchTogetherOutgoingRequests)
    .filter(group => group.ownerUid === currentUser.uid && (group.pendingUids || []).length);
  watchTogetherAverageCache = {};
  updateRequestsBadges();
  const communityActive = document.getElementById('nav-community')?.classList.contains('active');
  if (communityActive && activeFriendsTab === 'requests') renderRequestsList(true);
  if (communityActive && activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
  render();
}

function startWatchTogetherListener() {
  // Shared Watch is driven by the live users/{uid} listener so requests do not depend
  // on a separate collection that can be blocked by Firestore rules.
  watchTogetherUnsubscribe = null;
}

async function loadWatchTogetherGroupsForOwner(uid = '') {
  const ownerUid = String(uid || '').trim();
  if (!ownerUid) return;
  try {
    const doc = await db.collection('users').doc(ownerUid).get();
    const raw = doc.exists ? (doc.data() || {}) : {};
    const approvedMap = normalizeWatchTogetherRequestPayloadMap(raw.watchTogetherApprovedGroupMap);
    const outgoingMap = normalizeWatchTogetherRequestPayloadMap(raw.watchTogetherOutgoingRequestMap);
    const groups = [...Object.values(approvedMap), ...Object.values(outgoingMap)].filter(group => {
      const approved = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
      return group.ownerUid === ownerUid && approved.some(approvedUid => approvedUid !== ownerUid);
    });
    if (groups.length) {
      watchTogetherGroups = mergeWatchTogetherGroupsById(watchTogetherGroups, groups);
      watchTogetherAverageCache = {};
    }
  } catch (error) {
    console.error('Shared Watch owner groups failed:', error);
  }
}

function stopWatchTogetherListener() {
  if (watchTogetherUnsubscribe) {
    watchTogetherUnsubscribe();
    watchTogetherUnsubscribe = null;
  }
  watchTogetherGroups = [];
  watchTogetherIncomingRequests = [];
  watchTogetherOutgoingRequests = [];
  watchTogetherIncomingRequestIds = [];
  watchTogetherOutgoingRequestIds = [];
  watchTogetherIncomingRequestPayloadMap = {};
  watchTogetherOutgoingRequestPayloadMap = {};
  watchTogetherApprovedRequestIds = [];
  watchTogetherApprovedRequestPayloadMap = {};
  watchTogetherMirrorHydratePromise = null;
  watchTogetherAverageCache = {};
}

function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase();
}

function normalizeDisplayName(value) {
  return String(value || '').trim().toLowerCase();
}

function getUserAccountEmail(userLike = null) {
  if (!userLike) return '';
  return normalizeEmail(
    userLike.accountEmailLower ||
    userLike.emailLower ||
    userLike.accountEmail ||
    userLike.email ||
    ''
  );
}

function isCreatorAdmin(userLike = null) {
  const uid = String(userLike?.uid || userLike?.id || '').trim();
  if (uid === CREATOR_PUBLIC_UID) return true;
  const candidateEmail = getUserAccountEmail(userLike);
  const candidateName = normalizeDisplayName(
    userLike?.name ||
    userLike?.customName ||
    ''
  );
  return candidateEmail === CREATOR_ADMIN_EMAIL && candidateName === normalizeDisplayName(CREATOR_DEFAULT_NAME);
}

function getDisplayName(userLike = null, fallback = 'Unknown User') {
  return (userLike && (userLike.name || userLike.customName)) || fallback;
}

function getDisplayNameKey(value = '') {
  return normalizeDisplayName(value).replace(/\s+/g, ' ');
}

function isCreativeTeamUser(userLike = null) {
  if (!userLike) return false;
  const uid = String(userLike.uid || userLike.id || userLike.userId || '').trim();
  if (uid && CREATIVE_TEAM_UIDS.has(uid)) return true;
  const candidates = [
    userLike.name,
    userLike.customName,
    userLike.displayName,
    userLike.nameLower,
    userLike.customNameLower
  ];
  return candidates.some(value => {
    const key = getDisplayNameKey(value || '');
    return key && CREATIVE_TEAM_DISPLAY_NAMES.has(key);
  });
}

function renderCreativeTeamTagHTML() {
  return '<span class="creative-team-role">Creative Team</span>';
}

function renderDisplayNameHTML(userLike = null, fallback = 'Unknown User', extraClass = '') {
  const classes = ['creator-name'];
  if (extraClass) classes.push(extraClass);
  const nameHtml = escHtml(getDisplayName(userLike, fallback));
  const creativeTeamTag = isCreativeTeamUser(userLike) ? renderCreativeTeamTagHTML() : '';
  if (isCreatorAdmin(userLike)) {
    return `<span class="creator-name-wrap user-badged-name-wrap"><span class="${classes.join(' ')}">👑 ${nameHtml}</span><span class="creator-role">(Creator)</span>${creativeTeamTag}</span>`;
  }
  if (creativeTeamTag) {
    return `<span class="creator-name-wrap user-badged-name-wrap"><span${extraClass ? ` class="${extraClass}"` : ''}>${nameHtml}</span>${creativeTeamTag}</span>`;
  }
  return `<span${extraClass ? ` class="${extraClass}"` : ''}>${nameHtml}</span>`;
}

function shouldExposeInUserSearch(userLike = null) {
  const uid = String(userLike?.uid || userLike?.id || '').trim();
  const email = getUserAccountEmail(userLike);
  const publicFlag = userLike?.isPublic !== false;
  const creatorByUid = uid === CREATOR_PUBLIC_UID;
  const creatorByEmail = email === CREATOR_ADMIN_EMAIL;
  const creatorByFlag = userLike?.isCreatorAdmin === true;
  return publicFlag && (creatorByUid || creatorByEmail || creatorByFlag);
}

function normalizeCreatorPublicUser(raw = {}, uid = '') {
  if (!raw || typeof raw !== 'object') return null;
  const resolvedUid = String(raw.uid || uid || (raw.isCreatorAdmin === true ? CREATOR_PUBLIC_UID : '') || '').trim();
  const email = normalizeEmail(raw.emailLower || raw.accountEmailLower || raw.email || '');
  const user = {
    ...raw,
    uid: resolvedUid,
    name: raw.name || raw.customName || raw.displayName || CREATOR_DEFAULT_NAME,
    photo: raw.photo || raw.customPhoto || '',
    emailLower: email,
    accountEmailLower: normalizeEmail(raw.accountEmailLower || raw.emailLower || raw.email || ''),
    isCreatorAdmin: resolvedUid === CREATOR_PUBLIC_UID || raw.isCreatorAdmin === true || email === CREATOR_ADMIN_EMAIL,
    isPublic: raw.isPublic !== false
  };
  return user.uid ? user : null;
}

function cacheCreatorPublicUser(user = null) {
  if (!user?.uid) return null;
  const normalized = normalizeCreatorPublicUser(user, user.uid);
  if (!normalized) return null;
  usersMap[normalized.uid] = normalized;
  creatorSearchUserCache = normalized;
  try {
    localStorage.setItem(CREATOR_PUBLIC_PROFILE_CACHE_KEY, JSON.stringify({
      uid: normalized.uid,
      name: normalized.name || CREATOR_DEFAULT_NAME,
      customName: normalized.customName || normalized.name || CREATOR_DEFAULT_NAME,
      photo: normalized.photo || normalized.customPhoto || '',
      customPhoto: normalized.customPhoto || normalized.photo || '',
      bio: normalized.bio || normalized.profileBio || '',
      profileBio: normalized.profileBio || normalized.bio || '',
      socialLinks: normalized.socialLinks || getDefaultSocialLinks(),
      pinnedFavorites: normalized.pinnedFavorites || getDefaultPinnedFavorites(),
      showcaseFavorites: normalized.showcaseFavorites || getDefaultShowcaseFavorites(),
      profileVisibility: normalized.profileVisibility || getDefaultProfileVisibility(),
      listTabVisibility: normalized.listTabVisibility || getDefaultListTabVisibility(),
      ratingPreferences: normalized.ratingPreferences || getDefaultRatingPreferences(),
      animeTitleDisplayMode: normalized.animeTitleDisplayMode || getDefaultAnimeTitleDisplayMode(),
      emailLower: CREATOR_ADMIN_EMAIL,
      accountEmailLower: CREATOR_ADMIN_EMAIL,
      isCreatorAdmin: true,
      isPublic: true,
      cachedAt: Date.now()
    }));
  } catch (e) {}
  return normalized;
}

function getCachedCreatorPublicUser() {
  try {
    const raw = localStorage.getItem(CREATOR_PUBLIC_PROFILE_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const user = normalizeCreatorPublicUser(parsed, parsed.uid || CREATOR_PUBLIC_UID);
    if (!user || user.uid !== CREATOR_PUBLIC_UID) return null;
    return shouldExposeInUserSearch(user) ? cacheCreatorPublicUser(user) : null;
  } catch (e) {
    return null;
  }
}

function updateLandingCreatorProfileCard(user = null) {
  const avatar = document.getElementById('landing-profile-avatar');
  if (!avatar) return;
  const photo = (user && (user.photo || user.customPhoto)) || '';
  avatar.src = photo || 'https://ui-avatars.com/api/?name=King%20Kooom&background=1c1535&color=a78bfa';
  avatar.onerror = () => {
    avatar.onerror = null;
    avatar.src = 'https://ui-avatars.com/api/?name=King%20Kooom&background=1c1535&color=a78bfa';
  };
}

async function loadCreatorPublicProfileMirrorRaw() {
  try {
    const snap = await db.collection('publicProfiles').doc(CREATOR_PUBLIC_PROFILE_SLUG).get();
    return snap.exists ? (snap.data() || {}) : null;
  } catch (e) {
    console.warn('Creator public profile mirror unavailable:', e);
    return null;
  }
}

async function loadCreatorPublicProfileMirror() {
  const raw = await loadCreatorPublicProfileMirrorRaw();
  if (!raw) return null;
  const uid = raw.uid || raw.creatorUid || raw.ownerUid || raw.userId || CREATOR_PUBLIC_UID;
  const user = normalizeCreatorPublicUser(raw, uid);
  if (!user || !shouldExposeInUserSearch(user)) return null;
  updateLandingCreatorProfileCard(user);
  return cacheCreatorPublicUser(user);
}

async function loadCreatorSearchUser(force = false) {
  if (!force && creatorSearchUserCache?.uid === CREATOR_PUBLIC_UID) return creatorSearchUserCache;

  try {
    const directSnap = await db.collection('users').doc(CREATOR_PUBLIC_UID).get();
    if (directSnap.exists) {
      const directUser = normalizeCreatorPublicUser({ ...(directSnap.data() || {}), uid: CREATOR_PUBLIC_UID, isCreatorAdmin: true, isPublic: true }, CREATOR_PUBLIC_UID);
      if (directUser && shouldExposeInUserSearch(directUser)) {
        updateLandingCreatorProfileCard(directUser);
        return cacheCreatorPublicUser(directUser);
      }
    }
  } catch (e) {
    console.warn('Creator direct UID lookup failed:', e);
  }

  const mirrorUser = await loadCreatorPublicProfileMirror();
  if (mirrorUser?.uid === CREATOR_PUBLIC_UID) return mirrorUser;

  const queryAttempts = [
    ['accountEmailLower', CREATOR_ADMIN_EMAIL],
    ['emailLower', CREATOR_ADMIN_EMAIL],
    ['accountEmail', CREATOR_ADMIN_EMAIL],
    ['email', CREATOR_ADMIN_EMAIL]
  ];

  for (const [field, value] of queryAttempts) {
    try {
      const snap = await db.collection('users').where(field, '==', value).limit(1).get();
      if (snap.empty) continue;
      const doc = snap.docs[0];
      const user = normalizeCreatorPublicUser({ ...(doc.data() || {}), uid: doc.id }, doc.id);
      if (user?.uid === CREATOR_PUBLIC_UID && shouldExposeInUserSearch(user)) { updateLandingCreatorProfileCard(user); return cacheCreatorPublicUser(user); }
    } catch (e) {
      console.warn(`Creator lookup failed for ${field}:`, e);
    }
  }

  const cachedCreator = getCachedCreatorPublicUser();
  if (cachedCreator) {
    updateLandingCreatorProfileCard(cachedCreator);
    return cachedCreator;
  }

  const creatorShell = normalizeCreatorPublicUser({
    uid: CREATOR_PUBLIC_UID,
    name: CREATOR_DEFAULT_NAME,
    isCreatorAdmin: true,
    isPublic: true
  }, CREATOR_PUBLIC_UID);
  updateLandingCreatorProfileCard(creatorShell);
  return cacheCreatorPublicUser(creatorShell);
}

async function syncCreatorPublicProfileMirror(user = null, profile = null, listSource = null) {
  const email = normalizeEmail(user?.email || profile?.accountEmailLower || profile?.emailLower || profile?.email || '');
  const isCreator = String(user?.uid || '').trim() === CREATOR_PUBLIC_UID || email === CREATOR_ADMIN_EMAIL;
  if (!isCreator || !user?.uid) return;
  const source = normalizeUserProfile(profile || userProfile || {});
  const publicListData = listSource ? cloneListData(listSource) : null;
  const publicPayload = {
    uid: user.uid,
    name: CREATOR_DEFAULT_NAME,
    customName: CREATOR_DEFAULT_NAME,
    nameLower: normalizeDisplayName(CREATOR_DEFAULT_NAME),
    customNameLower: normalizeDisplayName(CREATOR_DEFAULT_NAME),
    photo: source.photo || user.photoURL || '',
    customPhoto: source.photo || user.photoURL || '',
    bio: source.bio || '',
    profileBio: source.bio || '',
    socialLinks: source.socialLinks || getDefaultSocialLinks(),
    pinnedFavorites: source.pinnedFavorites || getDefaultPinnedFavorites(),
    showcaseFavorites: source.showcaseFavorites || getDefaultShowcaseFavorites(),
    profileVisibility: source.profileVisibility || getDefaultProfileVisibility(),
    listTabVisibility: source.listTabVisibility || getDefaultListTabVisibility(),
    ratingPreferences: source.ratingPreferences || getDefaultRatingPreferences(),
    animeTitleDisplayMode: source.animeTitleDisplayMode || getDefaultAnimeTitleDisplayMode(),
    themeMode: source.themeMode || getDefaultThemeMode(),
    emailLower: CREATOR_ADMIN_EMAIL,
    accountEmailLower: CREATOR_ADMIN_EMAIL,
    isCreatorAdmin: true,
    isPublic: true
  };
  if (publicListData) publicPayload.publicListData = publicListData;
  try {
    const mirrorWrite = {
      ...publicPayload,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    };
    if (publicListData) mirrorWrite.publicListUpdatedAt = firebase.firestore.FieldValue.serverTimestamp();
    await db.collection('publicProfiles').doc(CREATOR_PUBLIC_PROFILE_SLUG).set(mirrorWrite, { merge: true });
    cacheCreatorPublicUser(publicPayload);
  } catch (e) {
    console.warn('Creator public profile mirror sync failed:', e);
  }
}

function parsePublicCreatorListData(raw = null) {
  if (!raw || typeof raw !== 'object') return null;
  const source = raw.publicListData || raw.listData || raw.lists || raw.watchlist || raw.library || null;
  if (!source || typeof source !== 'object') return null;
  const parsed = {};
  SCREENLIST_SECTIONS.forEach(section => {
    const value = source[section];
    if (typeof value === 'string') {
      try { parsed[section] = JSON.parse(value); } catch (e) { parsed[section] = []; }
    } else if (Array.isArray(value)) {
      parsed[section] = value;
    } else {
      parsed[section] = [];
    }
  });
  return normalizeListData(parsed);
}

async function loadCreatorPublicListData() {
  const rawMirror = await loadCreatorPublicProfileMirrorRaw();
  const mirrorList = parsePublicCreatorListData(rawMirror);
  if (mirrorList && listDataItemCount(mirrorList) > 0) {
    return await autoSortAnimeBuckets(mirrorList, false);
  }
  const direct = await loadPublicProfileListData(CREATOR_PUBLIC_UID, { suppressError: true });
  if (listDataItemCount(direct) > 0) return direct;
  return direct || getEmptyListData();
}

const SCREENLIST_SECTIONS = ["movies", "shows", "anime", "games", "manga", "books"];
const SCREENLIST_MEDIA_PROFILE_SECTIONS = ["movies", "shows", "anime", "games"];

function getEmptyListData() {
  return SCREENLIST_SECTIONS.reduce((acc, section) => {
    acc[section] = [];
    return acc;
  }, {});
}

function isShowSection(section) {
  return section === "shows" || section === "anime";
}

function isReadingSection(section) {
  return section === "manga" || section === "books";
}

function canOpenLibraryMediaProfile(section) {
  return SCREENLIST_MEDIA_PROFILE_SECTIONS.includes(section);
}

function getDefaultAnimeTitleDisplayMode() {
  return 'english';
}

function normalizeAnimeTitleDisplayMode(value) {
  const mode = String(value || '').trim().toLowerCase();
  if (mode === 'romanji' || mode === 'romaji') return 'romaji';
  if (mode === 'japanese' || mode === 'original') return 'japanese';
  return 'english';
}

function getAnimeTitleDisplayMode(profile = null) {
  const source = profile || (getActiveProfile?.() || userProfile || {});
  return normalizeAnimeTitleDisplayMode(source.animeTitleDisplayMode || source.animeTitleDisplay || getDefaultAnimeTitleDisplayMode());
}

function normalizeAnimeTitleVariants(raw = {}, fallbackTitle = '') {
  const input = raw && typeof raw === 'object' ? raw : {};
  return {
    english: String(input.english || input.englishTitle || fallbackTitle || '').trim(),
    romaji: String(input.romaji || input.romanji || input.romajiTitle || input.title || fallbackTitle || '').trim(),
    japanese: String(input.japanese || input.japaneseTitle || input.original || '').trim()
  };
}

function getAnimeDisplayTitle(item = {}, mode = getAnimeTitleDisplayMode()) {
  const variants = normalizeAnimeTitleVariants(item.titleVariants, item.title || item.name || '');
  const originalTitle = String(item.originalTitle || item.original_name || item.original_title || '').trim();
  if (mode === 'japanese') {
    return variants.japanese || (detectJapaneseScript(originalTitle) ? originalTitle : '') || variants.romaji || variants.english || item.title || item.name || '';
  }
  if (mode === 'romaji') {
    return variants.romaji || variants.english || item.title || item.name || originalTitle || '';
  }
  return variants.english || item.title || item.name || variants.romaji || originalTitle || '';
}

function isAnimeTitleContext(item = {}, sectionHint = '') {
  return sectionHint === 'anime' || item?.mediaCategory === 'anime' || item?.librarySection === 'anime' || item?.isAnime === true;
}

function getDisplayTitleForItem(item = {}, sectionHint = '') {
  if (isAnimeTitleContext(item, sectionHint)) return getAnimeDisplayTitle(item);
  return item?.title || item?.name || '';
}

function getDefaultTabForSection(section) {
  return section === "movies" ? "planned" : "watching";
}

const SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION = {
  shows: ['watching', 'planned', 'watched', 'paused'],
  anime: ['watching', 'planned', 'watched', 'paused'],
  movies: ['planned', 'watched', 'paused'],
  games: ['watching', 'live', 'planned', 'watched'],
  manga: ['watching', 'planned', 'watched', 'paused'],
  books: ['watching', 'planned', 'watched', 'paused']
};

function isVisibleMyListStatusTab(tab = activeTab, section = activeSection) {
  return (SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION[section] || SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION.shows).includes(tab);
}

function normalizeVisibleMyListStatusTab(tab = activeTab, section = activeSection) {
  return isVisibleMyListStatusTab(tab, section) ? tab : getDefaultTabForSection(section);
}

function getMyListStatusLabel(status = '', section = activeSection) {
  if (status === 'live') return 'Live Games';
  if (status === 'watching') {
    if (section === 'games') return 'Playing';
    return isReadingSection(section) ? 'Reading' : 'Watching';
  }
  if (status === 'planned') {
    if (section === 'games') return 'Backlog';
    return isReadingSection(section) ? 'TBR' : 'Watchlist';
  }
  if (status === 'watched') {
    if (section === 'games') return 'Played';
    return isReadingSection(section) ? 'Read' : 'Watched';
  }
  if (status === 'paused') return 'Paused';
  if (status === 'dropped') return 'Dropped';
  return String(status || '');
}

function getMyListStatusButtonConfigs(section = activeSection) {
  return (SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION[section] || SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION.shows)
    .map(status => ({ status, label: getMyListStatusLabel(status, section) }));
}


function getSectionLabel(section, singular = false) {
  if (section === "movies") return singular ? "movie" : "movies";
  if (section === "anime") return singular ? "anime" : "anime";
  if (section === "games") return singular ? "game" : "games";
  if (section === "manga") return singular ? "manga" : "manga";
  if (section === "books") return singular ? "book" : "books";
  return singular ? "show" : "shows";
}

function getSectionIcon(section) {
  if (section === "movies") return "🎬";
  if (section === "anime") return "🌸";
  if (section === "games") return "🎮";
  if (section === "manga") return "📚";
  if (section === "books") return "📖";
  return "📺";
}

function getAddButtonSectionLabel(section) {
  if (section === 'anime') return 'Anime';
  if (section === 'shows') return 'Show';
  if (section === 'movies') return 'Movie';
  if (section === 'games') return 'Game';
  if (section === 'manga') return 'Manga';
  if (section === 'books') return 'Book';
  return 'Title';
}

function getDefaultRatingPreferences() {
  return { media: 'ten', games: 'ten' };
}

function getDefaultThemeMode() {
  return 'default';
}

function normalizeThemeMode(value) {
  return value === 'light' || value === 'true-dark' ? value : 'default';
}

function normalizeRatingPreferences(raw) {
  const defaults = getDefaultRatingPreferences();
  if (raw && typeof raw === 'object') {
    defaults.media = raw.media === 'five' ? 'five' : 'ten';
    defaults.games = raw.games === 'five' ? 'five' : 'ten';
  }
  return defaults;
}

function getRatingPreferenceKeyForSection(section = '') {
  return section === 'games' ? 'games' : 'media';
}

function getRatingPreferencesForProfile(profile = null) {
  if (profile) return normalizeRatingPreferences(profile.ratingPreferences);
  if (viewingUser && !isViewingOtherProfile()) {
    return normalizeRatingPreferences(
      viewingUser.ratingPreferences ||
      usersMap[viewingUser.uid || '']?.ratingPreferences
    );
  }
  return normalizeRatingPreferences((getActiveProfile?.() || userProfile || {}).ratingPreferences);
}

function getRatingPreferenceForSection(section = '', profile = null) {
  const prefs = getRatingPreferencesForProfile(profile);
  return prefs[getRatingPreferenceKeyForSection(section)] || 'ten';
}

function getRatingStepCountForSection(section = '', profile = null) {
  return getRatingPreferenceForSection(section, profile) === 'five' ? 5 : 10;
}

function isFivePointRatingSection(section = '', profile = null) {
  return getRatingPreferenceForSection(section, profile) === 'five';
}

function formatRatingValueForSection(value, section = '', withSuffix = false, emptyValue = '') {
  const numeric = Number(value || 0);
  if (!(numeric > 0)) return emptyValue;
  if (isFivePointRatingSection(section)) {
    const display = numeric / 2;
    const text = Number.isInteger(display) ? String(display) : display.toFixed(1);
    return withSuffix ? `${text}/5` : text;
  }
  const text = Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(1);
  return withSuffix ? `${text}/10` : text;
}

function formatAverageRatingForSection(list = [], section = '') {
  const rated = list.filter(item => Number(item.rating || 0) > 0);
  if (!rated.length) return 'N/A';
  const avg = rated.reduce((sum, item) => sum + Number(item.rating || 0), 0) / rated.length;
  return formatRatingValueForSection(avg, section, true, 'N/A');
}

function getRatingSectionForDiscoverType(type = '') {
  if (type === 'game') return 'games';
  if (activeDiscoveryHub === 'anime') return 'anime';
  if (type === 'movie') return 'movies';
  return 'shows';
}

function buildRatingStarsMarkup(rating, itemId, prefix, size, section, interactive = true) {
  const stepCount = getRatingStepCountForSection(section);
  const currentRating = Number(rating || 0);
  const classes = ['stars'];
  if (stepCount === 5) classes.push('rating-scale-five');
  const attrs = interactive
    ? ` data-item-id="${itemId}" data-prefix="${prefix}" data-section="${section}"
    ontouchstart="starsTouchStart(event)"
    ontouchmove="starsTouchMove(event)"
    ontouchend="starsTouchEnd(event)"`
    : '';
  let html = `<div class="${classes.join(' ')}" style="--star-size:${size}px;"${attrs}>`;
  if (stepCount === 5) {
    for (let star = 1; star <= 5; star++) {
      const leftVal = star * 2 - 1;
      const rightVal = star * 2;
      if (interactive) {
        html += `<button class="star-btn half-step left ${leftVal <= currentRating ? 'lit' : ''}" style="font-size:${size}px" data-mylist-rate-item-id="${escAttr(itemId)}" data-mylist-rate-prefix="${escAttr(prefix)}" data-mylist-rate-score="${leftVal}"
          onclick="event.stopPropagation();rate('${itemId}','${prefix}',${leftVal})"
          onmouseenter="hoverStars(this,${leftVal})" onmouseleave="unhoverStars(this,${currentRating})">★</button>`;
        html += `<button class="star-btn half-step right ${rightVal <= currentRating ? 'lit' : ''}" style="font-size:${size}px" data-mylist-rate-item-id="${escAttr(itemId)}" data-mylist-rate-prefix="${escAttr(prefix)}" data-mylist-rate-score="${rightVal}"
          onclick="event.stopPropagation();rate('${itemId}','${prefix}',${rightVal})"
          onmouseenter="hoverStars(this,${rightVal})" onmouseleave="unhoverStars(this,${currentRating})">★</button>`;
      } else {
        html += `<span class="star-btn half-step left ${leftVal <= currentRating ? 'lit' : ''}" style="font-size:${size}px;cursor:default;">★</span>`;
        html += `<span class="star-btn half-step right ${rightVal <= currentRating ? 'lit' : ''}" style="font-size:${size}px;cursor:default;">★</span>`;
      }
    }
  } else {
    for (let s = 1; s <= 10; s++) {
      if (interactive) {
        html += `<button class="star-btn ${s <= currentRating ? 'lit' : ''}" style="font-size:${size}px" data-mylist-rate-item-id="${escAttr(itemId)}" data-mylist-rate-prefix="${escAttr(prefix)}" data-mylist-rate-score="${s}"
          onclick="event.stopPropagation();rate('${itemId}','${prefix}',${s})"
          onmouseenter="hoverStars(this,${s})" onmouseleave="unhoverStars(this,${currentRating})">★</button>`;
      } else {
        html += `<span class="star-btn ${s <= currentRating ? 'lit' : ''}" style="font-size:${size}px;cursor:default;">★</span>`;
      }
    }
  }
  if (currentRating > 0) html += `<span class="star-label">${formatRatingValueForSection(currentRating, section)}</span>`;
  html += `</div>`;
  return html;
}

function buildStandaloneRatingStarsMarkup(selectedRating = 0, section = '', clickHandler = '') {
  const stepCount = getRatingStepCountForSection(section);
  const classes = ['stars', 'discover-rating-stars'];
  if (stepCount === 5) classes.push('rating-scale-five');
  let stars = `<div class="${classes.join(' ')}" data-discover-rating="${selectedRating}" data-section="${section}" style="--star-size:18px;">`;
  if (stepCount === 5) {
    for (let star = 1; star <= 5; star++) {
      const leftVal = star * 2 - 1;
      const rightVal = star * 2;
      stars += `<button class="star-btn half-step left ${leftVal <= selectedRating ? 'lit' : ''}" onclick="${clickHandler}(${leftVal})" onmouseenter="hoverStars(this,${leftVal})" onmouseleave="unhoverStars(this,${selectedRating})">★</button>`;
      stars += `<button class="star-btn half-step right ${rightVal <= selectedRating ? 'lit' : ''}" onclick="${clickHandler}(${rightVal})" onmouseenter="hoverStars(this,${rightVal})" onmouseleave="unhoverStars(this,${selectedRating})">★</button>`;
    }
  } else {
    for (let i = 1; i <= 10; i++) {
      stars += `<button class="star-btn ${i <= selectedRating ? 'lit' : ''}" onclick="${clickHandler}(${i})" onmouseenter="hoverStars(this,${i})" onmouseleave="unhoverStars(this,${selectedRating})">★</button>`;
    }
  }
  if (selectedRating > 0) stars += `<span class="star-label">${formatRatingValueForSection(selectedRating, section)}</span>`;
  stars += `</div>`;
  return stars;
}

function detectJapaneseScript(value) {
  return /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff]/.test(String(value || ""));
}

function detectKoreanScript(value) {
  return /[\u1100-\u11ff\u3130-\u318f\uac00-\ud7af]/.test(String(value || ""));
}

function toGenreNameList(item) {
  if (Array.isArray(item?.genreNames)) {
    return item.genreNames.map(name => String(name || '').trim().toLowerCase()).filter(Boolean);
  }
  return String(item?.genre || '')
    .split(',')
    .map(name => name.trim().toLowerCase())
    .filter(Boolean);
}

function toOriginCountryList(item) {
  if (Array.isArray(item?.originCountries)) {
    return item.originCountries.map(code => String(code || '').trim().toUpperCase()).filter(Boolean);
  }
  return String(item?.originCountries || '')
    .split(',')
    .map(code => code.trim().toUpperCase())
    .filter(Boolean);
}

function detectAnimeFromMetadata(item) {
  const genres = toGenreNameList(item);
  const hasAnimationGenre = genres.includes('animation');
  if (!hasAnimationGenre) return false;

  const originalLanguage = String(item?.originalLanguage || '').trim().toLowerCase();
  const originCountries = toOriginCountryList(item);
  const originalTitle = item?.originalTitle || item?.originalName || '';
  const title = item?.title || '';
  const hasJapaneseSignal =
    originalLanguage === 'ja' ||
    originCountries.includes('JP') ||
    detectJapaneseScript(originalTitle) ||
    detectJapaneseScript(title);

  return hasJapaneseSignal;
}

function isAnimeDiscoverCandidate(item) {
  if (!item || typeof item !== 'object') return false;
  const genreIds = Array.isArray(item.genre_ids) ? item.genre_ids : [];
  const hasAnimationGenre = genreIds.includes(16) || toGenreNameList(item).includes('animation');
  if (!hasAnimationGenre) return false;

  const originalLanguage = String(item.original_language || item.originalLanguage || '').trim().toLowerCase();
  const originCountries = Array.isArray(item.origin_country)
    ? item.origin_country.map(code => String(code || '').trim().toUpperCase()).filter(Boolean)
    : toOriginCountryList(item);
  const titleSignals = [
    item.original_name,
    item.originalTitle,
    item.name,
    item.title
  ].filter(Boolean);
  const hasRegionalSignal =
    originalLanguage === 'ja' ||
    originalLanguage === 'ko' ||
    originCountries.includes('JP') ||
    originCountries.includes('KR') ||
    titleSignals.some(value => detectJapaneseScript(value) || detectKoreanScript(value));

  return hasRegionalSignal;
}

function resolveShowSection(item, fallbackSection = "shows") {
  if (!isShowSection(fallbackSection)) return fallbackSection;
  const explicit = String(item?.librarySection || item?.mediaCategory || '').trim().toLowerCase();
  if (explicit === 'anime') return 'anime';
  if (explicit === 'shows' || explicit === 'show' || explicit === 'tv') return 'shows';
  return detectAnimeFromMetadata(item) ? 'anime' : 'shows';
}

function normalizeListEntry(item, fallbackSection) {
  if (!item || typeof item !== 'object') return null;
  const next = { ...item };
  if (isShowSection(fallbackSection)) {
    const resolvedSection = resolveShowSection(next, fallbackSection);
    next.mediaCategory = resolvedSection;
    next.librarySection = resolvedSection;
    next.isAnime = resolvedSection === 'anime';
  } else {
    next.librarySection = fallbackSection;
  }
  return next;
}

function normalizeListData(source) {
  const normalized = getEmptyListData();
  const input = source && typeof source === 'object' ? source : {};

  ["movies", "games", "manga", "books"].forEach(section => {
    const items = Array.isArray(input[section]) ? input[section] : [];
    normalized[section] = items
      .map(item => normalizeListEntry(item, section))
      .filter(Boolean);
  });

  ["shows", "anime"].forEach(section => {
    const items = Array.isArray(input[section]) ? input[section] : [];
    items.forEach(item => {
      const normalizedItem = normalizeListEntry(item, section);
      if (!normalizedItem) return;
      normalized[resolveShowSection(normalizedItem, section)].push(normalizedItem);
    });
  });

  return JSON.parse(JSON.stringify(normalized));
}

async function hydrateShowMetadataFromTmdb(item) {
  if (!item?.tmdbId) return false;
  try {
    const res = await fetchTmdbProxy(`tv/${item.tmdbId}`);
    if (!res.ok) return false;
    const d = await res.json();
    item.genre = (d.genres || []).map(g => g.name).join(', ');
    item.genreNames = (d.genres || []).map(g => g.name).filter(Boolean);
    item.originalTitle = d.original_name || item.originalTitle || '';
    item.originalLanguage = d.original_language || item.originalLanguage || '';
    item.originCountries = Array.isArray(d.origin_country) ? d.origin_country : (item.originCountries || []);
    item.mediaCategory = detectAnimeFromMetadata(item) ? 'anime' : 'shows';
    item.librarySection = item.mediaCategory;
    item.isAnime = item.mediaCategory === 'anime';
    return true;
  } catch (e) {
    console.error('Anime classification refresh failed:', e);
    return false;
  }
}

async function autoSortAnimeBuckets(source, persist = false) {
  const working = cloneListData(source);
  const candidates = [...(working.shows || []), ...(working.anime || [])]
    .filter(item => item?.tmdbId)
    .filter(item =>
      !item.librarySection ||
      !item.mediaCategory ||
      !item.originalLanguage ||
      !Array.isArray(item.originCountries) ||
      !Array.isArray(item.genreNames)
    );

  let enriched = false;
  for (const item of candidates) {
    const changed = await hydrateShowMetadataFromTmdb(item);
    enriched = enriched || changed;
  }

  const normalized = normalizeListData(working);
  if (!enriched && isSameListData(normalized, source)) return normalized;

  if (persist && currentUser && !viewingUser) {
    await writeOwnDataDirect(normalized);
  }

  return normalized;
}

let data = getEmptyListData();
let ownDataCache = null; // durable in-session copy of the signed-in user's own library
let friendViewData = null; // isolated data for a friend's profile; never used for saving your own list
let viewingReturnTab = 'mylist';
function cloneListData(source) {
  return normalizeListData(source);
}

function getCompactImportedAnimeItem(item = {}) {
  if (!item || typeof item !== 'object') return item;
  const isMalImport = String(item.source || '').toLowerCase() === 'myanimelist' || !!item.bulkImportCompact;
  if (!isMalImport) return item;
  const next = { ...item };
  const episodes = Array.isArray(next.episodes) ? next.episodes : [];
  const total = Number(next.totalEps || next.totalEpisodes || episodes.length || 0);
  const watched = episodes.length
    ? episodes.filter(ep => ep && ep.watched).length
    : Number(next.currentEp || next.watchedEpisodes || 0);
  next.totalEpisodes = total;
  next.totalEps = total;
  next.currentEp = next.status === 'watched' ? total : Math.max(0, Math.min(total || Infinity, watched));
  next.episodes = [];
  next.bulkImportCompact = true;
  return next;
}

function compactImportedAnimeForStorage(source) {
  const safe = cloneListData(source);
  safe.anime = (safe.anime || []).map(item => getCompactImportedAnimeItem(item));
  return safe;
}

function getVisibleListData() {
  return viewingUser && friendViewData ? friendViewData : data;
}
function listDataSignature(source) {
  return JSON.stringify(cloneListData(source));
}
function isSameListData(a, b) {
  return !!a && !!b && listDataSignature(a) === listDataSignature(b);
}
function listDataItemCount(source) {
  const d = cloneListData(source);
  return SCREENLIST_SECTIONS.reduce((sum, section) => sum + (d[section] || []).length, 0);
}
function readOwnLocalBackup(excludeData = null) {
  const keys = [];
  if (currentUser) keys.push("screenlist-own-data-backup-" + currentUser.uid);
  keys.push("watchlist-tracker-data");
  for (const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) continue;
      const parsed = cloneListData(JSON.parse(raw));
      if (listDataItemCount(parsed) === 0) continue;
      if (excludeData && isSameListData(parsed, excludeData)) continue;
      return parsed;
    } catch(e) {}
  }
  return null;
}
async function writeOwnDataDirect(nextData) {
  const safeData = compactImportedAnimeForStorage(nextData);
  data = cloneListData(safeData);
  ownDataCache = cloneListData(safeData);
  if (currentUser) localStorage.setItem("screenlist-own-data-backup-" + currentUser.uid, JSON.stringify(safeData));
  localStorage.setItem("watchlist-tracker-data", JSON.stringify(safeData));
  if (DOC_REF) {
    await DOC_REF.set({
      shows: JSON.stringify(safeData.shows),
      movies: JSON.stringify(safeData.movies),
      anime: JSON.stringify(safeData.anime),
      games: JSON.stringify(safeData.games),
      manga: JSON.stringify(safeData.manga),
      books: JSON.stringify(safeData.books),
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true });
    if (currentUser?.uid === CREATOR_PUBLIC_UID) {
      await syncCreatorPublicProfileMirror(currentUser, userProfile, safeData);
    }
  }
  return safeData;
}
async function loadOwnDataFromFirestore() {
  if (!DOC_REF) return ownDataCache ? cloneListData(ownDataCache) : cloneListData(data);
  try {
    const snap = await DOC_REF.get();
    if (!snap.exists) return getEmptyListData();
    const d = snap.data();
    return normalizeListData({
      shows: d.shows ? JSON.parse(d.shows) : [],
      movies: d.movies ? JSON.parse(d.movies) : [],
      anime: d.anime ? JSON.parse(d.anime) : [],
      games: d.games ? JSON.parse(d.games) : [],
      manga: d.manga ? JSON.parse(d.manga) : [],
      books: d.books ? JSON.parse(d.books) : []
    });
  } catch(e) {
    console.error("Own library reload failed:", e);
    return ownDataCache ? cloneListData(ownDataCache) : cloneListData(data);
  }
}
let activeSection = "shows";
let activeTab = "watching";
let activeDiscoveryHub = "tv";
let searchQuery = "";
let openStates = {};
let saveTimeout = null;

// Sort state — session-only (resets on page refresh/leave, never persisted)
let sessionSortState = {};   // { "section:tab": sortKey }
let sessionCustomOrder = {}; // { "section:tab": [id, ...] }
const DEFAULT_SORT = 'recently-added';
const WATCHED_RATING_DEFAULT_SECTIONS = new Set(['movies', 'shows', 'anime']);
const SORT_OPTIONS = [
  { key: 'recently-added',    label: 'Recently Added' },
  { key: 'recently-edited',   label: 'Recently Edited' },
  { key: 'title-az',          label: 'Title A–Z' },
  { key: 'rating-high',       label: 'Highest Rated' },
  { key: 'rating-low',        label: 'Lowest Rated' },
  { key: 'release-newest',    label: 'Newest Release' },
  { key: 'release-oldest',    label: 'Oldest Release' },
  { key: 'custom',            label: 'Custom Order' },
];

function getSortStateKey(section = activeSection, tab = activeTab) { return section + ':' + tab; }
function getDefaultSortKeyFor(section = activeSection, tab = activeTab) {
  if (tab === 'watching' && (section === 'shows' || section === 'anime')) return 'recently-edited';
  if (tab === 'watched' && WATCHED_RATING_DEFAULT_SECTIONS.has(section)) return 'rating-high';
  return DEFAULT_SORT;
}
function getActiveSortKey() { return sessionSortState[getSortStateKey()] || getDefaultSortKeyFor(); }

function setSortOrder(key) {
  const stateKey = getSortStateKey();
  sessionSortState[stateKey] = key;
  if (key === 'custom' && !sessionCustomOrder[stateKey]) {
    const visibleData = getVisibleListData();
    const items = (visibleData[activeSection] || []).filter(i => i.status === activeTab);
    sessionCustomOrder[stateKey] = applySortOrder(items, getDefaultSortKeyFor(), stateKey).map(i => i.id);
  }
  closeSortDropdown();
  render();
}

function applySortOrder(items, sortKey, stateKey) {
  const arr = [...items];
  switch (sortKey) {
    case 'recently-added':
      return arr.sort((a, b) =>
        new Date(b.dateAdded || 0) - new Date(a.dateAdded || 0));
    case 'recently-edited':
      return arr.sort((a, b) =>
        new Date(b.dateModified || b.dateAdded || 0) - new Date(a.dateModified || a.dateAdded || 0));
    case 'title-az':
      return arr.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
    case 'rating-high':
      return arr.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    case 'rating-low':
      return arr.sort((a, b) => (a.rating || 0) - (b.rating || 0));
    case 'release-newest':
      return arr.sort((a, b) => (parseInt(b.year) || 0) - (parseInt(a.year) || 0));
    case 'release-oldest':
      return arr.sort((a, b) => (parseInt(a.year) || 0) - (parseInt(b.year) || 0));
    case 'custom': {
      const order = (stateKey && sessionCustomOrder[stateKey]) || [];
      if (!order.length) return arr;
      const idx = {};
      order.forEach((id, i) => { idx[id] = i; });
      return arr.sort((a, b) =>
        (idx[a.id] !== undefined ? idx[a.id] : 9999) -
        (idx[b.id] !== undefined ? idx[b.id] : 9999));
    }
    default:
      return arr;
  }
}

function closeSortDropdown() {
  const m = document.getElementById('sort-dropdown-menu');
  if (m) m.remove();
}

function toggleSortDropdown(e) {
  if (e) e.stopPropagation();
  const existing = document.getElementById('sort-dropdown-menu');
  if (existing) { existing.remove(); return; }
  const btn = document.getElementById('sort-dropdown-btn');
  if (!btn) return;
  const activeSortKey = getActiveSortKey();
  const menu = document.createElement('div');
  menu.id = 'sort-dropdown-menu';
  menu.className = 'sort-dropdown-menu';
  SORT_OPTIONS.forEach(opt => {
    const el = document.createElement('button');
    el.className = 'sort-dropdown-item' + (opt.key === activeSortKey ? ' active' : '');
    el.textContent = opt.label;
    el.onclick = () => setSortOrder(opt.key);
    menu.appendChild(el);
  });
  document.body.appendChild(menu);
  const rect = btn.getBoundingClientRect();
  menu.style.top = (rect.bottom + window.scrollY + 4) + 'px';
  const rightOffset = window.innerWidth - rect.right;
  menu.style.right = rightOffset + 'px';
  setTimeout(() => document.addEventListener('click', closeSortDropdown, { once: true }), 0);
}

function touchItem(item) {
  if (item) item.dateModified = new Date().toISOString();
  return item;
}

// Custom order drag-and-drop
let _dragSrcId = null;
function onCardDragStart(e, id) {
  _dragSrcId = id;
  e.dataTransfer.effectAllowed = 'move';
}
function onCardDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  const card = e.currentTarget;
  card.classList.add('drag-over');
}
function onCardDragLeave(e) {
  e.currentTarget.classList.remove('drag-over');
}
function onCardDrop(e, id) {
  e.preventDefault();
  e.currentTarget.classList.remove('drag-over');
  if (!_dragSrcId || _dragSrcId === id) return;
  const stateKey = getSortStateKey();
  let order = sessionCustomOrder[stateKey] ? [...sessionCustomOrder[stateKey]] : [];
  const from = order.indexOf(_dragSrcId);
  const to = order.indexOf(id);
  if (from === -1 || to === -1) return;
  order.splice(from, 1);
  order.splice(to, 0, _dragSrcId);
  sessionCustomOrder[stateKey] = order;
  _dragSrcId = null;
  render();
}
