let screenListAddAudioContext = null;
function getScreenListAddAudioContext() {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return null;
  if (!screenListAddAudioContext) screenListAddAudioContext = new AudioCtx();
  return screenListAddAudioContext;
}

function armScreenListAddSound() {
  const ctx = getScreenListAddAudioContext();
  if (ctx && ctx.state === 'suspended') ctx.resume().catch(() => {});
}

document.addEventListener('pointerdown', armScreenListAddSound, { passive: true });

function playLibraryAddPopSound() {
  try {
    const ctx = getScreenListAddAudioContext();
    if (!ctx) return;
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});
    const now = ctx.currentTime;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.055, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.15);
    gain.connect(ctx.destination);

    const pop = ctx.createOscillator();
    pop.type = 'triangle';
    pop.frequency.setValueAtTime(520, now);
    pop.frequency.exponentialRampToValueAtTime(920, now + 0.08);
    pop.connect(gain);
    pop.start(now);
    pop.stop(now + 0.16);

    const shineGain = ctx.createGain();
    shineGain.gain.setValueAtTime(0.0001, now);
    shineGain.gain.exponentialRampToValueAtTime(0.025, now + 0.026);
    shineGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.18);
    shineGain.connect(ctx.destination);
    const shine = ctx.createOscillator();
    shine.type = 'sine';
    shine.frequency.setValueAtTime(1240, now + 0.018);
    shine.frequency.exponentialRampToValueAtTime(1640, now + 0.11);
    shine.connect(shineGain);
    shine.start(now + 0.018);
    shine.stop(now + 0.19);
  } catch (e) {}
}

function clearListSearch() {
  searchQuery = "";
  const input = document.querySelector(".search-input");
  if (input) input.value = "";
}

function chooseInitialListView(listData) {
  const sectionOrder = ["movies", "shows", "anime", "games", "manga", "books"].filter(section => isSectionVisibleInMyLists(section));
  const statusOrderBySection = SCREENLIST_VISIBLE_STATUS_TABS_BY_SECTION;

  for (const section of sectionOrder) {
    const statuses = statusOrderBySection[section];
    const items = Array.isArray(listData[section]) ? listData[section] : [];
    for (const status of statuses) {
      if (items.some(item => item.status === status)) {
        return { section, tab: status };
      }
    }
  }
  return { section: "movies", tab: "planned" };
}

// 120Hz frame-locked no-effect page jumps for internal mobile page switches.
// This intentionally does not fade, slide, scale, or blur anything; it only aligns the DOM swap to high-refresh frames.
const SCREENLIST_INTERNAL_PAGE_JUMP_FPS = 120;
const SCREENLIST_INTERNAL_PAGE_JUMP_FRAME_MS = 1000 / SCREENLIST_INTERNAL_PAGE_JUMP_FPS;
const SCREENLIST_INTERNAL_PAGE_JUMP_MS = 90;
const SCREENLIST_MYLIST_PAGE_JUMP_MS = 300;
const SCREENLIST_MYLIST_PAGE_SWIPE_MS = 380;
let myListInternalPageJumpToken = 0;
let myListClickSwipeToken = 0;

function isScreenListMobileInternalJumpLayout() {
  return window.matchMedia && window.matchMedia('(max-width: 700px), (hover: none) and (pointer: coarse)').matches;
}

function runScreenListFrameLockedJump(callback, shouldCancel = () => false, durationMs = SCREENLIST_INTERNAL_PAGE_JUMP_MS) {
  const run = () => {
    if (shouldCancel()) return;
    try { callback(); } catch (error) { console.error('ScreenList frame-locked page jump failed:', error); }
  };

  if (!isScreenListMobileInternalJumpLayout() || document.hidden) {
    run();
    return;
  }

  const duration = Math.max(SCREENLIST_INTERNAL_PAGE_JUMP_FRAME_MS, Number(durationMs) || SCREENLIST_INTERNAL_PAGE_JUMP_MS);
  const targetFrameCount = Math.max(1, Math.round(duration / SCREENLIST_INTERNAL_PAGE_JUMP_FRAME_MS));
  const start = performance.now();
  let hasRun = false;
  let lastFrame = -1;

  function tick(now) {
    if (shouldCancel()) return;
    const elapsed = Math.max(0, now - start);
    const frame = Math.min(targetFrameCount, Math.floor(elapsed / SCREENLIST_INTERNAL_PAGE_JUMP_FRAME_MS));
    if (frame !== lastFrame) {
      lastFrame = frame;
      if (!hasRun) {
        hasRun = true;
        run();
      }
    }
    if (elapsed < duration) {
      requestAnimationFrame(tick);
    } else if (!hasRun) {
      hasRun = true;
      run();
    }
  }

  requestAnimationFrame(tick);
}

function runMyListInternalPageJump(callback) {
  const token = ++myListInternalPageJumpToken;
  runScreenListFrameLockedJump(callback, () => token !== myListInternalPageJumpToken, SCREENLIST_MYLIST_PAGE_JUMP_MS);
}


function getMyListSwipeMotion(selector, attrName, currentValue, nextValue) {
  const nodes = Array.from(document.querySelectorAll(selector))
    .filter(node => node && node.style.display !== 'none' && !node.hidden && node.offsetWidth > 0);
  const currentIndex = nodes.findIndex(node => node.dataset[attrName] === currentValue);
  const nextIndex = nodes.findIndex(node => node.dataset[attrName] === nextValue);
  if (currentIndex < 0 || nextIndex < 0 || currentIndex === nextIndex) {
    return { direction: 'left', path: [currentValue, nextValue].filter(Boolean) };
  }
  const low = Math.min(currentIndex, nextIndex);
  const high = Math.max(currentIndex, nextIndex);
  const values = nodes.slice(low, high + 1).map(node => node.dataset[attrName]).filter(Boolean);
  const path = nextIndex > currentIndex ? values : values.reverse();
  return { direction: nextIndex > currentIndex ? 'left' : 'right', path };
}

function getMyListSwipeSurface() {
  if (document.body.classList.contains('true-dark-mode')) return '#000';
  if (document.body.classList.contains('light-mode')) return '#f7f5ff';
  return '#050410';
}

function getMyListSwipeContentTop() {
  // Always anchor to toolbar bottom so the swipe only covers content below "Add to Shelf".
  // Using toolbar.getBoundingClientRect().bottom is scroll-position–independent.
  const toolbar = document.getElementById('mylist-toolbar');
  if (toolbar) {
    const rect = toolbar.getBoundingClientRect();
    if (rect && Number.isFinite(rect.bottom) && rect.bottom > 0) return rect.bottom;
  }
  // Fallback: use cards-grid top if visible in viewport
  const candidates = [document.getElementById('cards-grid'), document.getElementById('empty-state')];
  for (const node of candidates) {
    if (!node || node.style.display === 'none') continue;
    const rect = node.getBoundingClientRect();
    if (rect && Number.isFinite(rect.top) && rect.top > 0) return rect.top;
  }
  return 0;
}

function setMyListSwipeLiveContentHidden(hidden) {
  ['cards-grid', 'empty-state'].forEach(id => {
    const node = document.getElementById(id);
    if (!node) return;
    if (hidden) {
      if (node.dataset.myListSwipeVisibility === undefined) node.dataset.myListSwipeVisibility = node.style.visibility || '';
      node.style.visibility = 'hidden';
    } else {
      node.style.visibility = node.dataset.myListSwipeVisibility || '';
      delete node.dataset.myListSwipeVisibility;
    }
  });
}

function cleanMyListSwipeClone(node) {
  if (!node) return node;
  node.style.visibility = '';
  node.style.transition = '';
  node.style.transform = '';
  node.style.willChange = '';
  node.querySelectorAll('[style]').forEach(child => {
    if (child.style.visibility === 'hidden') child.style.visibility = '';
    child.style.transition = '';
    child.style.transform = '';
    child.style.willChange = '';
  });
  return node;
}

function forceMyListSwipeLayoutFlush() {
  const grid = document.getElementById('cards-grid');
  const empty = document.getElementById('empty-state');
  const target = grid && grid.style.display !== 'none' ? grid : empty;
  if (!target) return;
  target.getBoundingClientRect();
  void target.offsetHeight;
}

function buildMyListSwipeSnapshot(top) {
  const container = document.querySelector('#mylist-view .container, #mylist-view .main-content') || document.querySelector('#mylist-view');
  const cs = container ? window.getComputedStyle(container) : null;
  const snap = document.createElement('div');
  snap.className = 'mylist-page-swipe-out';
  snap.style.cssText =
    `position:fixed;top:${Math.max(0, top)}px;left:0;right:0;bottom:0;z-index:700;` +
    `pointer-events:none;background:${getMyListSwipeSurface()};overflow:hidden;` +
    `will-change:transform;contain:layout paint style;-webkit-backface-visibility:hidden;backface-visibility:hidden;`;
  const inner = document.createElement('div');
  inner.style.cssText = `padding-left:${cs ? cs.paddingLeft : '12px'};padding-right:${cs ? cs.paddingRight : '12px'};`;
  const grid = document.getElementById('cards-grid');
  const empty = document.getElementById('empty-state');
  if (grid) inner.appendChild(cleanMyListSwipeClone(grid.cloneNode(true)));
  if (empty && empty.style.display !== 'none') inner.appendChild(cleanMyListSwipeClone(empty.cloneNode(true)));
  snap.appendChild(inner);
  document.body.appendChild(snap);
  return snap;
}

function buildMyListSwipePanel(containerStyle) {
  const panel = document.createElement('div');
  panel.className = 'mylist-page-swipe-panel';
  const inner = document.createElement('div');
  inner.style.cssText = `padding-left:${containerStyle ? containerStyle.paddingLeft : '12px'};padding-right:${containerStyle ? containerStyle.paddingRight : '12px'};`;
  const grid = document.getElementById('cards-grid');
  const empty = document.getElementById('empty-state');
  if (grid) inner.appendChild(cleanMyListSwipeClone(grid.cloneNode(true)));
  if (empty && empty.style.display !== 'none') inner.appendChild(cleanMyListSwipeClone(empty.cloneNode(true)));
  panel.appendChild(inner);
  return panel;
}

function buildMyListSwipeTrack(top, motion) {
  const path = Array.isArray(motion?.path) ? motion.path.filter(Boolean) : [];
  if (path.length < 2 || typeof motion.applyPathState !== 'function') return null;
  const container = document.querySelector('#mylist-view .container, #mylist-view .main-content') || document.querySelector('#mylist-view');
  const containerStyle = container ? window.getComputedStyle(container) : null;
  const values = motion.direction === 'right' ? path.slice().reverse() : path.slice();
  const track = document.createElement('div');
  track.className = 'mylist-page-swipe-track';
  track.style.cssText =
    `position:fixed;top:${Math.max(0, top)}px;left:0;right:0;bottom:0;z-index:700;` +
    `pointer-events:none;background:${getMyListSwipeSurface()};overflow:hidden;` +
    `contain:layout paint style;-webkit-backface-visibility:hidden;backface-visibility:hidden;`;
  const strip = document.createElement('div');
  strip.className = 'mylist-page-swipe-strip';
  strip.style.width = `${values.length * 100}vw`;
  values.forEach(value => {
    motion.applyPathState(value);
    render();
    strip.appendChild(buildMyListSwipePanel(containerStyle));
  });
  track.appendChild(strip);
  document.body.appendChild(track);
  return { track, strip, panelCount: values.length };
}

function clearMyListSwipeTransforms() {
  ['cards-grid', 'empty-state'].forEach(id => {
    const node = document.getElementById(id);
    if (!node) return;
    node.style.transition = '';
    node.style.transform = '';
    node.style.willChange = '';
  });
}

function runMyListSwipeTransition(motionInput, applyState) {
  const token = ++myListClickSwipeToken;
  if (_sw) _swCancel();

  const motion = typeof motionInput === 'string'
    ? { direction: motionInput }
    : { direction: 'left', ...(motionInput || {}) };

  if (!isScreenListMobileInternalJumpLayout() || document.hidden) {
    applyState();
    render();
    persistUiState();
    requestAnimationFrame(() => updateSlidingPills());
    return;
  }

  document.querySelectorAll('.mylist-page-swipe-out, .mylist-page-swipe-track').forEach(node => node.remove());
  clearMyListSwipeTransforms();

  const top = getMyListSwipeContentTop();
  const width = Math.max(1, window.innerWidth || document.documentElement.clientWidth || 390);
  const ease = `transform ${SCREENLIST_MYLIST_PAGE_SWIPE_MS}ms cubic-bezier(0.22, 1, 0.36, 1)`;
  const trackState = buildMyListSwipeTrack(top, motion);

  applyState();
  render();
  updateSlidingPills();
  const finalTop = getMyListSwipeContentTop();
  if (trackState?.track) trackState.track.style.top = `${Math.max(0, finalTop)}px`;

  if (trackState) {
    setMyListSwipeLiveContentHidden(true);
    const { track, strip, panelCount } = trackState;
    const startX = motion.direction === 'right' ? -width * (panelCount - 1) : 0;
    const endX = motion.direction === 'right' ? 0 : -width * (panelCount - 1);
    strip.style.transition = 'none';
    strip.style.transform = `translate3d(${startX}px,0,0)`;
    requestAnimationFrame(() => {
      if (token !== myListClickSwipeToken) return;
      strip.style.transition = ease;
      strip.style.transform = `translate3d(${endX}px,0,0)`;
    });
    window.setTimeout(() => {
      if (token !== myListClickSwipeToken) return;
      persistUiState();
      requestAnimationFrame(() => {
        forceMyListSwipeLayoutFlush();
        if (track.parentNode) track.remove();
        setMyListSwipeLiveContentHidden(false);
        requestAnimationFrame(() => {
          clearMyListSwipeTransforms();
          updateSlidingPills();
        });
      });
    }, SCREENLIST_MYLIST_PAGE_SWIPE_MS + 40);
    return;
  }

  const snap = buildMyListSwipeSnapshot(finalTop);
  const incomingX = motion.direction === 'left' ? width : -width;
  const outgoingX = motion.direction === 'left' ? -width : width;

  requestAnimationFrame(() => {
    if (token !== myListClickSwipeToken) return;
    const grid = document.getElementById('cards-grid');
    const empty = document.getElementById('empty-state');
    [grid, empty].forEach(node => {
      if (!node || node.style.display === 'none') return;
      node.style.transition = 'none';
      node.style.willChange = 'transform';
      node.style.transform = `translate3d(${incomingX}px,0,0)`;
    });
    requestAnimationFrame(() => {
      if (token !== myListClickSwipeToken) return;
      snap.style.transition = ease;
      snap.style.transform = `translate3d(${outgoingX}px,0,0)`;
      [grid, empty].forEach(node => {
        if (!node || node.style.display === 'none') return;
        node.style.transition = ease;
        node.style.transform = 'translate3d(0,0,0)';
      });
    });
  });

  window.setTimeout(() => {
    if (token !== myListClickSwipeToken) return;
    persistUiState();
    requestAnimationFrame(() => {
      forceMyListSwipeLayoutFlush();
      if (snap.parentNode) snap.remove();
      setMyListSwipeLiveContentHidden(false);
      requestAnimationFrame(() => {
        clearMyListSwipeTransforms();
        updateSlidingPills();
      });
    });
  }, SCREENLIST_MYLIST_PAGE_SWIPE_MS + 40);
}

// Actions
function switchSection(s) {
  if (!isSectionVisibleInMyLists(s)) return;
  if (activeSection === s) return;
  const motion = getMyListSwipeMotion('#mylist-view #mylist-header .section-btn', 'section', activeSection, s);
  motion.applyPathState = section => {
    activeSection = section;
    activeTab = getDefaultTabForSection(section);
  };
  closeSortDropdown();
  runMyListSwipeTransition(motion, () => {
    activeSection = s;
    activeTab = getDefaultTabForSection(s);
  });
}
function switchTab(t) {
  if (!isVisibleMyListStatusTab(t, activeSection)) return;
  if (activeTab === t) return;
  const motion = getMyListSwipeMotion('#mylist-view #mylist-toolbar .tab-btn', 'tab', activeTab, t);
  motion.applyPathState = tab => { activeTab = tab; };
  closeSortDropdown();
  runMyListSwipeTransition(motion, () => {
    activeTab = t;
  });
}

// ── Swipe-between-status-tabs ────────────────────────────────────────────────
let _sw = null;
let _swPillLock = false; // prevents updateSlidingPills from interfering mid-swipe

function initMyListSwipe() {
  const view = document.getElementById('mylist-view');
  if (!view) return;
  // v269: My Lists is click-only again. Do not bind touch swipe handlers.
  // Category/status buttons still use the smooth internal click transition.
  view._swipeReady = true;
  if (_sw) _swCancel();
}

function _swVisibleTabs() {
  return Array.from(document.querySelectorAll('#mylist-view #mylist-toolbar .tab-btn'))
    .filter(b => b.style.display !== 'none' && b.offsetWidth > 0);
}

function _swAdjacentTab(dir) {
  const tabs = _swVisibleTabs();
  const i = tabs.findIndex(b => b.dataset.tab === activeTab);
  if (i === -1) return null;
  if (dir === 'left'  && i < tabs.length - 1) return tabs[i + 1].dataset.tab;
  if (dir === 'right' && i > 0)               return tabs[i - 1].dataset.tab;
  return null;
}

function getMyListSwipeTouchZone(target) {
  if (!target || !target.closest) return null;
  return target.closest('#mylist-view #cards-grid, #mylist-view #empty-state');
}

function _swStart(e) {
  // v269: gesture-based My Lists status swiping was removed.
  // Status/category changes now happen only through button taps.
  return;
}

function startMyListFingerSwipe(dir, next) {
  if (!_sw || _sw.live) return;
  const origTab = activeTab;
  const width = Math.max(1, window.innerWidth || document.documentElement.clientWidth || 390);
  const top = getMyListSwipeContentTop();
  const container = document.querySelector('#mylist-view .container, #mylist-view .main-content') || document.querySelector('#mylist-view');
  const containerStyle = container ? window.getComputedStyle(container) : null;

  const tabsEl = document.querySelector('#mylist-view #mylist-toolbar .tabs');
  const fromBtn = tabsEl && tabsEl.querySelector(`.tab-btn[data-tab="${origTab}"]`);
  const fromX = fromBtn ? fromBtn.offsetLeft : 0;
  const fromY = fromBtn ? fromBtn.offsetTop : 0;
  const fromW = fromBtn ? fromBtn.offsetWidth : 0;
  const fromH = fromBtn ? fromBtn.offsetHeight : 0;

  const outgoingPanel = buildMyListSwipePanel(containerStyle);
  setMyListSwipeLiveContentHidden(true);
  _swPillLock = true;

  activeTab = next;
  render();
  const incomingPanel = buildMyListSwipePanel(containerStyle);
  const toBtn = tabsEl && tabsEl.querySelector(`.tab-btn[data-tab="${next}"]`);
  const toX = toBtn ? toBtn.offsetLeft : fromX;
  const toW = toBtn ? toBtn.offsetWidth : fromW;

  forceMyListSwipeLayoutFlush();

  const pillEl = tabsEl && tabsEl.querySelector('.tab-sliding-pill');
  if (pillEl) {
    pillEl.style.transition = 'none';
    pillEl.style.width = fromW + 'px';
    pillEl.style.height = fromH + 'px';
    pillEl.style.transform = `translate3d(${fromX}px,${fromY}px,0)`;
  }

  const track = document.createElement('div');
  track.className = 'mylist-page-swipe-track mylist-finger-swipe-track';
  track.style.cssText =
    `position:fixed;top:${Math.max(0, top)}px;left:0;right:0;bottom:0;z-index:700;` +
    `pointer-events:none;background:${getMyListSwipeSurface()};overflow:hidden;` +
    `contain:layout paint style;-webkit-backface-visibility:hidden;backface-visibility:hidden;`;

  const strip = document.createElement('div');
  strip.className = 'mylist-page-swipe-strip';
  strip.style.width = '200vw';
  if (dir === 'left') {
    strip.appendChild(outgoingPanel);
    strip.appendChild(incomingPanel);
  } else {
    strip.appendChild(incomingPanel);
    strip.appendChild(outgoingPanel);
  }
  const startX = dir === 'right' ? -width : 0;
  strip.style.transition = 'none';
  strip.style.transform = `translate3d(${startX}px,0,0)`;
  track.appendChild(strip);
  document.body.appendChild(track);

  _sw.dir = dir;
  _sw.nextTab = next;
  _sw.origTab = origTab;
  _sw.live = true;
  _sw.sw = width;
  _sw.track = track;
  _sw.strip = strip;
  _sw.startX = startX;
  _sw.pillEl = pillEl;
  _sw.pillFromX = fromX;
  _sw.pillFromY = fromY;
  _sw.pillToX = toX;
  _sw.pillFromW = fromW;
  _sw.pillToW = toW;
}

function renderMyListFingerSwipeFrame() {
  if (!_sw || !_sw.live) return;
  _sw.raf = 0;
  const dx = _sw.frameX || 0;
  const sw = Math.max(1, _sw.sw || 1);
  const clampedDx = _sw.dir === 'left'
    ? Math.max(-sw, Math.min(0, dx))
    : Math.max(0, Math.min(sw, dx));
  const frac = Math.min(1, Math.max(0, Math.abs(clampedDx) / sw));

  if (_sw.strip) _sw.strip.style.transform = `translate3d(${(_sw.startX || 0) + clampedDx}px,0,0)`;
  if (_sw.pillEl) {
    _sw.pillEl.style.transform = `translate3d(${_sw.pillFromX + (_sw.pillToX - _sw.pillFromX) * frac}px,${_sw.pillFromY}px,0)`;
    _sw.pillEl.style.width = (_sw.pillFromW + (_sw.pillToW - _sw.pillFromW) * frac) + 'px';
  }
}

function queueMyListFingerSwipeFrame(dx) {
  if (!_sw || !_sw.live) return;
  _sw.frameX = dx;
  if (_sw.raf) return;
  _sw.raf = requestAnimationFrame(renderMyListFingerSwipeFrame);
}

function _swMove(e) {
  if (!_sw || _sw.canceled) return;
  const touch = e.touches && e.touches[0];
  if (!touch) return;
  const dx = touch.clientX - _sw.x0;
  const dy = touch.clientY - _sw.y0;
  _sw.dx = dx;

  if (!_sw.live) {
    if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
    if (Math.abs(dy) >= Math.abs(dx) * 0.86) { _sw.canceled = true; return; }
    const dir = dx < 0 ? 'left' : 'right';
    const next = _swAdjacentTab(dir);
    if (!next) {
      // Consume horizontal edge swipes inside My Lists content so Safari/app shell does not create a full-page swipe effect.
      if (Math.abs(dx) > 14 && Math.abs(dx) > Math.abs(dy) * 1.15) e.preventDefault();
      _sw.canceled = true;
      return;
    }
    startMyListFingerSwipe(dir, next);
  }

  e.preventDefault();
  queueMyListFingerSwipeFrame(dx);
}

function finishMyListFingerSwipe(nextTab, callback) {
  activeTab = nextTab;
  render();
  forceMyListSwipeLayoutFlush();
  requestAnimationFrame(() => {
    callback?.();
    forceMyListSwipeLayoutFlush();
    requestAnimationFrame(() => {
      setMyListSwipeLiveContentHidden(false);
      updateSlidingPills();
    });
  });
}

function _swEnd() {
  if (!_sw) return;
  if (!_sw.live) { _sw = null; return; }

  const state = _sw;
  _sw = null;
  if (state.raf) cancelAnimationFrame(state.raf);

  const dx = state.dx || 0;
  const sw = Math.max(1, state.sw || 1);
  const vel = Math.abs(dx) / Math.max(1, Date.now() - state.t0);
  const threshold = Math.min(sw * 0.28, 92);
  const commit = Math.abs(dx) > threshold || vel > 0.48;
  const ease = 'transform 260ms cubic-bezier(0.22,1,0.36,1)';
  const endX = state.dir === 'left' ? -sw : 0;
  const cancelX = state.startX || 0;

  if (state.strip) {
    state.strip.style.transition = ease;
    state.strip.style.transform = `translate3d(${commit ? endX : cancelX}px,0,0)`;
  }
  if (state.pillEl) {
    state.pillEl.style.transition = ease;
    state.pillEl.style.transform = commit
      ? `translate3d(${state.pillToX}px,${state.pillFromY}px,0)`
      : `translate3d(${state.pillFromX}px,${state.pillFromY}px,0)`;
    state.pillEl.style.width = (commit ? state.pillToW : state.pillFromW) + 'px';
  }

  window.setTimeout(() => {
    _swPillLock = false;
    finishMyListFingerSwipe(commit ? state.nextTab : state.origTab, () => {
      if (state.track && state.track.parentNode) state.track.remove();
      if (state.pillEl) state.pillEl.style.transition = '';
      persistUiState();
    });
  }, 265);
}

function _swCancel() {
  if (!_sw || !_sw.live) { _sw = null; return; }
  const state = _sw;
  _sw = null;
  if (state.raf) cancelAnimationFrame(state.raf);
  _swPillLock = false;
  activeTab = state.origTab;
  render();
  if (state.track && state.track.parentNode) state.track.remove();
  setMyListSwipeLiveContentHidden(false);
  if (state.pillEl) state.pillEl.style.transition = '';
  requestAnimationFrame(() => updateSlidingPills());
}
// ─────────────────────────────────────────────────────────────────────────────

function positionSlidingPill(container, activeBtn, pillClass) {
  if (!container || !activeBtn) return;
  let pill = container.querySelector('.' + pillClass);
  const isNew = !pill;
  if (!pill) {
    pill = document.createElement('span');
    pill.className = pillClass + ' pill-init';
    container.appendChild(pill);
  }
  const x = activeBtn.offsetLeft;
  const y = activeBtn.offsetTop;
  const w = activeBtn.offsetWidth;
  const h = activeBtn.offsetHeight;
  // Width + height set directly (no transition) — only transform animates
  pill.style.width = w + 'px';
  pill.style.height = h + 'px';
  pill.style.transform = 'translate3d(' + x + 'px,' + y + 'px,0)';
  if (isNew) {
    // Two rAFs: first commits the paint, second enables spring transition
    requestAnimationFrame(() => requestAnimationFrame(() => pill.classList.remove('pill-init')));
  }
}

function updateSlidingPills() {
  if (_swPillLock) return; // swipe is driving the pill manually — don't interfere
  const sectionToggle = document.querySelector('#mylist-view #mylist-header .section-toggle');
  const activeSecBtn = sectionToggle && sectionToggle.querySelector('.section-btn.active');
  if (sectionToggle && activeSecBtn) positionSlidingPill(sectionToggle, activeSecBtn, 'section-sliding-pill');

  const tabsContainer = document.querySelector('#mylist-view #mylist-toolbar .tabs');
  const activeTabBtn = tabsContainer && tabsContainer.querySelector('.tab-btn.active');
  if (tabsContainer && activeTabBtn) positionSlidingPill(tabsContainer, activeTabBtn, 'tab-sliding-pill');
}


async function goToDefaultMyListsPage() {
  try {
    if (typeof isDirectMessagesPageOpen === 'function' && isDirectMessagesPageOpen()) {
      closeDirectMessagesPage(true);
    }
  } catch (error) {
    console.warn('Default My Lists shortcut skipped DM close:', error);
  }

  try {
    const mediaOverlay = document.getElementById('discover-media-profile');
    if (mediaOverlay && typeof closeMediaProfileOverlayImmediately === 'function') {
      closeMediaProfileOverlayImmediately(mediaOverlay);
    }
  } catch (error) {
    console.warn('Default My Lists shortcut skipped media profile close:', error);
  }

  try {
    if (document.body.classList.contains('profile-active') && typeof closeProfile === 'function') {
      closeProfile();
    }
  } catch (error) {
    console.warn('Default My Lists shortcut skipped profile close:', error);
  }

  closeSortDropdown();
  if (typeof clearListSearch === 'function') clearListSearch();
  activeSection = 'shows';
  activeTab = 'watching';
  if (viewingUser && typeof backToMyList === 'function') {
    await backToMyList('mylist');
    activeSection = 'shows';
    activeTab = 'watching';
  }
  setBottomNavVisibility(true);
  syncMainNavButtons('mylist');
  setMainNavVisibility('mylist');
  render();
  persistUiState();

  const myListView = document.getElementById('mylist-view');
  if (myListView && typeof myListView.scrollTo === 'function') myListView.scrollTo({ top: 0, behavior: 'auto' });
  window.scrollTo({ top: 0, behavior: 'auto' });
}
