function removeWatchTogetherGroupFromLocalState(groupId = '') {
  if (!groupId) return;
  watchTogetherGroups = watchTogetherGroups.filter(group => group && group.id !== groupId);
  watchTogetherIncomingRequests = watchTogetherIncomingRequests.filter(group => group && group.id !== groupId);
  watchTogetherOutgoingRequests = watchTogetherOutgoingRequests.filter(group => group && group.id !== groupId);
  watchTogetherIncomingRequestIds = watchTogetherIncomingRequestIds.filter(id => id !== groupId);
  watchTogetherOutgoingRequestIds = watchTogetherOutgoingRequestIds.filter(id => id !== groupId);
  watchTogetherApprovedRequestIds = watchTogetherApprovedRequestIds.filter(id => id !== groupId);
  delete watchTogetherIncomingRequestPayloadMap[groupId];
  delete watchTogetherOutgoingRequestPayloadMap[groupId];
  delete watchTogetherApprovedRequestPayloadMap[groupId];
}

function getWatchTogetherGroupParticipantUids(group = {}) {
  return [...new Set([
    group.ownerUid,
    ...(Array.isArray(group.participantUids) ? group.participantUids : []),
    ...(Array.isArray(group.pendingUids) ? group.pendingUids : []),
    ...(Array.isArray(group.approvedUids) ? group.approvedUids : []),
    ...(Array.isArray(group.rejectedUids) ? group.rejectedUids : [])
  ].filter(Boolean))];
}

function getWatchTogetherGroupsTouchingItemForCurrentUser(item = {}, section = activeSection) {
  if (!currentUser || !canUseWatchTogetherSection(section)) return [];
  const allGroups = mergeWatchTogetherGroupsById(
    watchTogetherGroups,
    getWatchTogetherMirroredPayloadGroups()
  );
  return allGroups.filter(group => {
    if (!group || !group.id || !watchTogetherGroupMatchesItem(group, item, section)) return false;
    const touchedUids = getWatchTogetherGroupParticipantUids(group);
    return group.ownerUid === currentUser.uid || touchedUids.includes(currentUser.uid);
  });
}

async function clearWatchTogetherGroupEverywhere(group = {}) {
  const groupId = group.id || '';
  if (!groupId) return;
  const uids = getWatchTogetherGroupParticipantUids(group);
  await Promise.all(uids.flatMap(uid => [
    clearWatchTogetherRequestMirror(uid, 'incoming', groupId),
    clearWatchTogetherRequestMirror(uid, 'outgoing', groupId),
    clearWatchTogetherApprovedMirror(uid, groupId)
  ]));
  removeWatchTogetherGroupFromLocalState(groupId);
}

async function detachCurrentUserFromWatchTogetherGroup(group = {}) {
  if (!currentUser || !group?.id) return;
  const groupId = group.id;
  if (group.ownerUid === currentUser.uid) {
    await clearWatchTogetherGroupEverywhere(group);
    return;
  }

  const uid = currentUser.uid;
  const pendingUids = Array.isArray(group.pendingUids) ? group.pendingUids.filter(Boolean) : [];
  const approvedUids = Array.isArray(group.approvedUids) ? group.approvedUids.filter(Boolean) : [];
  const remainingPending = pendingUids.filter(memberUid => memberUid !== uid);
  const remainingApproved = approvedUids.filter(memberUid => memberUid !== uid);
  const remainingParticipants = (Array.isArray(group.participantUids) ? group.participantUids : []).filter(memberUid => memberUid !== uid);
  const hasApprovedPartner = remainingApproved.some(memberUid => memberUid && memberUid !== group.ownerUid);
  const hasPendingPartner = remainingPending.length > 0;

  if (!hasApprovedPartner && !hasPendingPartner) {
    await clearWatchTogetherGroupEverywhere(group);
    return;
  }

  const nextStatus = hasPendingPartner ? 'pending' : 'approved';
  const updatedGroup = {
    ...group,
    pendingUids: remainingPending,
    approvedUids: remainingApproved,
    participantUids: remainingParticipants,
    status: nextStatus,
    updatedAtMs: Date.now()
  };

  const writes = [
    clearWatchTogetherRequestMirror(uid, 'incoming', groupId),
    clearWatchTogetherRequestMirror(uid, 'outgoing', groupId),
    clearWatchTogetherApprovedMirror(uid, groupId)
  ];

  if (remainingPending.length) {
    writes.push(setWatchTogetherRequestMirror(group.ownerUid, 'outgoing', groupId, updatedGroup, { includeInRequestList: true }));
    writes.push(...remainingPending.map(memberUid => setWatchTogetherRequestMirror(memberUid, 'incoming', groupId, updatedGroup)));
  } else {
    writes.push(clearWatchTogetherRequestMirror(group.ownerUid, 'outgoing', groupId));
  }
  writes.push(...remainingApproved.map(memberUid => setWatchTogetherApprovedMirror(memberUid, groupId, updatedGroup)));

  await Promise.all(writes);
  removeWatchTogetherGroupFromLocalState(groupId);
}

async function cleanupWatchTogetherForDeletedItem(item = {}, section = activeSection) {
  if (!currentUser || !item || !canUseWatchTogetherSection(section)) return;
  const groups = getWatchTogetherGroupsTouchingItemForCurrentUser(item, section);
  if (!groups.length) return;
  await Promise.all(groups.map(group => detachCurrentUserFromWatchTogetherGroup(group)));
  watchTogetherAverageCache = {};
  updateRequestsBadges();
  if (activeFriendsTab === 'activity' && isWatchActivitySubTab()) renderActiveWatchActivitySubTab(true);
}

function resetDeleteButton(btn) {
  if (!btn) return;
  btn.dataset.confirmDelete = '';
  btn.textContent = '×';
  btn.style.color = '#5c5278';
  btn.style.fontSize = '16px';
  btn.title = 'Delete';
}

function deleteItem(eventOrId, maybeId) {
  const clickEvent = maybeId !== undefined ? eventOrId : window.event;
  const id = String(maybeId !== undefined ? maybeId : eventOrId);
  const btn = clickEvent?.currentTarget || clickEvent?.target;
  clickEvent?.stopPropagation?.();
  if (!id || viewingUser) return;

  if (btn && btn.dataset.confirmDelete !== id) {
    btn.dataset.confirmDelete = id;
    btn.textContent = '✓';
    btn.style.color = '#ef4444';
    btn.style.fontSize = '14px';
    btn.title = 'Tap again to confirm';
    setTimeout(() => {
      if (btn.dataset.confirmDelete === id) resetDeleteButton(btn);
    }, 1500);
    return;
  }

  const sectionAtDelete = activeSection;
  const deletedItem = (data[sectionAtDelete] || []).find(item => String(item.id) === id);
  data[sectionAtDelete] = (data[sectionAtDelete] || []).filter(item => String(item.id) !== id);
  save();
  render();

  if (deletedItem) {
    cleanupWatchTogetherForDeletedItem(deletedItem, sectionAtDelete).catch(error => {
      console.warn('Shared Watch cleanup after library delete failed:', error);
      showToast('Removed from library. Shared Watch cleanup will retry when you reopen.');
    });
  }
}

let _lastRate = { key: null, time: 0 };
function rate(itemId, prefix, score) {
  // Debounce: ignore identical rate within 350ms (prevents touch+click double-fire from toggling off)
  const key = itemId + '|' + prefix + '|' + score;
  const now = Date.now();
  if (_lastRate.key === key && now - _lastRate.time < 350) return;
  _lastRate = { key, time: now };

  const items = data[activeSection];
  const item = items.find(i => i.id === itemId);
  if (!item) return;
  if (prefix === "overall") {
    item.rating = item.rating === score ? 0 : score;
  } else if (prefix.startsWith("season:")) {
    const sNum = parseInt(prefix.slice(7));
    if (!item.seasonRatings) item.seasonRatings = {};
    item.seasonRatings[sNum] = (item.seasonRatings[sNum] === score) ? 0 : score;
  } else if (prefix.startsWith("ep:")) {
    const epId = prefix.slice(3);
    const ep = (item.episodes || []).find(e => e.id === epId);
    if (ep) ep.rating = ep.rating === score ? 0 : score;
  }
  touchItem(item);
  save(); render();
  if (score > 0) playRatingAnimation(itemId, prefix);
}

function playRatingAnimation(itemId, prefix) {
  // Look up the actual score from the data so animation intensity matches
  const item = data[activeSection].find(i => i.id === itemId);
  if (!item) return;
  let score = 0;
  if (prefix === 'overall') score = item.rating || 0;
  else if (prefix.startsWith('season:')) {
    const sNum = parseInt(prefix.slice(7));
    score = (item.seasonRatings && item.seasonRatings[sNum]) || 0;
  }
  if (score < 1) return;

  // Map score (1-10) to 0-1 intensity, ramps faster at top
  const t = Math.pow(score / 10, 1.3);
  const peakScale = 1.3 + t * 0.7;       // 1.34 → 2.0
  const midScale  = 1.05 + t * 0.18;
  const glow      = 5 + t * 16;          // 5.5 → 21px
  const glowAlpha = 0.5 + t * 0.5;       // 0.53 → 1.0
  const stagger   = (0.07 - t * 0.04) * 1000;
  const duration  = 380 + t * 240;
  const isPerfect = score === 10;

  // ONE drop-shadow only — color shifts toward magenta at high scores instead of stacking shadows
  // (multiple drop-shadows are GPU-expensive and cause the stutter you saw)
  const glowR = Math.round(251 - t * 15);  // 251 → 236
  const glowG = Math.round(191 - t * 119); // 191 → 72
  const glowB = Math.round(36 + t * 117);  // 36 → 153
  const peakFilter = `drop-shadow(0 0 ${glow}px rgba(${glowR},${glowG},${glowB},${glowAlpha}))`;

  requestAnimationFrame(() => {
    const containers = document.querySelectorAll('.stars');
    containers.forEach(c => {
      if (c.dataset.itemId !== itemId || c.dataset.prefix !== prefix) return;
      const lit = [...c.querySelectorAll('.star-btn.lit')];
      lit.forEach((star, i) => {
        // Tell the browser to promote this element to its own GPU layer for the animation
        star.style.willChange = 'transform, filter';
        const anim = star.animate([
          { transform: 'scale(1)', filter: 'none' },
          { transform: `scale(${peakScale})`, filter: peakFilter, offset: 0.3 },
          { transform: `scale(${midScale})`, filter: 'none', offset: 0.6 },
          { transform: 'scale(1)', filter: 'none' }
        ], { duration, delay: i * stagger, easing: 'ease-out', fill: 'none' });
        anim.onfinish = () => { star.style.willChange = ''; };
      });

      const label = c.querySelector('.star-label');
      if (label) {
        label.style.willChange = 'transform, color';
        const lAnim = label.animate([
          { transform: 'scale(1)', color: '' },
          { transform: `scale(${1.15 + t * 0.35})`, color: '#fbbf24', offset: 0.4 },
          { transform: 'scale(1)', color: '' }
        ], { duration: 500 + t * 180, delay: 100 + t * 70, easing: 'ease-out' });
        lAnim.onfinish = () => { label.style.willChange = ''; };
      }

      if (isPerfect) spawnPerfectBurst(c);
    });
  });
}

function spawnPerfectBurst(container) {
  const burst = document.createElement('div');
  burst.style.cssText = `
    position:absolute; inset:-10px; border-radius:8px; pointer-events:none;
    background: radial-gradient(circle, rgba(251,191,36,0.45), rgba(236,72,153,0.2) 50%, transparent 70%);
    z-index:0;
  `;
  const oldPos = getComputedStyle(container).position;
  if (oldPos === 'static') container.style.position = 'relative';
  container.appendChild(burst);
  burst.animate([
    { opacity: 0, transform: 'scale(0.6)' },
    { opacity: 1, transform: 'scale(1.1)', offset: 0.3 },
    { opacity: 0, transform: 'scale(1.6)' }
  ], { duration: 700, easing: 'ease-out' }).onfinish = () => burst.remove();
}

function hoverStars(btn, val) {
  const container = btn.parentElement;
  const section = container?.dataset?.section || container?.closest?.('#ep-rating-popup')?.dataset?.section || activeSection;
  container.querySelectorAll('.star-btn').forEach((b, i) => {
    b.style.color = (i + 1) <= val ? '#f59e0b' : '#443d60';
    b.style.transform = (i + 1) <= val ? 'scale(1.2)' : 'scale(1)';
  });
  let label = container.querySelector('.star-label');
  if (!label) {
    label = document.createElement('span');
    label.className = 'star-label';
    container.appendChild(label);
  }
  label.textContent = formatRatingValueForSection(val, section);
}
function unhoverStars(btn, rating) {
  const container = btn.parentElement;
  const section = container?.dataset?.section || container?.closest?.('#ep-rating-popup')?.dataset?.section || activeSection;
  container.querySelectorAll('.star-btn').forEach((b, i) => {
    b.style.color = (i + 1) <= rating ? '#f59e0b' : '#443d60';
    b.style.transform = 'scale(1)';
  });
  const label = container.querySelector('.star-label');
  if (label) label.textContent = rating > 0 ? formatRatingValueForSection(rating, section) : '';
}

// Touch scrub for overall + season star ratings
function starsTouchStart(e) {
  const c = e.currentTarget;
  c.dataset.touchStartX = e.touches[0].clientX;
  c.dataset.touchStartY = e.touches[0].clientY;
  c.dataset.scrubVal = '0';
  c.dataset.scrubbing = 'false';
}
function starsTouchMove(e) {
  const c = e.currentTarget;
  const section = c?.dataset?.section || activeSection;
  const touch = e.touches[0];
  const dx = Math.abs(touch.clientX - parseFloat(c.dataset.touchStartX || 0));
  const dy = Math.abs(touch.clientY - parseFloat(c.dataset.touchStartY || 0));
  // Need at least 10px of horizontal-dominant motion before locking in scrub mode
  // (prevents tap jitter from being misread as a scrub)
  if (c.dataset.scrubbing !== 'true') {
    if (dx < 10 || dy > dx) return;
  }
  c.dataset.scrubbing = 'true';
  e.preventDefault();
  const stars = [...c.querySelectorAll('.star-btn')];
  let val = 0;
  stars.forEach((btn, i) => {
    if (touch.clientX >= btn.getBoundingClientRect().left) val = i + 1;
  });
  if (val >= 1) {
    c.dataset.scrubVal = val;
    stars.forEach((b, i) => {
      b.style.color = (i + 1) <= val ? '#f59e0b' : '#443d60';
      b.style.transform = (i + 1) <= val ? 'scale(1.2)' : 'scale(1)';
    });
    let label = c.querySelector('.star-label');
    if (!label) {
      label = document.createElement('span');
      label.className = 'star-label';
      c.appendChild(label);
    }
    label.textContent = formatRatingValueForSection(val, section);
  }
}
function starsTouchEnd(e) {
  const c = e.currentTarget;
  if (c.dataset.scrubbing !== 'true') return;
  const val = parseInt(c.dataset.scrubVal || 0);
  if (val > 0) {
    e.preventDefault();
    rate(c.dataset.itemId, c.dataset.prefix, val);
  }
  c.dataset.scrubVal = '0';
  c.dataset.scrubbing = 'false';
}

function setEpisodesExpanded(list, shouldOpen, immediate) {
  if (!list) return;
  if (list._episodesTransitionHandler) {
    list.removeEventListener('transitionend', list._episodesTransitionHandler);
    list._episodesTransitionHandler = null;
  }

  const startHeight = list.getBoundingClientRect().height;
  const content = list.querySelector('.ep-list-inner');

  if (shouldOpen) {
    list.classList.add('open');
    if (immediate) {
      list.style.height = 'auto';
      return;
    }
    list.style.height = startHeight + 'px';
    const targetHeight = content ? Math.ceil(content.getBoundingClientRect().height) : list.scrollHeight;
    void list.offsetHeight;
    list.style.height = targetHeight + 'px';
  } else {
    list.style.height = startHeight + 'px';
    void list.offsetHeight;
    list.classList.remove('open');
    if (immediate) {
      list.style.height = '0px';
      return;
    }
    list.style.height = '0px';
  }

  const onTransitionEnd = (e) => {
    if (e.propertyName !== 'height') return;
    if (shouldOpen) {
      requestAnimationFrame(() => {
        if (list.classList.contains('open')) list.style.height = 'auto';
      });
    }
    list.removeEventListener('transitionend', onTransitionEnd);
    list._episodesTransitionHandler = null;
  };

  list._episodesTransitionHandler = onTransitionEnd;
  list.addEventListener('transitionend', onTransitionEnd);
}

function getMyListSafeScrollOffset() {
  const bodyPad = parseFloat(getComputedStyle(document.body).paddingTop || '0') || 0;
  return Math.max(88, bodyPad + 58);
}

function getSmoothScrollProgress(t) {
  const clamped = Math.max(0, Math.min(1, t));
  return clamped * clamped * (3 - 2 * clamped);
}

function animateWindowScrollTo(targetY, duration = 300) {
  const startY = window.scrollY || window.pageYOffset || 0;
  const maxY = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
  const endY = Math.max(0, Math.min(targetY, maxY));
  const delta = endY - startY;
  if (Math.abs(delta) < 2) return;
  const token = (animateWindowScrollTo._token || 0) + 1;
  animateWindowScrollTo._token = token;
  const start = performance.now();
  const step = now => {
    if (animateWindowScrollTo._token !== token) return;
    const t = Math.min(1, (now - start) / duration);
    window.scrollTo(0, startY + delta * getSmoothScrollProgress(t));
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function animateScrollContainerTo(scroller, targetY, duration = 300) {
  if (!scroller) return;
  const startY = scroller.scrollTop || 0;
  const maxY = Math.max(0, scroller.scrollHeight - scroller.clientHeight);
  const endY = Math.max(0, Math.min(targetY, maxY));
  const delta = endY - startY;
  if (Math.abs(delta) < 2) return;
  const token = (scroller._screenlistScrollToken || 0) + 1;
  scroller._screenlistScrollToken = token;
  const start = performance.now();
  const step = now => {
    if (scroller._screenlistScrollToken !== token) return;
    const t = Math.min(1, (now - start) / duration);
    scroller.scrollTop = startY + delta * getSmoothScrollProgress(t);
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function scrollElementNearViewportTop(el, offset = getMyListSafeScrollOffset(), duration = 300) {
  if (!el) return;
  requestAnimationFrame(() => {
    const rect = el.getBoundingClientRect();
    animateWindowScrollTo((window.scrollY || window.pageYOffset || 0) + rect.top - offset, duration);
  });
}

function scrollSeasonHeaderToEpisodeDropdownTop(seasonHeader, duration = 300) {
  if (!seasonHeader) return;
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const scroller = seasonHeader.closest('.ep-scroll');
      if (!scroller) return;
      const scrollerRect = scroller.getBoundingClientRect();
      const headerRect = seasonHeader.getBoundingClientRect();
      const target = scroller.scrollTop + headerRect.top - scrollerRect.top;
      animateScrollContainerTo(scroller, target, duration);
    });
  });
}

function toggleEpisodes(id) {
  const list = document.getElementById('ep-list-' + id);
  const arrow = document.getElementById('ep-arrow-' + id);
  const label = document.getElementById('ep-label-' + id);
  if (!list) return;
  const open = list.classList.contains('open');
  setEpisodesExpanded(list, !open, false);
  arrow.classList.toggle('open', !open);
  label.textContent = open ? 'Show Episodes' : 'Hide Episodes';
  openStates['ep-' + id] = !open;
  if (open) return;
  scrollElementNearViewportTop(document.getElementById('card-' + id), getMyListSafeScrollOffset(), 300);
  backfillSeasonMetadataForExistingShow(id, activeSection);
}

function preserveEpisodeScroll(itemId, action) {
  const scrollEl = document.querySelector(`#ep-list-${itemId} .ep-scroll`);
  const scrollTop = scrollEl ? scrollEl.scrollTop : 0;
  action();
  requestAnimationFrame(() => {
    const nextScrollEl = document.querySelector(`#ep-list-${itemId} .ep-scroll`);
    if (nextScrollEl) nextScrollEl.scrollTop = scrollTop;
  });
}

function preserveViewport(action) {
  const scrollX = window.scrollX;
  const scrollY = window.scrollY;
  action();
  requestAnimationFrame(() => {
    window.scrollTo({ left: scrollX, top: scrollY, behavior: 'auto' });
  });
}

function itemMatchesCurrentView(item) {
  return item.status === activeTab &&
    (!searchQuery || (item.title || '').toLowerCase().includes(searchQuery.toLowerCase()));
}

function getEpisodeProgress(item) {
  return getCompactEpisodeStats(item);
}

function updateEpisodeRowState(ep) {
  const row = document.getElementById('ep-row-' + ep.id);
  if (!row) return;
  row.classList.toggle('watched-ep', !!ep.watched);
  const check = row.querySelector('.ep-check');
  if (!check) return;
  check.classList.toggle('checked', !!ep.watched);
  check.innerHTML = ep.watched ? '&#10003;' : '';
}

function updateCardProgressUI(item) {
  const progress = getEpisodeProgress(item);
  const countEl = document.getElementById('progress-count-' + item.id);
  const percentEl = document.getElementById('progress-percent-' + item.id);
  const fillEl = document.getElementById('progress-fill-' + item.id);
  if (countEl) countEl.textContent = `${progress.watched}/${progress.total} episodes`;
  if (percentEl) percentEl.textContent = `${progress.percent}%`;
  if (fillEl) fillEl.style.width = `${progress.percent}%`;
}

function updateSeasonProgressUI(item, seasonNum) {
  if (!seasonNum) return;
  const seasonEpisodes = (item.episodes || []).filter(e => String(e.seasonNum || '') === String(seasonNum || ''));
  const seasonProgressEl = document.getElementById(`season-progress-${item.id}-${seasonNum}`);
  if (!seasonProgressEl) return;
  const watched = seasonEpisodes.filter(e => e.watched).length;
  const total = getSeasonInfoForEpisodes(item, seasonNum, seasonEpisodes).totalEpisodes || seasonEpisodes.length;
  seasonProgressEl.textContent = `${watched}/${total}`;
}

function updateStatusPillsUI(item) {
  const statusPills = document.querySelectorAll(`#status-pills-${item.id} .status-pill`);
  statusPills.forEach(btn => {
    const isActive = btn.dataset.status === item.status;
    ['live-active', 'watching-active', 'planned-active', 'watched-active', 'paused-active', 'dropped-active']
      .forEach(cls => btn.classList.remove(cls));
    if (isActive) btn.classList.add(`${item.status}-active`);
  });
}

function updateSeasonActionLabelUI(item, seasonNum) {
  if (!seasonNum) return;
  const seasonEpisodes = (item.episodes || []).filter(e => String(e.seasonNum || '') === String(seasonNum || ''));
  const seasonWrap = document.getElementById(`s-eps-${item.id}-${seasonNum}`)?.closest('.season-block');
  const actionBtn = seasonWrap ? seasonWrap.querySelector('.edit-ep-link') : null;
  if (!actionBtn) return;
  const watched = seasonEpisodes.filter(e => e.watched).length;
  actionBtn.textContent = watched < seasonEpisodes.length ? 'Mark all' : 'Clear all';
}

function spawnEpisodeBurst(row) {
  const check = row.querySelector('.ep-check');
  if (!check) return;
  const burst = document.createElement('div');
  burst.className = 'episode-burst';
  const rowRect = row.getBoundingClientRect();
  const checkRect = check.getBoundingClientRect();
  burst.style.left = `${checkRect.left - rowRect.left + checkRect.width / 2}px`;
  burst.style.top = `${checkRect.top - rowRect.top + checkRect.height / 2}px`;
  row.appendChild(burst);
  burst.animate([
    { opacity: 0, transform: 'scale(0.35)' },
    { opacity: 1, transform: 'scale(1.12)', offset: 0.22 },
    { opacity: 0, transform: 'scale(1.9)' }
  ], {
    duration: 620,
    easing: 'cubic-bezier(0.16, 1, 0.3, 1)'
  }).onfinish = () => burst.remove();
}

function animateEpisodeWatchSweep(epId) {
  requestAnimationFrame(() => {
    const row = document.getElementById('ep-row-' + epId);
    if (!row) return;
    row.classList.remove('episode-watch-enter');
    row.classList.remove('episode-watch-sweep');
    row.classList.remove('episode-watch-impact');
    row.classList.remove('episode-watch-glow');
    void row.offsetWidth;
    row.classList.add('episode-watch-enter');
    row.classList.add('episode-watch-sweep');
    row.classList.add('episode-watch-impact');
    row.classList.add('episode-watch-glow');

    row.querySelectorAll('.episode-fill-layer').forEach(layer => layer.remove());
    const fillLayer = document.createElement('div');
    fillLayer.className = 'episode-fill-layer';
    row.appendChild(fillLayer);

    spawnEpisodeBurst(row);

    const fillAnim = fillLayer.animate([
      { clipPath: 'inset(0 99% 0 0 round 4px)' },
      { clipPath: 'inset(0 84% 0 0 round 4px)', offset: 0.16 },
      { clipPath: 'inset(0 66% 0 0 round 4px)', offset: 0.32 },
      { clipPath: 'inset(0 48% 0 0 round 4px)', offset: 0.48 },
      { clipPath: 'inset(0 29% 0 0 round 4px)', offset: 0.64 },
      { clipPath: 'inset(0 12% 0 0 round 4px)', offset: 0.8 },
      { clipPath: 'inset(0 3% 0 0 round 4px)', offset: 0.92 },
      { clipPath: 'inset(0 0 0 0 round 4px)' }
    ], {
      duration: 1120,
      easing: 'linear',
      fill: 'forwards'
    });

    fillAnim.onfinish = () => {
      fillLayer.remove();
      row.classList.remove('episode-watch-sweep');
      row.classList.remove('episode-watch-enter');
      row.classList.remove('episode-watch-impact');
      row.classList.remove('episode-watch-glow');
    };
  });
}

function toggleEp(itemId, epId) {
  const item = data[activeSection].find(i => i.id === itemId);
  if (!item) return;
  const ep = item.episodes.find(e => e.id === epId);
  if (!ep) return;
  let becameWatched = false;
  let shouldRerender = false;
  preserveEpisodeScroll(itemId, () => {
    ep.watched = !ep.watched;
    becameWatched = ep.watched;
    const allWatched = item.episodes.every(e => e.watched);
    const anyWatched = item.episodes.some(e => e.watched);
    if (allWatched) item.status = "watched";
    else if (anyWatched) item.status = "watching";
    else item.status = "planned";
    touchItem(item);
    save();
    shouldRerender = !itemMatchesCurrentView(item);
    if (shouldRerender) {
      render();
      return;
    }
    updateEpisodeRowState(ep);
    updateCardProgressUI(item);
    updateSeasonProgressUI(item, ep.seasonNum);
    updateStatusPillsUI(item);
  });
  if (becameWatched) animateEpisodeWatchSweep(epId);
}

function markAllEps(id, val) {
  const item = data[activeSection].find(i => i.id === id);
  if (!item) return;
  preserveViewport(() => {
    preserveEpisodeScroll(id, () => {
      item.episodes.forEach(e => e.watched = val);
      item.status = val ? "watched" : "planned";
      touchItem(item);
      save();
      if (!itemMatchesCurrentView(item)) {
        render();
        return;
      }
      item.episodes.forEach(updateEpisodeRowState);
      updateCardProgressUI(item);
      new Set(item.episodes.map(ep => ep.seasonNum).filter(Boolean)).forEach(seasonNum => {
        updateSeasonProgressUI(item, seasonNum);
        updateSeasonActionLabelUI(item, seasonNum);
      });
      updateStatusPillsUI(item);
    });
  });
}

function showEditEp(id) {
  const item = data[activeSection].find(i => i.id === id);
  if (!item) return;
  const el = document.getElementById('edit-ep-' + id);
  el.innerHTML = `
    <input type="number" min="1" value="${item.episodes.length}" style="width:60px;padding:4px 8px;font-size:12px;background:#0c0a1d;border:1px solid #2a2248;border-radius:4px;color:#e8e3f3;outline:none;" id="ep-count-inp-${id}">
    <button class="btn-primary btn-sm" onclick="saveEpCount('${id}')">Save</button>
    <button class="btn-secondary btn-sm" onclick="render()">Cancel</button>
  `;
}

function saveEpCount(id) {
  const item = data[activeSection].find(i => i.id === id);
  if (!item) return;
  const count = Math.max(1, parseInt(document.getElementById('ep-count-inp-' + id).value) || 1);
  const curr = item.episodes;
  preserveEpisodeScroll(id, () => {
    if (count > curr.length) {
      for (let i = curr.length; i < count; i++) {
        curr.push({ id: id + '-ep-' + (i+1), number: i+1, title: '', watched: false, rating: 0 });
      }
    } else {
      item.episodes = curr.slice(0, count);
    }
    item.totalEpisodes = count;
    save(); render();
  });
}

// TMDB Cover Search
const TMDB_PROXY_BASE = "/api/tmdb";
const RAWG_PROXY_BASE = "/api/rawg";
const SCREENLIST_AI_PROXY_BASE = "/api/ai";
const DEEPSEEK_PROXY_BASE = "/api/deepseek"; // legacy fallback only
let selectedTmdb = null; // holds the selected item data

function buildProxyUrl(base, path, params = {}) {
  const cleanPath = String(path || '').replace(/^\/+/, '');
  const search = new URLSearchParams();
  Object.entries(params || {}).forEach(([key, value]) => {
    if (value === undefined || value === null || value === '') return;
    search.set(key, String(value));
  });
  const query = search.toString();
  return `${base}/${cleanPath}${query ? `?${query}` : ''}`;
}

function fetchTmdbProxy(path, params = {}) {
  return fetch(buildProxyUrl(TMDB_PROXY_BASE, path, params));
}

function fetchRawgProxy(path, params = {}) {
  return fetch(buildProxyUrl(RAWG_PROXY_BASE, path, params));
}

const JIKAN_API_BASE = "https://api.jikan.moe/v4";
const animeTitleVariantCache = new Map();
const animeTitleHydrationInFlight = new Set();

async function fetchAnimeTitleVariantsFromJikan(query = '') {
  const cleanQuery = String(query || '').trim();
  if (!cleanQuery) return null;
  const cacheKey = cleanQuery.toLowerCase();
  if (animeTitleVariantCache.has(cacheKey)) return animeTitleVariantCache.get(cacheKey);
  try {
    const url = `${JIKAN_API_BASE}/anime?q=${encodeURIComponent(cleanQuery)}&limit=1`;
    const res = await fetch(url, { cache: 'force-cache' });
    if (!res.ok) return null;
    const json = await res.json();
    const hit = Array.isArray(json?.data) ? json.data[0] : null;
    if (!hit) return null;
    const titleRows = Array.isArray(hit.titles) ? hit.titles : [];
    const titleByType = type => titleRows.find(row => String(row?.type || '').toLowerCase() === type)?.title || '';
    const variants = normalizeAnimeTitleVariants({
      english: hit.title_english || titleByType('english') || cleanQuery,
      romaji: hit.title || titleByType('default') || titleByType('romaji') || cleanQuery,
      japanese: hit.title_japanese || titleByType('japanese') || ''
    }, cleanQuery);
    animeTitleVariantCache.set(cacheKey, variants);
    return variants;
  } catch (e) {
    console.warn('Anime title variant lookup failed:', e);
    return null;
  }
}

async function hydrateAnimeTitleVariants(target = {}) {
  if (!target || typeof target !== 'object') return target;
  const fallbackTitle = target.title || target.name || '';
  const fallbackVariants = normalizeAnimeTitleVariants({
    english: fallbackTitle,
    romaji: target.romajiTitle || fallbackTitle,
    japanese: target.japaneseTitle || (detectJapaneseScript(target.originalTitle || target.original_name || target.original_title) ? (target.originalTitle || target.original_name || target.original_title) : '')
  }, fallbackTitle);
  const query = fallbackTitle || target.originalTitle || target.original_name || target.original_title || '';
  const jikanVariants = await fetchAnimeTitleVariantsFromJikan(query);
  const variants = normalizeAnimeTitleVariants({
    english: jikanVariants?.english || fallbackVariants.english,
    romaji: jikanVariants?.romaji || fallbackVariants.romaji,
    japanese: jikanVariants?.japanese || fallbackVariants.japanese
  }, fallbackTitle);
  target.titleVariants = variants;
  target.englishTitle = variants.english;
  target.romajiTitle = variants.romaji;
  target.japaneseTitle = variants.japanese;
  return target;
}

function queueAnimeTitleVariantHydration(item, section = 'anime') {
  if (!item || section !== 'anime' || isViewingOtherProfile?.()) return;
  const mode = getAnimeTitleDisplayMode();
  if (mode === 'english' && item.titleVariants?.english) return;
  if (item.titleVariants?.romaji && item.titleVariants?.japanese) return;
  const key = `${section}:${item.id || item.title || ''}`;
  if (animeTitleHydrationInFlight.has(key)) return;
  animeTitleHydrationInFlight.add(key);
  hydrateAnimeTitleVariants(item).then(() => {
    animeTitleHydrationInFlight.delete(key);
    if (!viewingUser && activeSection === section) {
      save();
      render();
    }
  }).catch(() => animeTitleHydrationInFlight.delete(key));
}

function formatAnimeSeasonTitle(baseTitle = '', season = {}) {
  const n = Number(season.season_number || season.seasonNum || season.number || 0);
  const rawName = String(season.name || '').trim();
  const genericName = !rawName || /^season\s*\d+$/i.test(rawName) || rawName === String(n);
  const suffix = genericName ? `Season ${n || ''}`.trim() : rawName;
  return suffix ? `${baseTitle} — ${suffix}` : baseTitle;
}

function buildAnimeSeasonLibraryItem(base = {}, season = {}, status = 'watching', rating = 0, index = 0) {
  const baseId = String(base.tmdbId || base.id || Date.now());
  const seasonNum = Number(season.seasonNum || season.season_number || season.number || index + 1);
  const episodes = Array.isArray(season.episodes) ? season.episodes : [];
  const id = `${Date.now()}-${baseId}-s${seasonNum}-${index}`;
  const title = formatAnimeSeasonTitle(base.title || base.name || '', season);
  return {
    id,
    title,
    parentTitle: base.title || base.name || '',
    cover: season.cover || base.cover || '',
    genre: base.genre || '',
    year: String(season.airDate || season.air_date || base.year || '').slice(0, 4),
    status,
    rating,
    dateAdded: new Date().toISOString(),
    imdbId: base.imdbId || '',
    tmdbId: base.tmdbId || '',
    tmdbSeasonNumber: seasonNum,
    mediaCategory: 'anime',
    librarySection: 'anime',
    originalTitle: base.originalTitle || '',
    originalLanguage: base.originalLanguage || '',
    originCountries: Array.isArray(base.originCountries) ? base.originCountries : [],
    genreNames: Array.isArray(base.genreNames) ? base.genreNames : [],
    isAnime: true,
    titleVariants: normalizeAnimeTitleVariants({
      english: formatAnimeSeasonTitle(base.titleVariants?.english || base.englishTitle || base.title || '', season),
      romaji: formatAnimeSeasonTitle(base.titleVariants?.romaji || base.romajiTitle || base.title || '', season),
      japanese: base.titleVariants?.japanese || base.japaneseTitle
        ? formatAnimeSeasonTitle(base.titleVariants?.japanese || base.japaneseTitle, season)
        : ''
    }, title),
    totalEpisodes: episodes.length,
    totalEps: episodes.length,
    currentEp: status === 'watched' ? episodes.length : 0,
    episodes: episodes.map((ep, i) => ({
      id: `${id}-ep-${i + 1}`,
      number: i + 1,
      seasonNum,
      seasonName: season.name || season.seasonName || '',
      epNum: ep.epNum || ep.episode_number || i + 1,
      title: ep.title || ep.name || '',
      watched: status === 'watched',
      rating: 0
    }))
  };
}

function shouldSplitAnimeSeasons(source = {}) {
  // Anime TV titles should stay as one library card.
  // Keep season metadata attached for nested season/episode rendering,
  // but do not split seasons into separate library entries.
  return false;
}

function buildAnimeSeasonItemsForLibrary(source = {}, status = 'watching', rating = 0) {
  return [coerceAnimeSeriesLibraryItem(source, status, rating)];
}

function getAnimeSeriesMatchKey(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/\s+[—–-]\s+(the\s+)?final\s+season.*$/i, '')
    .replace(/\s+[—–-]\s+(season|part)\s*\d+.*$/i, '')
    .replace(/\s*[:|]\s*(the\s+)?final\s+season.*$/i, '')
    .replace(/\s*[:|]\s*(season|part)\s*\d+.*$/i, '')
    .replace(/\s+(the\s+)?final\s+season.*$/i, '')
    .replace(/\s+season\s*\d+.*$/i, '')
    .replace(/\s+part\s*\d+.*$/i, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getAnimeSeriesMatchKeys(source = {}) {
  return new Set([
    source.title,
    source.parentTitle,
    source.englishTitle,
    source.romajiTitle,
    source.originalTitle,
    source.titleVariants?.english,
    source.titleVariants?.romaji
  ].map(getAnimeSeriesMatchKey).filter(Boolean));
}

function isAnimeSeasonSplitEntry(entry = {}, source = {}) {
  if (!entry || typeof entry !== 'object') return false;
  const isAnimeEntry = entry.isAnime === true || entry.mediaCategory === 'anime' || entry.librarySection === 'anime';
  if (!isAnimeEntry) return false;
  const hasSeasonSplitMarker = !!(
    entry.tmdbSeasonNumber ||
    entry.parentTitle ||
    /(?:^|\s+[—–-]\s+|\s*:\s*|\s+)(the\s+)?final\s+season/i.test(entry.title || '') ||
    /(?:^|\s+[—–-]\s+|\s*:\s*|\s+)season\s*\d+/i.test(entry.title || '') ||
    /(?:^|\s+[—–-]\s+|\s*:\s*|\s+)part\s*\d+/i.test(entry.title || '')
  );
  if (!hasSeasonSplitMarker) return false;
  const sourceTmdbId = String(source.tmdbId || '').trim();
  const entryTmdbId = String(entry.tmdbId || '').trim();
  if (sourceTmdbId && entryTmdbId && sourceTmdbId === entryTmdbId) return true;
  const sourceKeys = getAnimeSeriesMatchKeys(source);
  if (!sourceKeys.size) return false;
  return [entry.parentTitle, entry.title, entry.englishTitle, entry.romajiTitle, entry.originalTitle]
    .map(getAnimeSeriesMatchKey)
    .some(key => key && sourceKeys.has(key));
}

function removeAnimeSeasonSplitEntries(list = [], source = {}) {
  const items = Array.isArray(list) ? list : [];
  return items.filter(entry => !isAnimeSeasonSplitEntry(entry, source));
}

function coerceAnimeSeriesLibraryItem(item = {}, status = item?.status || 'watching', rating = item?.rating || 0) {
  const next = { ...item };
  const title = next.parentTitle || next.title || next.name || '';
  next.title = title;
  next.status = status || next.status || 'watching';
  next.rating = Number(rating || next.rating || 0);
  next.mediaCategory = 'anime';
  next.librarySection = 'anime';
  next.isAnime = true;
  delete next.parentTitle;
  delete next.tmdbSeasonNumber;
  if (Array.isArray(next.animeSeasonItems) && !Array.isArray(next.seasonsInfo)) {
    next.seasonsInfo = next.animeSeasonItems.map(season => ({
      seasonNum: season.seasonNum || season.season_number || 0,
      season_number: season.season_number || season.seasonNum || 0,
      name: season.name || '',
      title: season.name || '',
      cover: season.cover || '',
      airDate: season.airDate || '',
      episodeCount: Array.isArray(season.episodes) ? season.episodes.length : Number(season.episode_count || 0)
    }));
  }
  return next;
}

function cleanAnimeSeriesListForSingleAdd(list = [], source = {}) {
  const items = Array.isArray(list) ? list : [];
  const sourceKeys = getAnimeSeriesMatchKeys(source);
  if (!sourceKeys.size) return removeAnimeSeasonSplitEntries(items, source);
  const matchedSeriesEntries = items.filter(entry => {
    if (!entry || typeof entry !== 'object') return false;
    const isAnimeEntry = entry.isAnime === true || entry.mediaCategory === 'anime' || entry.librarySection === 'anime';
    if (!isAnimeEntry) return false;
    const entryKeys = getAnimeSeriesMatchKeys(entry);
    for (const key of entryKeys) {
      if (sourceKeys.has(key)) return true;
    }
    return false;
  });
  const hasMatchedSplit = matchedSeriesEntries.length > 1 || items.some(entry => isAnimeSeasonSplitEntry(entry, source));
  return items.filter(entry => {
    if (isAnimeSeasonSplitEntry(entry, source)) return false;
    if (!hasMatchedSplit) return true;
    const entryKeys = getAnimeSeriesMatchKeys(entry);
    for (const key of entryKeys) {
      if (sourceKeys.has(key)) return false;
    }
    return true;
  });
}

async function postAiImportMatch(endpoint, payload) {
  return fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
}

async function fetchDeepSeekImportMatch(payload) {
  const primaryEndpoint = `${SCREENLIST_AI_PROXY_BASE}/import-match`;
  const res = await postAiImportMatch(primaryEndpoint, payload);
  if (res.status !== 404) return res;

  // Legacy fallback so older Worker deploys do not instantly break while the
  // new Workers AI route is being deployed. Remove after /api/ai is live.
  return postAiImportMatch(`${DEEPSEEK_PROXY_BASE}/import-match`, payload);
}

async function checkScreenListAI() {
  const endpoint = `${SCREENLIST_AI_PROXY_BASE}/import-match`;
  const startedAt = performance.now();
  try {
    const res = await postAiImportMatch(endpoint, {
      systemPrompt: 'Return valid JSON only. No markdown.',
      userPrompt: 'Return exactly {"ok":true,"service":"workers-ai"}.',
      temperature: 0
    });
    const elapsedMs = Math.round(performance.now() - startedAt);
    const raw = await res.text();
    let body = raw;
    try { body = JSON.parse(raw); } catch (e) {}
    const result = { ok: res.ok, status: res.status, elapsedMs, endpoint, body };
    console.log('ScreenList Workers AI check:', result);
    if (!res.ok) {
      console.warn('ScreenList Workers AI check failed. 404 = Worker route missing, 401/403 = auth/binding issue, 500 = Worker/AI error.');
    }
    return result;
  } catch (error) {
    const result = { ok: false, status: 0, endpoint, error: error?.message || String(error) };
    console.error('ScreenList Workers AI check failed:', result);
    return result;
  }
}

async function checkDeepSeekAPI() {
  return checkScreenListAI();
}

window.checkScreenListAI = checkScreenListAI;
window.screenListAiCheck = checkScreenListAI;
window.checkDeepSeekAPI = checkScreenListAI; // legacy console alias
window.deepSeekCheck = checkScreenListAI;

function saveTmdbKey() {
  localStorage.removeItem("tmdb-api-key");
  renderApiKeySection();
}

function clearTmdbKey() {
  localStorage.removeItem("tmdb-api-key");
  renderApiKeySection();
}

function renderApiKeySection() {
  document.getElementById("api-key-section").innerHTML = '';
}

let addTitleLiveSearchTimer = null;
let addTitleSearchRequestToken = 0;
let addShelfSearchFilter = 'all';
let pendingModalStatusSelection = '';
let modalAddSubmitting = false;
let addShelfModalBackHandler = null;

function resetAddTitleSelection() {
  const selectedArea = document.getElementById("tmdb-selected-area");
  selectedTmdb = null;
  pendingModalStatusSelection = '';
  modalAddSubmitting = false;
  if (selectedArea) {
    selectedArea.style.display = "none";
    selectedArea.innerHTML = "";
  }
  hideModalStatusPicker();
}

function getAddShelfDefaultFilter(section = activeSection) {
  if (section === 'movies') return 'movies';
  if (section === 'shows') return 'tv';
  if (section === 'anime') return 'anime';
  if (section === 'games') return 'games';
  if (section === 'manga') return 'manga';
  if (section === 'books') return 'books';
  return 'all';
}

function getAddShelfSearchPlaceholder(filter = addShelfSearchFilter) {
  if (filter === 'games') return 'Search games...';
  if (filter === 'anime') return 'Search anime...';
  if (filter === 'movies') return 'Search movies...';
  if (filter === 'tv') return 'Search TV shows...';
  if (filter === 'manga') return 'Search manga...';
  if (filter === 'books') return 'Search books...';
  return 'Search movies, shows, anime, games...';
}

function setAddShelfSearchPlaceholder(filter = addShelfSearchFilter) {
  const input = document.getElementById('inp-tmdb-search');
  if (input) input.placeholder = getAddShelfSearchPlaceholder(filter);
}

function setModalBackBtn(visible, handler = null) {
  const btn = document.getElementById('modal-back-btn');
  if (!btn) return;
  addShelfModalBackHandler = visible ? (handler || clearSelection) : null;
  btn.style.display = visible ? '' : 'none';
}

function handleModalBackButton() {
  if (typeof addShelfModalBackHandler === 'function') addShelfModalBackHandler();
}

function resetAddShelfModalHome() {
  resetAddTitleSelection();
  const searchArea = document.getElementById('tmdb-search-area');
  const results = document.getElementById('tmdb-results');
  const input = document.getElementById('inp-tmdb-search');
  if (searchArea) searchArea.style.display = 'block';
  if (results) results.innerHTML = '';
  if (input) input.value = '';
  setAddShelfFilter(getAddShelfDefaultFilter(activeSection));
  setModalBackBtn(false);
  if (input) setTimeout(() => input.focus(), 40);
}

function getAddShelfStatusLabel(status = '', section = activeSection) {
  const option = (MODAL_STATUS_OPTIONS[section] || []).find(entry => entry.status === status);
  return option?.label || getMyListStatusLabel(status, section) || 'Library';
}

function handleAddTitleLiveSearchInput() {
  const input = document.getElementById("inp-tmdb-search");
  const resultsDiv = document.getElementById("tmdb-results");
  const query = (input?.value || '').trim();
  clearTimeout(addTitleLiveSearchTimer);
  resetAddTitleSelection();
  if (!query) {
    addTitleSearchRequestToken++;
    if (resultsDiv) resultsDiv.innerHTML = "";
    return;
  }
  if (query.length < 2) {
    addTitleSearchRequestToken++;
    if (resultsDiv) resultsDiv.innerHTML = '<div class="cover-search-msg">Keep typing...</div>';
    return;
  }
  if (addShelfSearchFilter === 'books' || addShelfSearchFilter === 'manga') {
    selectManualReadingTitle();
    return;
  }
  addTitleLiveSearchTimer = setTimeout(() => doSearch(), 260);
}

function doSearch() {
  clearTimeout(addTitleLiveSearchTimer);
  const query = (document.getElementById("inp-tmdb-search")?.value || '').trim();
  if (!query) return;
  const token = ++addTitleSearchRequestToken;
  if (addShelfSearchFilter === 'games') searchRAWG(token);
  else if (addShelfSearchFilter === 'books' || addShelfSearchFilter === 'manga') selectManualReadingTitle();
  else searchUniversalShelf(token);
}

function setAddShelfFilter(filter) {
  addShelfSearchFilter = filter;
  document.querySelectorAll('.shelf-filter-pill').forEach(p => {
    p.classList.toggle('active', p.dataset.filter === filter);
  });
  setAddShelfSearchPlaceholder(filter);
  const query = (document.getElementById('inp-tmdb-search')?.value || '').trim();
  if (query.length >= 2) doSearch();
  else if (document.getElementById('tmdb-results')) document.getElementById('tmdb-results').innerHTML = '';
}

function getAddShelfResultKind(item = {}, fallbackFilter = addShelfSearchFilter) {
  const mediaType = String(item?.media_type || item?.mediaType || '').trim().toLowerCase();
  const mediaCategory = String(item?.mediaCategory || item?.librarySection || '').trim().toLowerCase();
  const normalizedForAnimeCheck = {
    title: item?.title || item?.name || '',
    originalTitle: item?.original_title || item?.original_name || item?.originalTitle || '',
    originalLanguage: item?.original_language || item?.originalLanguage || '',
    originCountries: Array.isArray(item?.origin_country) ? item.origin_country : (item?.originCountries || []),
    genreNames: Array.isArray(item?.genres) ? item.genres.map(g => g?.name).filter(Boolean) : (Array.isArray(item?.genreNames) ? item.genreNames : []),
    genre: item?.genre || ''
  };
  const isAnimeTitle = mediaCategory === 'anime' || isAnimeDiscoverCandidate(item) || detectAnimeFromMetadata(normalizedForAnimeCheck);

  if (item?.rawgId || String(item?.source || '').trim().toLowerCase() === 'rawg' || fallbackFilter === 'games') return 'game';
  if (mediaCategory === 'manga' || fallbackFilter === 'manga') return 'manga';
  if (mediaCategory === 'books' || fallbackFilter === 'books') return 'book';
  if (mediaType === 'movie' || mediaCategory === 'movies' || fallbackFilter === 'movies') return isAnimeTitle ? 'anime-movie' : 'movie';
  if (mediaType === 'tv' || mediaCategory === 'shows' || mediaCategory === 'anime' || fallbackFilter === 'tv' || fallbackFilter === 'anime') {
    return isAnimeTitle ? 'anime-tv' : 'tv-show';
  }
  return 'title';
}

function getAddShelfResultTypeConfig(item = {}, fallbackFilter = addShelfSearchFilter) {
  const kind = getAddShelfResultKind(item, fallbackFilter);
  const configMap = {
    'movie': { label: 'Movie', badgeClass: 'badge-movie' },
    'tv-show': { label: 'TV Show', badgeClass: 'badge-tv' },
    'anime-tv': { label: 'Anime TV Show', badgeClass: 'badge-anime-tv' },
    'anime-movie': { label: 'Anime Movie', badgeClass: 'badge-anime-movie' },
    'game': { label: 'Game', badgeClass: 'badge-game' },
    'manga': { label: 'Manga', badgeClass: 'badge-manga' },
    'book': { label: 'Book', badgeClass: 'badge-book' },
    'title': { label: 'Title', badgeClass: 'badge-generic' }
  };
  return configMap[kind] || configMap.title;
}

function buildAddShelfResultMeta(item = {}, detail = '', fallbackFilter = addShelfSearchFilter) {
  const typeConfig = getAddShelfResultTypeConfig(item, fallbackFilter);
  const cleanDetail = String(detail || '').trim();
  return cleanDetail ? `${typeConfig.label} · ${cleanDetail}` : typeConfig.label;
}

async function searchUniversalShelf(searchToken = 0) {
  const query = (document.getElementById("inp-tmdb-search")?.value || '').trim();
  if (!query) return;
  const resultsDiv = document.getElementById("tmdb-results");
  if (!resultsDiv) return;
  resultsDiv.innerHTML = '<div class="cover-search-msg">Searching...</div>';
  const filter = addShelfSearchFilter;
  try {
    let hits = [];
    if (filter === 'all') {
      const res = await fetchTmdbProxy('search/multi', { query, include_adult: false });
      const json = await res.json();
      if (searchToken && searchToken !== addTitleSearchRequestToken) return;
      hits = (json.results || [])
        .filter(r => (r.media_type === 'movie' || r.media_type === 'tv') && r.poster_path)
        .sort((a, b) => (b.popularity || 0) - (a.popularity || 0))
        .slice(0, 8);
    } else if (filter === 'movies') {
      const res = await fetchTmdbProxy('search/movie', { query });
      const json = await res.json();
      if (searchToken && searchToken !== addTitleSearchRequestToken) return;
      hits = (json.results || [])
        .filter(r => r.poster_path)
        .sort((a, b) => (b.popularity || 0) - (a.popularity || 0))
        .slice(0, 8)
        .map(r => ({ ...r, media_type: 'movie' }));
    } else if (filter === 'tv' || filter === 'anime') {
      const res = await fetchTmdbProxy('search/tv', { query });
      const json = await res.json();
      if (searchToken && searchToken !== addTitleSearchRequestToken) return;
      let tvHits = (json.results || [])
        .filter(r => r.poster_path)
        .sort((a, b) => (b.popularity || 0) - (a.popularity || 0));
      if (filter === 'anime') tvHits = tvHits.filter(r => isAnimeDiscoverCandidate(r));
      hits = tvHits.slice(0, 8).map(r => ({ ...r, media_type: 'tv' }));
    }
    if (hits.length === 0) {
      resultsDiv.innerHTML = '<div class="cover-search-msg">No results found. Try a different search.</div>';
      return;
    }
    resultsDiv.innerHTML = '<div class="tmdb-results">' + hits.map(r => {
      const title = escHtml(r.title || r.name || '');
      const year = (r.release_date || r.first_air_date || '').slice(0, 4);
      const overviewText = String(r.overview || '').trim();
      const overviewSnippet = overviewText ? `${overviewText.slice(0, 80)}${overviewText.length > 80 ? '...' : ''}` : '';
      const poster = `https://image.tmdb.org/t/p/w92${r.poster_path}`;
      const mType = r.media_type || 'tv';
      const typeConfig = getAddShelfResultTypeConfig(r, filter);
      const badge = `<span class="shelf-result-badge ${typeConfig.badgeClass}">${typeConfig.label}</span>`;
      const meta = escHtml(buildAddShelfResultMeta(r, overviewSnippet, filter));
      return `<div class="tmdb-result" onclick="selectTMDB(${r.id}, '${mType}')">
        <img src="${escAttr(poster)}">
        <div class="tmdb-result-info">
          <div class="tmdb-result-title">${title} ${year ? '(' + year + ')' : ''} ${badge}</div>
          <div class="tmdb-result-meta">${meta}</div>
        </div>
      </div>`;
    }).join('') + '</div>';
  } catch(e) {
    if (resultsDiv) resultsDiv.innerHTML = '<div class="cover-search-msg">Search failed. Try again.</div>';
  }
}

function selectManualReadingTitle() {
  const input = document.getElementById("inp-tmdb-search");
  const title = (input?.value || '').trim();
  const resultsDiv = document.getElementById("tmdb-results");
  if (!title) {
    if (resultsDiv) resultsDiv.innerHTML = `<div class="cover-search-msg">Enter a ${getSectionLabel(activeSection, true)} title first.</div>`;
    return;
  }
  selectedTmdb = {
    title,
    cover: '',
    genre: activeSection === 'manga' ? 'Manga' : 'Book',
    year: '',
    source: 'manual',
    mediaCategory: activeSection,
    librarySection: activeSection,
    episodes: []
  };
  if (resultsDiv) resultsDiv.innerHTML = '';
  const selectedArea = document.getElementById("tmdb-selected-area");
  selectedArea.style.display = "block";
  selectedArea.innerHTML = `<div class="tmdb-selected">
    <div class="tmdb-selected-info">
      <div class="tmdb-selected-title">${escHtml(title)}</div>
      <div class="tmdb-selected-detail">Manual ${escHtml(getAddButtonSectionLabel(activeSection))} entry</div>
      <button class="tmdb-clear" onclick="clearSelection()">Clear selection</button>
    </div>
  </div>`;
  showModalStatusPicker();
  document.getElementById("tmdb-search-area").style.display = "none";
  setModalBackBtn(true);
}

async function searchRAWG(searchToken = 0) {
  const query = document.getElementById("inp-tmdb-search").value.trim();
  if (!query) return;
  const resultsDiv = document.getElementById("tmdb-results");
  resultsDiv.innerHTML = '<div class="cover-search-msg">Searching...</div>';
  try {
    const res = await fetchRawgProxy('games', { search: query, page_size: 6 });
    const json = await res.json();
    if (searchToken && searchToken !== addTitleSearchRequestToken) return;
    const hits = (json.results || []).slice(0, 6);
    if (hits.length === 0) {
      resultsDiv.innerHTML = '<div class="cover-search-msg">No results found. Try a different search.</div>';
      return;
    }
    resultsDiv.innerHTML = '<div class="tmdb-results">' + hits.map(r => {
      const title = escHtml(r.name || '');
      const year = (r.released || '').slice(0, 4);
      const platforms = (r.platforms || []).map(p => p.platform.name).slice(0, 3).join(', ');
      const poster = r.background_image ? r.background_image : '';
      const posterThumb = poster ? `<img src="${poster}" style="width:66px;height:44px;border-radius:4px;object-fit:cover;flex-shrink:0;">` : '';
      const typeConfig = getAddShelfResultTypeConfig({ ...r, source: 'rawg', rawgId: r.id }, 'games');
      const badge = `<span class="shelf-result-badge ${typeConfig.badgeClass}">${typeConfig.label}</span>`;
      const meta = escHtml(buildAddShelfResultMeta({ ...r, source: 'rawg', rawgId: r.id }, platforms, 'games'));
      return `<div class="tmdb-result" onclick="selectRAWG(${r.id})">
        ${posterThumb}
        <div class="tmdb-result-info">
          <div class="tmdb-result-title">${title} ${year ? '(' + year + ')' : ''} ${badge}</div>
          <div class="tmdb-result-meta">${meta}</div>
        </div>
      </div>`;
    }).join("") + '</div>';
  } catch(e) {
    resultsDiv.innerHTML = '<div class="cover-search-msg">Search failed.</div>';
  }
}

async function selectRAWG(id) {
  const resultsDiv = document.getElementById("tmdb-results");
  resultsDiv.innerHTML = '<div class="cover-search-msg">Loading details...</div>';
  try {
    const res = await fetchRawgProxy(`games/${id}`);
    const d = await res.json();
    const title = d.name || '';
    const cover = d.background_image || '';
    const genres = (d.genres || []).map(g => g.name).join(', ');
    const year = (d.released || '').slice(0, 4);
    const platforms = (d.platforms || []).map(p => p.platform.name).join(', ');

    selectedTmdb = {
      title,
      cover,
      genre: genres,
      year,
      platforms,
      metacritic: d.metacritic || '',
      metacriticSlug: d.slug || '',
      rawgId: String(id),
      rawgSlug: d.slug || '',
      backloggdSlug: d.slug || '',
      source: 'rawg',
      stores: Array.isArray(d.stores) ? d.stores : [],
      mediaCategory: 'games',
      librarySection: 'games'
    };

    resultsDiv.innerHTML = '';
    const selectedArea = document.getElementById("tmdb-selected-area");
    selectedArea.style.display = "block";
    selectedArea.innerHTML = `<div class="tmdb-selected">
      ${cover ? `<img src="${cover}" style="width:90px;height:60px;border-radius:4px;object-fit:cover;">` : ''}
      <div class="tmdb-selected-info">
        <div class="tmdb-selected-title">${escHtml(title)} ${year ? '(' + year + ')' : ''}</div>
        <div class="tmdb-selected-detail">${escHtml(genres)}</div>
        <div class="tmdb-selected-detail">${escHtml(platforms)}</div>
        <button class="tmdb-clear" onclick="clearSelection()">Clear selection</button>
      </div>
    </div>`;
    showModalStatusPicker();
    document.getElementById("tmdb-search-area").style.display = "none";
    setModalBackBtn(true);
  } catch(e) {
    resultsDiv.innerHTML = '<div class="cover-search-msg">Failed to load details. Try again.</div>';
  }
}

async function searchTMDB(searchToken = 0) {
  const query = document.getElementById("inp-tmdb-search").value.trim();
  if (!query) return;
  const resultsDiv = document.getElementById("tmdb-results");
  resultsDiv.innerHTML = '<div class="cover-search-msg">Searching...</div>';
  try {
    const type = isShowSection(activeSection) ? "tv" : "movie";
    const res = await fetchTmdbProxy(`search/${type}`, { query });
    const json = await res.json();
    if (searchToken && searchToken !== addTitleSearchRequestToken) return;
    const hits = (json.results || []).filter(r => r.poster_path).slice(0, 6);
    if (hits.length === 0) {
      resultsDiv.innerHTML = '<div class="cover-search-msg">No results found. Try a different search.</div>';
      return;
    }
    resultsDiv.innerHTML = '<div class="tmdb-results">' + hits.map(r => {
      const title = escHtml(r.title || r.name || '');
      const year = (r.release_date || r.first_air_date || '').slice(0, 4);
      const overview = escHtml((r.overview || '').slice(0, 80)) + (r.overview && r.overview.length > 80 ? '...' : '');
      const poster = `https://image.tmdb.org/t/p/w92${r.poster_path}`;
      return `<div class="tmdb-result" onclick="selectTMDB(${r.id})">
        <img src="${poster}">
        <div class="tmdb-result-info">
          <div class="tmdb-result-title">${title} ${year ? '(' + year + ')' : ''}</div>
          <div class="tmdb-result-meta">${overview}</div>
        </div>
      </div>`;
    }).join("") + '</div>';
  } catch(e) {
    resultsDiv.innerHTML = '<div class="cover-search-msg">Search failed. Try again.</div>';
  }
}

async function selectTMDB(id, knownType = null) {
  const type = knownType || (isShowSection(activeSection) ? "tv" : "movie");
  const resultsDiv = document.getElementById("tmdb-results");
  resultsDiv.innerHTML = '<div class="cover-search-msg">Loading details...</div>';
  try {
    const res = await fetchTmdbProxy(`${type}/${id}`);
    const d = await res.json();
    const title = d.title || d.name || '';
    const cover = d.poster_path ? `https://image.tmdb.org/t/p/w500${d.poster_path}` : '';
    const genres = (d.genres || []).map(g => g.name).join(', ');
    const year = (d.release_date || d.first_air_date || '').slice(0, 4);

    const genreNames = (d.genres || []).map(g => g.name).filter(Boolean);
    selectedTmdb = {
      title,
      cover,
      genre: genres,
      genreNames,
      year,
      tmdbId: String(id),
      originalTitle: d.original_name || d.original_title || '',
      originalLanguage: d.original_language || '',
      originCountries: Array.isArray(d.origin_country) ? d.origin_country : []
    };
    if (type === "tv") {
      selectedTmdb.mediaCategory = detectAnimeFromMetadata(selectedTmdb) ? 'anime' : 'shows';
      selectedTmdb.librarySection = selectedTmdb.mediaCategory;
      selectedTmdb.isAnime = selectedTmdb.mediaCategory === 'anime';
    } else {
      selectedTmdb.mediaCategory = 'movies';
      selectedTmdb.librarySection = 'movies';
      selectedTmdb.isAnime = false;
    }

    // Get IMDb ID
    if (type === "movie" && d.imdb_id) {
      selectedTmdb.imdbId = d.imdb_id;
    } else if (type === "tv") {
      try {
        const extRes = await fetchTmdbProxy(`tv/${id}/external_ids`);
        const extData = await extRes.json();
        if (extData.imdb_id) selectedTmdb.imdbId = extData.imdb_id;
      } catch(e) {}
    }

    if (type === "tv") {
      if (selectedTmdb.isAnime) await hydrateAnimeTitleVariants(selectedTmdb);
      // Fetch episodes by season. Anime season metadata stays attached to one series card.
      const seasons = (d.seasons || []).filter(s => s.season_number > 0 && Number(s.episode_count || 0) > 0);
      let allEpisodes = [];
      const animeSeasonItems = [];
      for (const season of seasons) {
        try {
          const sRes = await fetchTmdbProxy(`tv/${id}/season/${season.season_number}`);
          const sData = await sRes.json();
          const seasonStartIndex = allEpisodes.length;
          const seasonDisplayName = sData.name || season.name || '';
          const seasonEpisodes = (sData.episodes || []).map((ep, idx) => ({
            number: seasonStartIndex + idx + 1,
            seasonNum: season.season_number,
            seasonName: seasonDisplayName,
            epNum: ep.episode_number,
            title: ep.name || '',
            cover: (sData.poster_path || season.poster_path) ? `https://image.tmdb.org/t/p/w500${sData.poster_path || season.poster_path}` : '',
          }));
          seasonEpisodes.forEach(ep => allEpisodes.push(ep));
          animeSeasonItems.push({
            seasonNum: season.season_number,
            season_number: season.season_number,
            name: sData.name || season.name || `Season ${season.season_number}`,
            airDate: sData.air_date || season.air_date || '',
            cover: (sData.poster_path || season.poster_path) ? `https://image.tmdb.org/t/p/w500${sData.poster_path || season.poster_path}` : '',
            episodes: seasonEpisodes
          });
        } catch(e) {}
      }
      selectedTmdb.episodes = allEpisodes;
      selectedTmdb.totalEpisodes = allEpisodes.length;
      selectedTmdb.seasons = seasons.length;
      selectedTmdb.seasonsInfo = animeSeasonItems;
      selectedTmdb.animeSeasonItems = selectedTmdb.isAnime ? animeSeasonItems : [];
    } else if (selectedTmdb.isAnime) {
      await hydrateAnimeTitleVariants(selectedTmdb);
    }

    // Show selected preview
    resultsDiv.innerHTML = '';
    const selectedArea = document.getElementById("tmdb-selected-area");
    const coverThumb = d.poster_path ? `https://image.tmdb.org/t/p/w185${d.poster_path}` : '';
    const epInfo = type === "tv" ? `<div class="tmdb-selected-detail">${selectedTmdb.seasons} season${selectedTmdb.seasons > 1 ? 's' : ''} · ${selectedTmdb.totalEpisodes} episodes</div>` : '';
    selectedArea.style.display = "block";
    selectedArea.innerHTML = `<div class="tmdb-selected">
      ${coverThumb ? `<img src="${coverThumb}">` : ''}
      <div class="tmdb-selected-info">
        <div class="tmdb-selected-title">${escHtml(title)} ${year ? '(' + year + ')' : ''}</div>
        <div class="tmdb-selected-detail">${escHtml(genres)}</div>
        ${epInfo}
        <button class="tmdb-clear" onclick="clearSelection()">Clear selection</button>
      </div>
    </div>`;
    showModalStatusPicker();
    document.getElementById("tmdb-search-area").style.display = "none";
    setModalBackBtn(true);
  } catch(e) {
    resultsDiv.innerHTML = '<div class="cover-search-msg">Failed to load details. Try again.</div>';
  }
}

function clearSelection() {
  selectedTmdb = null;
  document.getElementById("tmdb-selected-area").style.display = "none";
  document.getElementById("tmdb-selected-area").innerHTML = "";
  hideModalStatusPicker();
  document.getElementById("tmdb-search-area").style.display = "block";
  setModalBackBtn(false);
}

