const DISCOVER_UNIVERSAL_SEARCH_DEBOUNCE_MS = 140;
const DISCOVER_UNIVERSAL_SEARCH_LIMIT = 24;
const DISCOVER_TVMAZE_MATCH_LIMIT = 6;

